INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2be680f5-d221-59a6-a929-4e7dcf4a37f9', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 3, 3, 'የተሰነጠቀ ሰኰና ያለውንና የሚያመሰኳውን እንስሳ ሁሉ ብሉ።'),
  ('332181f6-4b6a-54dc-a91a-6bde4792edfc', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 4, 4, 'ነገር ግን ከሚያመሰኩት ፥ ሰኰናቸውም ስንጥቅ ከሆነው ከእነዚህ አትበሉም፤ ግመል ያመሰኳል፤ ነገር ግን ሰኰናው ስላልተሰነጠቀ ለእናንተ ርኩስ ነው።'),
  ('365af678-9264-5bcb-a276-b0088842f3a8', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 5, 5, 'ጥንቸል ያመሰኳል፤ ነገር ግን ሰኰናው ስላልተሰነጠቀ ይህ ለእናንተ ርኩስ ነው።'),
  ('1aeed5e6-34fd-5262-af66-240401aecb91', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 6, 6, 'ሽኮኮ ያመሰኳል፤ ነገር ግን ሰኰናው ስላልተሰነጠቀ ለእናንተ ርኩስ ነው።'),
  ('07251b2f-3e84-5745-a556-12cd01bc72bd', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 7, 7, 'እርያም ሰኰናው ተሰንጥቆአል፤ ነገር ግን ስለማያመሰኳ ለእናንተ ርኩስ ነው።'),
  ('31a2e5ab-125b-573e-aad8-4fd0cebfa2db', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 8, 8, 'የእነዚህን ሥጋ አትበሉም፤ በድናቸውንም አትነኩም፤ ለእናንተ ርኩሳን ናቸው።'),
  ('89722b2a-9602-5c84-abd1-2bc32f6bdeed', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 9, 9, '“በውኃ ውስጥ ከሚኖሩት ሁሉ እነዚህን ትበላላችሁ፤ በውኆች፥ በባሕሮችም፥ በወንዞችም ውስጥ ከሚኖሩት ሁሉ ክንፍና ቅርፊት ያላቸውን ትበላላችሁ።'),
  ('720b73e5-d296-5814-a13a-ea2e2d41aecb', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 10, 10, 'በውኆች ውስጥ ከሚንቀሳቀሱ፥ በውኆች ውስጥ የሕይወት ነፍስ ከአላቸው ሁሉ፥ በባሕሮችና በወንዞች ውስጥ ክንፍና ቅርፊት የሌላቸው ሁሉ በእናንተ ዘንድ የተጸየፉ ናቸው።'),
  ('b48362a5-0764-5c06-aeec-3fa93d5b0193', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 11, 11, 'በእናንተም ዘንድ የተጸየፉ ይሆናሉ። ሥጋቸውንም አትበሉም፤ በድናቸውንም ትጸየፋላችሁ።'),
  ('8bd0e87b-5599-5696-aa4a-480dea342b07', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 12, 12, 'ክንፍና ቅርፊትም የሌላቸው በውኃ ውስጥ የሚኖሩት ሁሉ ለእናንተ ርኩሳን ናቸው።'),
  ('2846275b-a963-5b73-ac1c-8efbb399310d', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 13, 13, '“ከወፎችም ወገን የምትጸየፉአቸው እነዚህ ናቸው፤ አይበሉም፤ የተጸየፉ ናቸው፤ ንስር፥ ገዴ አሞራ፥ ዓሣ አውጭ፥'),
  ('b9be58cb-b7e8-5339-ae5f-0f4314116e41', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 14, 14, 'ጭላት፥ ጭልፊት፥ አንጭ አሞራ በየወገኑ፤'),
  ('f099964a-9e0d-5620-aeb8-75f6aaced1c4', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 15, 15, 'ቁራ ሁሉ በየወገኑ፤'),
  ('c730921f-b3c2-5982-a7df-da7267ade132', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 16, 16, 'ሰጎን በየወገኑ፤ ጠለቋ፥ ዝዪ፥ በቋል በየወገኑ፤'),
  ('1e017bf3-2398-5fbd-a8ca-6f83b96be32e', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 17, 17, 'ጉጉት፥ እርኩም፥ ጋጋኖ፥'),
  ('7980ed57-4130-5fed-a86c-567352450ebb', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 18, 18, 'የውኃ ዶሮ፥ ይብራ፥ ጥምብ አንሣ አሞራ፥'),
  ('1d89f186-a898-532b-acdc-065dd86b7d95', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 19, 19, 'ሸመላ፥ ሳቢሳ በየወገኑ፤ ጅንጅላቴ ወፍ፥ የሌሊት ወፍ።'),
  ('8514030c-dda7-526b-afe1-b6a6e1ccf537', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 20, 20, '“የሚበርርም፥ በአራት እግሮችም የሚሄድ ተንቀሳቃሽ ሁሉ ለእናንተ ርኩስ ነው።'),
  ('9e019149-44c9-52a2-a6c5-23bdd5632662', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 21, 21, 'ነገር ግን ከሚበርሩት፥ አራትም እግሮች ካሉአቸው፥ ከእግሮቻቸውም በላይ በምድር ላይ የሚዘልሉባቸው ጭኖች ካሉአቸው ተንቀሳቃሾች እነዚህን ትበላላችሁ፤'),
  ('0d88241d-b783-5b62-a59d-9ac27f3d1583', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 22, 22, 'ከእነርሱም እነዚህን አትበሉም፤ ኩብኩባ የሚመስለውም፥ ፌንጣ የሚመስለውም፥ አሸን የሚመስለውም፥ አንበጣ የሚመስለውም።'),
  ('7918f3d5-02a7-5e25-a2ea-294f71c9ec41', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 23, 23, 'የሚበርር፥ አራትም እግሮች ያሉት ተንቀሳቃሽ ሁሉ ለእናንተ ርኩስ ነው።'),
  ('36855e80-1780-5498-a606-6693892dba7d', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 24, 24, '“በእነዚህም ርኩስ ትሆናላችሁ፤ የእነርሱንም በድን የሚነካ ሁሉ እስከ ማታ ርኩስ ነው።'),
  ('ca21edd9-582e-52be-a542-cab42280ab16', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 25, 25, 'ከእነርሱም በድን የሚያነሣ ሁሉ ልብሱን ይጠብ፤ እስከ ማታም ርኩስ ነው።'),
  ('985c7488-4343-5f85-ad77-565971de3ddf', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 26, 26, 'ሰኰናም ያለው፥ ነገር ግን ሰኰናው ያልተሰነጠቀ፥ የማያመሰኳም እንስሳ ሁሉ ለእናንተ ርኩስ ነው፤ እርሱን የሚነካ ሁሉ ርኩስ ነው።'),
  ('aa6ab32c-f4bd-51c1-a69b-63a26e281eb0', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 27, 27, 'በአራት እግሮቹ ከሚሄድ እንስሳ ሁሉ በመዳፎቹ ላይ የሚሄድ ለእናንተ ርኩስ ነው፤ የእርሱን በድን የሚነካ ሁሉ እስከ ማታ ርኩስ ነው።'),
  ('27f31450-5c3b-555a-aee7-683546305a37', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 28, 28, 'በድናቸውንም የሚያነሣ ልብሱን ይጠብ፤ እስከ ማታም ርኩስ ነው። እነርሱም በእናንተ ዘንድ ርኩሳን ናቸው።'),
  ('02098724-9f2e-5b7e-afed-f9321ccacf88', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 29, 29, '“በምድር ላይም ከሚንቀሳቀስ ተንቀሳቃሽ እነዚህ ለእናንተ ርኩሳን ናቸው፤ ሙጭልጭላ፥ አይጥ፥ እንሽላሊት በየወገኑ፥'),
  ('8fe7abad-7d25-578d-ad9a-f2a3d7856cda', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 30, 30, 'ኤሊ፥ አዞ፥ ገበሎ፥ አርጃኖ፥ እስስት።'),
  ('4e57ec80-d318-50dd-aae8-a39712841a96', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 31, 31, 'ከሚንቀሳቀሱት ሁሉ በእናንተ ዘንድ ርኩሳን የሚሆኑ እነዚህ ናቸው። ከእነርሱም በድናቸውን የሚነካ ሁሉ እስከ ማታ ርኩስ ነው።'),
  ('1a20593c-9d96-50bb-a0eb-46281c92fb5e', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 32, 32, 'ከእነርሱም በድናቸው በምንም ላይ ቢወድቅ እርሱ ርኩስ ነው፤ የዕንጨት ዕቃ ወይም ልብስ ወይም ቍርበት ወይም ከረጢት ቢሆን የሚሠራበት ዕቃ ሁሉ እርሱን በውኃ ውስጥ ይንከሩት፤ እስከ ማታም ርኩስ ነው፤ ከዚያም በኋላ ንጹሕ ይሆናል።'),
  ('46e07693-1ace-5377-abbf-caa41d26be84', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 33, 33, 'ከእነርሱም አንዳች በውስጡ የወደቀበትን የሸክላውን ዕቃ ሁሉ ስበሩት፤ በውስጡም ያለው ሁሉ ርኩስ ነው።'),
  ('f4899fb5-7b0b-5d9d-a8a9-118a798fcffa', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 34, 34, 'በእርሱ ውስጥ ያለው፤ ውኃም የሚፈስስበት፥ የሚበላ መብል ሁሉ ርኩስ ነው፤ በዚህም ዕቃ ሁሉ ያለው የሚጠጣ መጠጥ ሁሉ ርኩስ ነው።'),
  ('f887560f-7fc6-5162-a6a0-abd79a9b8c58', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 35, 35, 'ከእነዚህም በድን የሚወድቅበት ሁሉ ርኩስ ነው፤ እቶን ወይም ምድጃ ቢሆን ይሰባበራል፤ ርኩሳን ናቸውና፤ ለእናንተ ርኩሳን ይሆናሉ።'),
  ('c581fa5e-96d4-5ff0-a374-766462dedbf0', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 36, 36, 'ነገር ግን ምንጩ፥ ጉድጓዱም፥ የውኃውም ኵሬ ንጹሓን ናቸው፤ በድናቸውን ግን የሚነካ ርኩስ ነው።'),
  ('7ce24180-f4e7-56b8-af3a-4f023edd7fb2', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 37, 37, 'ከበድናቸውም በሚዘራ ዘር ላይ አንዳች ቢውድቅ እርሱ ንጹሕ ነው።'),
  ('8e3493fd-d0ef-51fc-a42d-2ca93d932dd3', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 38, 38, 'ነገር ግን በዘሩ ላይ ውኃ ቢፈስስበት፥ ከዚህ በኋላ ከበድናቸው አንዳች ቢወድቅበት፥ ለእናንተ ርኩስ ነው።'),
  ('dfdc68eb-796e-5210-a0ca-e00d3341efc7', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 39, 39, '“ለመብል ከሚሆኑላችሁ እንስሳት የሞተ ቢኖር፥ በድኑን የሚነካ ሁሉ እስከ ማታ ርኩስ ነው።'),
  ('5e0380d5-ef4c-5e16-ace7-7291d33474fa', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 40, 40, 'ከበድኑም የሚበላ ልብሱን ያጥባል፤ እስከ ማታም ርኩስ ይሆናል፤ በድኑንም የሚያነሣ፤ ልብሱን ይጠብ፥ እስከ ማታም ርኩስ ነው።'),
  ('a8558462-8e47-5e53-afa1-49f26e3a33a5', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 41, 41, '“በምድርም ላይ የሚንቀሳቀስ ተንቀሳቃሽ አውሬ ሁሉ ለእናንተ ርኩስ ነው፤ አትብሉትም።'),
  ('a011ef6b-3e6e-548a-a71d-7b6155678f49', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 42, 42, 'በሆዱ የሚሳብ፥ በአራትም እግሮች የሚሳብ፥ ብዙ እግሮችም ያሉት፥ በምድርም ላይ የሚንቀሳቀሱ ተንቀሳቃሾች ሁሉ ርኩሳን ናቸውና አትብሉአቸው።'),
  ('0aae45e2-8ba4-517c-ac0a-fc2beac17225', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 43, 43, 'በምድር ላይ በሚንቀሳቀሱ ተንቀሳቃሾች ሁሉ ሰውነታችሁን አታርክሱ፤ በእነርሱም እንዳትረክሱ ሰውነታችሁን አታርክሱባቸው።'),
  ('f6585869-34a7-52bb-a0e9-5005248d237f', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 44, 44, 'እኔ እግዚአብሔር አምላካችሁ ነኝና፤ ሰውነታችሁን ቀድሱ፤ ቅዱሳንም ሁኑ፤ እኔ አምላካችሁ እግዚአብሔር ቅዱስ ነኝና፤'),
  ('19a0d73c-a8d7-532a-a8cd-42521169d2ce', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 45, 45, 'በምድርም ላይ በሚሳብ ተንቀሳቃሽ ሁሉ ሰውነታችሁን አታሳድፉ። እኔ አምላካችሁ እሆን ዘንድ ከግብፅ ምድር ያወጣኋችሁ እግዚአብሔር ነኝ፤ እንግዲህ እኔ ቅዱስ ነኝና እናንተም ቅዱሳን ሁኑ።'),
  ('b259b27b-7b53-5608-a156-e875eb2a812a', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 46, 46, '“የእንስሳና የወፍ፥ በውኃውም ውስጥ የሚንቀሳቀስ የፍጥረት ሁሉ፥ በምድርም ላይ የሚንቀሳቀስ የፍጥረት ሁሉ ሕግ ይህ ነው።'),
  ('55f1f7f0-ff3b-53e7-aa64-f6348c3c0d1a', 'bc7a94a0-d5c4-5eb4-a4c4-d08f5ba9673b', '3b62ea89-e956-5864-aa22-d2b845d3a069', 47, 47, 'በርኩስና በንጹሕ መካከል፥ የሕይወት ነፍስ ካላቸውም በምትበሉትና በማትበሉት መካከል እንድትለዩ ነው።”'),
  ('c467c7b8-18ad-538b-a21e-a03cc3f44cf1', '65bd21c3-7c7e-534a-a03a-71ace77920e4', 'de319bc7-f42b-5bda-ac36-fe8cc21b8b07', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('7e7d6f9a-4a64-58a4-af27-ef719f96addb', '65bd21c3-7c7e-534a-a03a-71ace77920e4', 'de319bc7-f42b-5bda-ac36-fe8cc21b8b07', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ተናገራቸው፦ ሴት ብታረግዝ ወንድ ልጅም ብትወልድ፥ ሰባት ቀን ያህል የረከሰች ናት፤'),
  ('6e434e3a-2465-5664-a1cd-379b3f22fb76', '65bd21c3-7c7e-534a-a03a-71ace77920e4', 'de319bc7-f42b-5bda-ac36-fe8cc21b8b07', 3, 3, 'እንደ ግዳጅዋ ወራት ትረክሳለች። በስምንተኛውም ቀን ልጁ ከሥጋው ሸለፈት ይገረዝ።'),
  ('cff432ff-d8e8-5777-a56c-44aba75e78e4', '65bd21c3-7c7e-534a-a03a-71ace77920e4', 'de319bc7-f42b-5bda-ac36-fe8cc21b8b07', 4, 4, 'ከደምዋም እስክትነጻ ሠላሳ ሦስት ቀን ትቈይ፤ የመንጻቷ ቀንም እስኪፈጸም ድረስ የተቀደሰን ነገር አትንካ፤ ወደ መቅደስም አትግባ።'),
  ('30d09b4a-4478-51df-a7f1-4a49c4db6b80', '65bd21c3-7c7e-534a-a03a-71ace77920e4', 'de319bc7-f42b-5bda-ac36-fe8cc21b8b07', 5, 5, 'ሴት ልጅም ብትወልድ እንደ ግዳጅዋ ወራት ሁለት ሳምንት ያህል የረከሰች ናት፤ ከደምዋም እስክትነጻ ድረስ ስድሳ ስድስት ቀን ትቈይ።'),
  ('3d1ca633-1424-50d9-ace2-6f9b6a2c6b7c', '65bd21c3-7c7e-534a-a03a-71ace77920e4', 'de319bc7-f42b-5bda-ac36-fe8cc21b8b07', 6, 6, '“የመንጻቷ ወራትም በተፈጸመ ጊዜ፥ ለወንድ ልጅ ወይም ለሴት ልጅ፥ የአንድ ዓመት ጠቦት ለሚቃጠል መሥዋዕት፥ የርግብም ግልገል ወይም ዋኖስ ለኀጢአት መሥዋዕት ወደ ምስክሩ ድንኳን ደጃፍ ወደ ካህኑ ታመጣለች።'),
  ('4f221054-6755-514f-a993-8d4e9ee5501b', '65bd21c3-7c7e-534a-a03a-71ace77920e4', 'de319bc7-f42b-5bda-ac36-fe8cc21b8b07', 7, 7, 'ካህኑም በእግዚአብሔር ፊት ያቀርበዋል፤ ያስተሰርይላትማል፤ ከደምዋም ፈሳሽ ትነጻለች። ወንድ ወይም ሴት ለምትወልድ ሴት ሕጉ ይህ ነው።'),
  ('41722eea-5b4c-5e68-a3b0-a0f77d515990', '65bd21c3-7c7e-534a-a03a-71ace77920e4', 'de319bc7-f42b-5bda-ac36-fe8cc21b8b07', 8, 8, 'ጠቦት ለማምጣት የሚበቃ ገንዘብ በእጅዋ ባይኖራት ሁለት ዋኖሶች፥ ወይም ሁለት የርግብ ግልገሎች፥ አንዱን ለሚቃጠል መሥዋዕት፥ ሌላውንም ለኀጢአት መሥዋዕት ታቀርባለች፤ ካህኑም ያስተሰርይላታል፤ እርስዋም ትነጻለች።”'),
  ('d6479ba9-d5bd-5ea6-a955-c5dece8c83e2', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 1, 1, 'እግዚአብሔር ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('01a334d8-c3c5-5890-a7c2-199ea05c8370', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 2, 2, '“ሰው በሥጋው ቆዳ ላይ እባጭ ብትወጣበት፥ ብትነጣም፥ በሥጋውም ቆዳ እንደ ለምጽ ደዌ ብትመስል፥ ወደ ካህኑ ወደ አሮን ወይም ከካህናቱ ልጆች ወደ አንዱ ያምጡት።'),
  ('d6abcc36-4f0d-5eb4-a5bb-8406c49a46ad', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 3, 3, 'ካህኑም በሥጋው ቆዳ ያለችውን ያችን ደዌ ይያት፤ ጠጕሯም ተለውጣ ብትነጣ በሥጋው ቆዳ ያለች የዚያች ደዌ መልክ ቢከፋ፥ ደዌውም ወደ ሥጋው ቆዳ ቢጠልቅ፥ እርስዋ የለምጽ ደዌ ናት፤ ካህኑም አይቶ፦ ‘ርኩስ ነው’ ይበለው።'),
  ('d2bbd0d5-81ce-597e-aad6-5e670504a378', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 4, 4, 'ቋቍቻውም በሥጋው ቆዳ ላይ ቢነጣ፥ ከቆዳውም የጠለቀ ባይመስል፥ ጠጕሩም ባይነጣ፥ ካህኑ የታመመውን ሰው ሰባት ቀን ይዘጋበታል።'),
  ('9c1854f3-e437-5c81-a8ed-092a3b7a6d58', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 5, 5, 'በሰባተኛውም ቀን ካህኑ ያችን ደዌ ይያት፤ እነሆም፥ ያች ደዌ በፊት እንደ ነበረች ብትሆን፥ በቆዳውም ላይ ባትሰፋ፥ ካህኑ ሰባት ቀን ደግሞ ይለየዋል።'),
  ('d9a7a940-b434-511f-ac53-7eb4a75f3e43', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 6, 6, 'ደግሞ በሰባተኛው ቀን ካህኑ ያየዋል፤ እነሆም፥ ያች ደዌ ብትከስም፥ በቆዳውም ላይ ባትሰፋ፥ ካህኑ፦ ‘ንጹሕ ነው’ ይለዋል፤ ምልክት ነውና፥ ልብሱንም አጥቦ ንጹሕ ይሆናል።'),
  ('187c8aa5-9d33-5ed5-ac0a-b81cf8f96b38', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 7, 7, 'ስለ መንጻቱ በካህኑ ዘንድ ከታየ በኋላ ምልክቱ በቆዳው ላይ ቢሰፋ፥ እንደገና ሊታይ ወደ ካህኑ ይቀርባል።'),
  ('2a9e2446-dd3d-5d3c-aad6-365d449a0f6e', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 8, 8, 'ካህኑም ያያል፤ እነሆም፥ ምልክቱ በቆዳው ላይ ቢሰፋ ካህኑ፦ ‘ርኩስ ነው’ ይለዋል፤ ለምጽ ነውና።'),
  ('aaf5c857-b626-5e92-a158-1245b3c7a7fb', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 9, 9, '“የለምጽ ደዌ በሰው ላይ ቢወጣ እርሱ ወደ ካህኑ ይሄዳል።'),
  ('15f8a167-a4d3-5148-a94a-07a51c52c904', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 10, 10, 'ካህኑም ያየዋል፤ እነሆም፥ በቆዳው ላይ ነጭ እባጭ ቢሆን፥ ጠጕሩም ተለውጦ ቢነጣ፥ ሥጋውም በእባጩ ውስጥ ቢያዥ፥'),
  ('c9253573-5173-5a2b-a5cd-3056be49ccc5', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 11, 11, 'እርሱ በሥጋው ቆዳ ላይ አሮጌ ለምጽ ነው፤ ካህኑም፦ ‘ርኩስ ነው’ ይለዋል፤ እርሱ ርኩስ ነውና ይለየዋል።'),
  ('37b9077d-2c86-5fae-ad65-114984dde581', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 12, 12, 'ለምጹም በቆዳው ላይ ሰፍቶ ቢወጣ፥ ለምጹም የታመመውን ሰው ቆዳውን ሁሉ ከራሱ እስከ እግሮቹ ድረስ እንደ ከደነው ለካህኑ ቢመስለው፤'),
  ('6fd32757-3942-5fcd-a39d-45f14a320830', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 13, 13, 'ካህኑ ያየዋል፤ እነሆም፥ ለምጹ ቆዳውን ሁሉ ቢከድን የታመመውን ሰው፦ ካህኑ ‘ንጹሕ ነህ’ ይለዋል፤ ሁለመናው ተለውጦ ነጭ ሆኖአልና ንጹሕ ነው።'),
  ('37524335-08d0-58ae-ae2f-bfd19624c429', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 14, 14, 'ደዌው በታየበት ቀን ጤነኛው ቆዳ ርኩስ ይሆናል።'),
  ('0f5c5f27-d060-584c-aef1-eefc4218c39f', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 15, 15, 'ካህኑም ጤነኛውን ቆዳ አይቶ፦ ‘ርኩስ ነው’ ይለዋል፤ ስለዚህ ለምጽ ነውና ርኩስ ነው።'),
  ('74ee0fda-2536-519a-ab7e-e670add3a822', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 16, 16, 'ጤነኛው ቆዳ ተመልሶ ቢነጣ እንደገና ወደ ካህኑ ይመጣል።'),
  ('8d9d0b91-3b9e-5851-a67a-b1a2c01b1e38', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 17, 17, 'ካህኑም ያየዋል፤ እነሆም፥ ደዌው ቢነጣ ካህኑ የታመመውን፦ ‘ንጹሕ ነው’ ይለዋል፤ ንጹሕ ነውና።'),
  ('fb7d5fed-1306-5870-ad59-08e00b2b7053', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 18, 18, '“በሥጋውም ቆዳ ላይ ቍስል ቢሆንና ቢሽር፥'),
  ('c423441a-1900-58d0-a024-c185ce948fa1', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 19, 19, 'በቍስሉም ስፍራ ነጭ እባጭ ወይም ቀላ ያለ ቋቍቻ ቢወጣ፥ በካህኑ ዘንድ ይታያል።'),
  ('4a485554-5bff-5af4-a55a-1b7ed8f90c8b', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 20, 20, 'ካህኑም ያያል፤ እነሆም፥ ወደ ቆዳው ውስጥ ጠልቆ ቢታይ፥ ጠጕሩም ተለውጦ ቢነጣ፥ ካህኑ፦ ‘ርኩስ ነው’ ይለዋል፤ የለምጽ ደዌ ነው፤ ከቍስሉ ውስጥ ወጥቶአል።'),
  ('6141a831-ef59-51a6-a005-b9e93527b9f0', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 21, 21, 'ካህኑም ቢያየው፥ ነጭም ጠጕር ባይኖርበት፥ ወደ ቆዳውም ውስጥ ባይጠልቅ ነገር ግን ቢከስም፥ ካህኑ ሰባት ቀን ይለየዋል።'),
  ('6b23e9d2-8f9d-559e-a900-5b3cb264addd', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 22, 22, 'በቆዳውም ላይ ቢሰፋ፥ ካህኑ፦ ‘ርኩስ ነው’ ይለዋል፤ የለምጽ ደዌ ነው፤ በእትራቱ ላይ ወጥቶአልና።'),
  ('6de2d4b4-02fa-5d1f-af82-c661d76e9981', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 23, 23, 'ያች ደዌ ግን በስፍራዋ ብትቆም፥ ባትሰፋም፥ የቍስል እትራት ናት፤ ካህኑም፦ ‘ንጹሕ ነው’ ይለዋል።'),
  ('0fa1bfc9-ca42-5528-ad5f-02193c991fd1', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 24, 24, '“በሥጋውም ቆዳ የእሳት ትኩሳት ቢኖርበት፥ በተቃጠለውም ስፍራ ነጭ፥ ወይም ቀላ ያለ ቋቍቻ ቢታይ፥'),
  ('6dace667-a747-57b6-a832-9c632af166c0', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 25, 25, 'ካህኑ ያየዋል፤ እነሆም፥ በቋቁቻው ጠጕሩ ተለውጦ ቢነጣ፥ ወደ ቆዳውም ውስጥ ቢጠልቅ፥ ለምጽ ነው፤ ከተቃጠለውም ስፍራ ወጥቶአል፤ ካህኑም፦ ‘ርኩስ ነው’ ይለዋል፤ የለምጽ ደዌ ነውና።'),
  ('27afbef6-a420-53d4-a3a2-0ac9a987b7c7', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 26, 26, 'ካህኑም ቢያየው፥ በቋቍቻውም ነጭ ጠጕር ባይኖር፥ ወደ ቆዳውም ባይጠልቅ፥ ነገር ግን ቢከስም፥ ካህኑ ሰባት ቀን ይለየዋል።'),
  ('d6f74c70-2264-5312-af1c-b6c74a262beb', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 27, 27, 'ካህኑም በሰባተኛው ቀን ያየዋል፤ በቆዳውም ላይ ቢሰፋ ካህኑ፦ ‘ርኩስ ነው’ ይለዋል፤ የለምጽ ደዌ ነውና በእትራቱ ላይ ወጥቶአል።'),
  ('e5d779e8-27bd-5873-acfa-c5e1cef107b8', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 28, 28, 'ቋቍቻውም በስፍራው ላይ ቢቆም፥ በቆዳውም ላይ ባይሰፋ፥ ነገር ግን ቢከስም፥ የትኩሳት እባጭ ነው፤ የትኩሳትም ጠባሳ ነውና ካህኑ፦ ‘ንጹሕ ነው’ ይለዋል።'),
  ('0510ff69-821b-53f5-a2cf-212709ba57a0', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 29, 29, '“ማናቸውም ወንድ ወይም ሴት በራሱ ወይም በአገጩ የለምጽ ደዌ ቢኖርበት፥ ካህኑ የለምጹን ደዌ ያያል፤'),
  ('cfe2f3af-198e-5e35-a77f-bab03f747bda', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 30, 30, 'እነሆም፥ ወደ ቆዳው ቢጠልቅ፥ በውስጡም ቀጭን ብጫ ጠጕር ቢኖርበት፥ ካህኑ፦ ‘ርኩስ ነው’ ይለዋል፤ ቈረቈር ነው፤ የራስ ወይም የአገጭ ለምጽ ነው።'),
  ('ed81409c-a6bf-55df-ab46-65613f5af91a', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 31, 31, 'ካህኑም የቈረቈሩን ደዌ ቢያይ፥ ወደ ቆዳውም ባይጠልቅ፥ ጥቁርም ጠጕር ባይኖርበት፥ ካህኑ የቈረቈር ደዌ ያለበትን ሰው ሰባት ቀን ይለየዋል።'),
  ('2d0e9ba9-7daa-5bf8-a60e-62d8c9ba8903', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 32, 32, 'ካህኑም በሰባተኛው ቀን ደዌውን ያያል፤ እነሆም፥ ቈረቈሩ ባይሰፋ፥ በውስጡም ብጫ ጠጕር ባይኖር፥ የቈረቈሩም መልክ ወደ ቆዳው ባይጠልቅ፤ ይላጫል፤'),
  ('d9b949df-9280-5f8b-a3ea-e943964e5cc6', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 33, 33, 'ቈረቈሩ ግን አይላጭም፤ ካህኑም ቈርቈር ያለበትን ሰው ሰባት ቀን ደግሞ ይለየዋል።'),
  ('99a0c67d-0ed0-54ee-ad97-41336cfb4242', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 34, 34, 'ካህኑም በሰባተኛው ቀን ቈረቈሩን ያያል፤ እነሆም፥ ከተላጨ በኋላ ቈረቈሩ በቆዳው ላይ ባይሰፋ፥ መልኩም ወደ ቆዳው ባይጠልቅ፥ ካህኑ፦ ‘ንጹሕ ነው’ ይለዋል፤ ልብሱን አጥቦ ንጹሕ ይሆናል።'),
  ('1764528b-f109-5f7d-ac07-bcd3092ad9c2', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 35, 35, 'ከነጻ በኋላ ግን ቈረቈሩ በቆዳው ላይ ቢሰፋ፥ ካህኑ ያየዋል፤'),
  ('07319733-1f78-5552-af71-7440757b2d98', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 36, 36, 'እነሆም፥ ቈረቈሩ በቆዳው ላይ ቢሰፋ ካህኑ ብጫውን ጠጕር አይፈልግም፤ ርኩስ ነውና።'),
  ('4471143d-9270-599e-a8ab-c49d15063c0c', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 37, 37, 'ቈረቈሩ ግን ፊት እንደ ነበረ በቦታው ቢኖር፥ ጥቁርም ጠጕር ቢበቅልበት፥ ቈረቈሩ ሽሮአል፤ እርሱም ንጹሕ ነው፤ ካህኑም፦ ‘ንጹሕ ነው’ ይለዋል።'),
  ('5d014bcb-4ebf-5f27-a28b-47c573758e72', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 38, 38, '“ማናቸውም ወንድ ወይም ሴት በሥጋው ቆዳ ላይ ነጭ ቋቍቻ ቢኖርበት፥'),
  ('08ce4178-37e1-5f3e-adc5-4997fddc166c', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 39, 39, 'ካህኑ ያያል፤ እነሆም፥ በሥጋቸው ቆዳ ላይ ያለው ቋቍቻ ፈገግ ቢል አጓጐት ነው፤ ከቆዳው ውስጥ ወጥቶአል፤ ንጹሕ ነው።'),
  ('872adcec-150d-5aa4-a339-773f51359655', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 40, 40, '“የሰውም ጠጕር ከራሱ ቢመለጥ እርሱ በራ ነው፤ ነገር ግን ንጹሕ ነው።'),
  ('60c8d361-e24c-538b-ae2f-4bdde88b0c88', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 41, 41, 'ጠጕሩ ከግንባሩ ቢመለጥ እርሱ ራሰ በራ ነው፤ ነገር ግን ንጹሕ ነው።'),
  ('a0e6dcc7-6b18-56e7-aafa-dc0495d54f99', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 42, 42, 'በቡሀነቱ ወይም በራሰ በራነቱ ነጭ፥ ወይም ቀላ ያለ ደዌ ቢኖርበት፥ እርሱ ከቡሀነቱ ወይም ከራሰ በራነቱ የወጣ ለምጽ ነው።'),
  ('45b520cb-6145-5c7f-ad28-d12d0285e3e5', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 43, 43, 'ካህኑም ያየዋል፤ እነሆም፥ የደዌው እብጠት በሥጋው ቆዳ ላይ የሆነ ለምጽ መስሎ፥ በቡሀነቱ ወይም በራሰ በራነቱ ነጭ ወይም ቀላ ያለ ቢሆን፥'),
  ('788e768a-52c6-5616-a466-b6b8876e1a3e', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 44, 44, 'ለምጻም ሰው ነው፤ ርኩስ ነው፤ ካህኑ፦ በርግጥ ‘ርኩስ ነው’ ይለዋል፤ ደዌው በራሱ ነው።'),
  ('40180dfe-2dae-5972-a774-ec97df7c1d95', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 45, 45, '“የለምጽ ደዌ ያለበት ሰው ልብሱ የተቀደደ ይሁን፤ ራሱም የተገለጠ ይሁን፤ ከንፈሩንም ይሸፍን፤ ርኩስ ይባላል።'),
  ('87ccc030-2b01-5430-a7ee-5a1d5cf818bc', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '88849ca6-bda2-53a6-a233-7577a5f80219', 46, 46, 'ደዌው ባለበት ዘመን ሁሉ ርኩስ ይሆናል፤ እርሱ ርኩስ ነው፤ ብቻውን ይቀመጣል፤ መኖሪያውም ከሰፈር በውጭ ይሆናል።'),
  ('3cc37ba7-f27c-55c2-a406-6f8d069e00d9', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 1, 47, '“የለምጽም ደዌ በልብስ ላይ ቢሆን፥ ልብሱም የበግ ጠጕር ወይም የተልባ እግር ቢሆን፥'),
  ('a99df232-dd30-51e3-a360-389e9c2ba381', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 2, 48, 'በድሩ ወይም በማጉ ላይ ቢሆን፥ የበግ ጠጕር ወይም የተልባ እግር ቢሆን፥ ቆዳ ወይም ከቆዳ የሚደረግ ነገር ቢሆን፥'),
  ('de2c1db2-2bdd-5507-aad3-8e9a8999d239', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 3, 49, 'ደዌው በልብሱ ወይም በቆዳው ወይም በድሩ ወይም በማጉ ወይም ከቆዳ በሚደረገው ነገር አረንጓዴ ወይም ቀይ ቢሆን፥ የለምጽ ደዌ ነው፤ ለካህኑ ያሳያል።'),
  ('d40decac-306d-5134-a882-3f43ca04c6cc', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 4, 50, 'ካህኑም ደዌውን አይቶ ደዌው ያለበትን ነገር ሰባት ቀን ይለየዋል።'),
  ('b7f069a1-5fa5-531d-a042-19bdc5c1ece7', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 5, 51, 'በሰባተኛውም ቀን ደዌውን ያያል፤ ደዌውም በልብስ ላይ ወይም በድሩ ወይም በማጉ ወይም በቆዳው ወይም ከቆዳው በሚደረግ ነገር ቢሰፋ፥ ደዌው እየፋገ የሚሄድ ለምጽ ነው፤ ርኩስ ነው።'),
  ('c6c9edf7-6c96-5d9d-ad4d-7b6af9a7d083', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 6, 52, 'ልብሱን ያቃጥላል፤ ድሩ ወይም ማጉ የበግ ጠጕር ወይም የተልባ እግር ቢሆን ወይም ከቆዳ የተደረገ ቢሆን፥ ደዌ ያለበት ሁሉ እየፋገ የሚሄድ ለምጽ ነውና በእሳት ይቃጠላል።'),
  ('a629c807-9c72-5c21-a668-2e4c808c0169', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 7, 53, '“ካህኑ ቢያይ፥ እነሆም፥ ደዌው በድሩ ወይም በማጉ ወይም ከቆዳ በተደረገ ነገር ቢሆን በልብሱ ላይ ባይሰፋ፥'),
  ('d3d3ef64-dc09-5bb1-a7cd-2560ed5e2ff6', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 8, 54, 'ካህኑ ደዌ ያለበቱ ነገር እንዲታጠብ ያዝዛል፤ ሌላም ሰባት ቀን ይለየዋል።'),
  ('e7387149-92ed-5b1b-a5a8-cc5316fb39bb', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 9, 55, 'ደዌውም ከታጠበ በኋላ ካህኑ ያየዋል፤ እነሆም፥ ደዌው መልኩን ባይለውጥ፥ ባይሰፋም፥ ርኩስ ነው፤ በእሳት ያቃጥሉታል፤ በልብሱም ውስጥ በማጉም፥ በድሩም ወጥቶአልና።'),
  ('1dba8276-7bcf-5e47-a347-7e4030073794', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 10, 56, '“ካህኑም ቢያይ፥ እነሆ፥ ደዌው ከታጠበ በኋላ ቢከስም፥ ከልብሱ ወይም ከድሩ ወይም ከማጉ ወይም ከቆዳው ይቅደደው።'),
  ('0c5e9ec1-9c1e-5515-aa2f-168d3320bb26', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 11, 57, 'በልብሱም ወይም በድሩ ወይም በማጉ ወይም ከቆዳ በተደረገ ነገር ላይ ደግሞ ቢታይ፥ የወጣ ለምጽ ነው፤ ደዌው ያለበትን ነገር ያቃጥሉት።'),
  ('c3fe791c-cbde-557b-a8f6-512576e55335', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 12, 58, 'ልብሱ ወይም ድሩ ወይም ማጉ ወይም ከቆዳ የተደረገው ነገር ከታጠበ በኋላ ደዌው ቢለቅቀው ሁለተኛ ጊዜ ይታጠባል፤ ንጹሕም ይሆናል።'),
  ('9ca27afc-c066-5117-a192-829e4f371db3', 'fbf1a430-e4f6-582e-aa89-22ea4be77542', '95172707-0452-5d9f-a9c7-dfb854264106', 13, 59, '“በበግ ጠጕር ልብስ፥ ወይም በተልባ እግር ወይም በድሩ ወይም በማጉ ወይም ከቆዳ በተደረገ ነገር ላይ ቢሆን፥ ንጹሕ ወይም ርኩስ ያሰኝ ዘንድ የለምጽ ደዌ ሕግ ይህ ነው።”'),
  ('930c85e9-ae16-5a1a-a7b9-adc9a5b9406d', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 1, 1, 'እግዚአብሔር ሙሴን እንዲህ ሲል ተናገረው፦'),
  ('33261389-5027-5d90-a75b-7c45fa0e8b4c', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 2, 2, '“ለምጽ ለያዘው ሰው ሕጉ ይህ ነው፤ ከለምጽ በነጻበት ቀን ወደ ካህኑ ይወስዱታል።'),
  ('02c62242-43c1-517a-a285-8a4280581b80', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 3, 3, 'ካህኑም ከሰፈር ወደ ውጭ ይወጣል፤ ካህኑም ያየዋል፤'),
  ('b39c577a-04c9-5b06-ab86-a6a7a23760f4', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 4, 4, 'እነሆም፥ የለምጹ ደዌ ከለምጻሙ ላይ ቢጠፋ፥ ካህኑ ስለሚነጻው ሰው ሁለት ንጹሓን ዶሮዎች በሕይወታቸው፥ የዝግባም ዕንጨት፥ ቀይ ግምጃም፥ ሂሶጵም ያመጣ ዘንድ ያዝዛል።'),
  ('aa53cb4e-1281-53dd-a5ab-70a9b915717e', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 5, 5, 'ካህኑም ከሁለቱ ዶሮዎች አንደኛዋን በሸክላ ዕቃ ውስጥ በምንጭ ውኃ ላይ ያርድ ዘንድ ያዝዛል።'),
  ('84db0694-4297-5a4f-ad21-141d17706711', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 6, 6, 'ያልታረደችውንም ዶሮ፥ ዝግባውንም ዕንጨት፥ ቀዩንም ግምጃ፥ ሂሶጱንም ወስዶ በምንጭ ውኃ ላይ በታረደችው ዶሮ ደም ውስጥ ይነክራቸዋል።'),
  ('38ab8835-ca37-56bc-a18d-834d679cc0c2', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 7, 7, 'ከለምጹም በሚነጻው ሰው ላይ ሰባት ጊዜ ይረጫል፤ ንጹሕም ይሆናል፤ ያልታረደችውን ዶሮ ወደ ሜዳ ይለቅቃታል።'),
  ('d4648a8a-2ba0-55f0-a2cb-a7ccb2b4df79', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 8, 8, 'የነጻውም ሰው ልብሱን ያጥባል፤ ጠጕሩንም ሁሉ ይላጫል፤ በውኃም ይታጠባል፤ ንጹሕም ይሆናል። ከዚያም በኋላ ወደ ሰፈር ይገባል፤ ነገር ግን ከቤቱ በውጭ ሆኖ ሰባት ቀን ይቀመጣል።'),
  ('e1bee06a-7d72-5c94-aff6-09d7f4478860', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 9, 9, 'በሰባተኛውም ቀን ጠጕሩን ሁሉ ይላጫል፤ ራሱንም፥ ጢሙንም፥ ቅንድቡንም፥ የገላውንም ጠጕር ሁሉ ይላጫል፤ ልብሱንም፥ ገላውንም በውኃ ያጥባል፤ ንጹሕም ይሆናል።'),
  ('7b02402b-5966-5bf6-ac7e-6bec10e1c165', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 10, 10, '“በስምንተኛው ቀን ነውር የሌለባቸውን፥ ዓመት የሞላቸውን ሁለት ተባት የበግ ጠቦቶች፥ ነውር የሌለባትንም አንዲት የዓመት እንስት የበግ ጠቦት፥ ስለ እህልም ቍርባን ከመስፈሪያው ከዐሥር እጅ ሦስት እጅ የሆነ፥ በዘይት የተለወሰ መልካም የስንዴ ዱቄት፥ አንድ ማሰሮ ዘይትም ይወስዳል።'),
  ('4c13b706-e3c5-5016-a291-cb2626521b1d', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 11, 11, 'የሚያነጻውም ካህን እነዚህን ነገሮች፥ የሚነጻውንም ሰው በምስክሩ ድንኳን ደጃፍ አጠገብ በእግዚአብሔር ፊት ያቀርባቸዋል።'),
  ('8e83d675-c300-5f85-a37d-19c9de8a4bd5', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 12, 12, 'ካህኑም አንዱን ጠቦት ወስዶ ስለ በደል መሥዋዕት ያቀርባል፤ ያንም አንድ ማሰሮ ዘይት ስለ ልዩ ቍርባን በእግዚአብሔር ፊት ይለየዋል።'),
  ('5d613820-1f19-59c4-a212-9364ea94fe6d', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 13, 13, 'የኀጢአትን መሥዋዕትና የሚቃጠለውን መሥዋዕት በሚያርዱበት በተቀደሰው ስፍራ ጠቦቱን ያርዱታል፤ የበደሉ መሥዋዕት ለካህኑ እንደሚሆን፥ እንዲሁ የኀጢአቱ መሥዋዕት ነውና፤ ቅዱሰ ቅዱሳን ነው።'),
  ('e8dd8693-1449-5897-a326-c13f8faf6eea', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 14, 14, 'ካህኑም ከበደል መሥዋዕት ደም ወስዶ የሚነጻውን ሰው የቀኝ ጆሮውን ጫፍ፥ የቀኝ እጁንም አውራ ጣት፥ የቀኝ እግሩንም አውራ ጣት ይቀባዋል።'),
  ('16f8dd3b-9d67-577a-a1af-a38815e4acf9', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 15, 15, 'ካህኑም ከማሰሮው ዘይት ወስዶ በግራ እጁ ውስጥ ያፈስሰዋል።'),
  ('664fd669-3a2f-569c-ac94-85a021970a4d', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 16, 16, 'ካህኑም በግራ እጁ ውስጥ ባለው ዘይት ቀኝ ጣቱን ነክሮ ከዘይቱ በእግዚአብሔር ፊት ሰባት ጊዜ በጣቱ ይረጫል።'),
  ('1a3b4ce7-a77b-503b-af35-669eecfcd28c', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 17, 17, 'ካህኑም በእጁ ውስጥ ከቀረው ዘይት የሚነጻውን ሰው የቀኝ ጆሮውን ጫፍ፥ የቀኝ እጁንም አውራ ጣት፥ የቀኝ እግሩንም አውራ ጣት የበደል መሥዋዕት ደም ባረፈበት ላይ ይቀባዋል።'),
  ('3abbc3bf-def1-5ab7-abf8-0e144183cfba', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 18, 18, 'በካህኑም እጅ ውስጥ የቀረውን ዘይት ካህኑ በሚነጻው ሰው ራስ ላይ ያደርግበታል፤ ካህኑም በእግዚአብሔር ፊት ያስተሰርይለታል።'),
  ('ba672bae-d497-5b6c-a56d-430843ca5303', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 19, 19, 'ካህኑም የኀጢአቱን መሥዋዕት ያቀርባል፤ ካህኑም ከኀጢአቱ ለማንጻት ለሚነጻው ሰው ያስተሰርይለታል፤ ከዚህም በኋላ ካህኑ የሚቃጠለውን መሥዋዕት ያርዳል።'),
  ('459f5f0e-17b6-536c-ab8a-1f7a1d7deccf', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 20, 20, 'ካህኑም የሚቃጠለውን መሥዋዕትና የእህሉን ቍርባን በመሠዊያው ላይ በእግዚአብሔር ፊት ያቀርባል፤ ካህኑም ያስተሰርይለታል፤ እርሱም ንጹሕ ይሆናል።'),
  ('f05a45b0-9bc8-5360-a184-1ba6d27e61b5', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 21, 21, '“ድሃም ቢሆን፥ በእጁም ገንዘብ ባይኖረው፥ ማስተስረያ ይሆንለት ዘንድ አንድ ጠቦት ስለ በደል የመለየት መሥዋዕት፥ ከመስፈሪያውም ከዐሥር እጅ አንድ እጅ የሆነ በዘይት የተለወሰ የስንዴ ዱቄት ለቍርባን፥ አንድ ማሰሮ ዘይትም ያመጣል።'),
  ('24fe896f-1461-5b57-a1d6-c3ae6f858a69', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 22, 22, 'ሁለት ዋኖሶች፥ ወይም ሁለት የርግብ ግልገሎች በእጁ እንዳገኘ አንዲቱን ለኀጢአት መሥዋዕት፥ አንዲቱንም ለሚቃጠል መሥዋዕት ይወስዳል።'),
  ('b6171713-e336-5d0b-a2a6-ecf2d3b118ba', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 23, 23, 'በስምንተኛውም ቀን ያነጹት ዘንድ ወደ ካህኑ ወደ ምስክሩ ድንኳን ደጃፍ በእግዚአብሔር ፊት ያመጣቸዋል።'),
  ('9efc8acb-5cef-5d75-a484-80ad326361a2', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 24, 24, 'ካህኑም የበደሉን መሥዋዕት የበግ ጠቦት የማሰሮውንም ዘይት ይወስዳል፤ በእግዚአብሔርም ፊት ለቍርባን ያቀርበዋል።'),
  ('5d620112-80b3-5701-a4f4-92a28ce4213c', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 25, 25, 'የበደሉንም መሥዋዕት የበግ ጠቦት ያርዳል፤ ካህኑም ከበደሉ መሥዋዕት ደም ወስዶ የሚነጻውን ሰው የቀኝ ጆሮውን ጫፍ፥ የቀኝ እጁንም አውራ ጣት፥ የቀኝ እግሩንም አውራ ጣት ይቀባዋል።'),
  ('ebc678b1-59b8-57f8-ab95-e1dd07ec749f', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 26, 26, 'ካህኑም ከዘይቱ በግራ እጁ ውስጥ ያፈስሰዋል።'),
  ('499dd00b-6cf4-5a70-ae77-ea6b032a3a0f', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 27, 27, 'ካህኑም በግራ እጁ ውስጥ ከአለው ዘይት በቀኝ ጣቱ ሰባት ጊዜ በእግዚአብሔር ፊት ይረጨዋል።'),
  ('f6888559-e67e-56dc-ab79-f9d6ea72cda1', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 28, 28, 'ካህኑም በእጁ ውስጥ ከአለው ዘይት የሚነጻውን ሰው የቀኝ ጆሮውን ጫፍ፥ የቀኝ እጁንም አውራ ጣት፥ የቀኝ እግሩንም አውራ ጣት የበደል መሥዋዕት ደም ባረፈበት ላይ ይቀባዋል።'),
  ('47a64a74-fd04-564b-a5de-443574f5e9ff', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 29, 29, 'በካህኑ እጅ ውስጥ የቀረውን ዘይት በሚነጻው ሰው ራስ ላይ ያደርገዋል፤ ካህኑም በእግዚአብሔር ፊት ያስተሰርይለታል።'),
  ('ed7d79e1-f630-5c80-aa47-2fbfb528a175', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 30, 30, 'በእጁ ከአለው ከዋኖሶች ወይም ከርግብ ግልገሎች አንዱን ያቀርባል።'),
  ('7196572e-fd42-5a72-a580-fcef5ea1b396', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 31, 31, 'አንዲቱን ለኀጢአት መሥዋዕት፥ ሌላዪቱንም ከእህል ቍርባን ጋር ለሚቃጠል መሥዋዕት ያቀርባል፤ ካህኑም ለሚነጻው ሰው በእግዚአብሔር ፊት ያስተሰርይለታል።'),
  ('98a8c291-aa1e-5d07-af33-1e95c6563b1e', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', 'ab16facc-a281-5c63-adbe-1fbfee3e273c', 32, 32, 'ለመንጻቱ የሚያስፈልገውን ነገር ለማያገኝ የለምጽ ደዌ ላለበት ሰው ሕጉ ይህ ነው።”'),
  ('592dc8a6-22dd-511e-ade8-6973f55f76de', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 1, 33, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('f96c226c-0a8c-5468-acb0-e628cd714cc1', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 2, 34, '“ትወርሱአት ዘንድ እኔ ወደምሰጣችሁ ርስት ወደ ከነዓን ምድር በገባችሁ ጊዜ፥ እኔም የለምጽ ደዌ ምልክት በርስታችሁ ምድር ቤቶች ባደረግሁ ጊዜ፥'),
  ('d993963a-42f9-5a35-a00b-053b76af681c', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 3, 35, 'ባለቤቱ መጥቶ ካህኑን፦ ‘ደዌ በቤቴ ውስጥ እንዳለ አይቻለሁ’ ብሎ ይንገረው።'),
  ('3b2a157c-eb8d-5d5f-a4b5-b347fd023a70', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 4, 36, 'ካህኑም በቤቱ ውስጥ ያለው ዕቃ ሁሉ እንዳይረክስ፥ እርሱ የለምጹን ምልክት ለማየት ወደ ቤት ሳይገባ፥ ቤቱን ባዶ እንዲያደርጉት ያዝዛል፤ በኋላም ካህኑ ቤቱን ለማየት ይገባል።'),
  ('be51ea6f-828b-56f9-ace8-7b08b9167ffd', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 5, 37, 'የለምጹንም ምልክት ያያል፤ እነሆም፥ የለምጹ ምልክት በግንቡ ላይ በአረንጓዴና በቀይ ቢዥጐረጐር፥ መልኩም ወደ ግንቡ ውስጥ ቢጠልቅ፥'),
  ('ff9a9001-2d8e-50f4-a002-a20eabfb2c4e', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 6, 38, 'ካህኑ ከቤቱ ውስጥ ወደ ቤቱ በር ወጥቶ ሰባት ቀን ቤቱን ይዘጋዋል።'),
  ('aefaaf72-2b19-531d-a2fd-f92a1eff356f', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 7, 39, 'ካህኑም በሰባተኛው ቀን ተመልሶ ቤቱን ያያል፤'),
  ('9779b087-8ae2-5312-abd8-d1d4582a1eef', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 8, 40, 'እነሆም፥ ደዌው በቤቱ ግንብ ላይ ቢሰፋ፥ ካህኑ ደዌ ያለባቸውን ድንጋዮች እንዲያወጡ፥ ከከተማውም ወደ ውጭ ወደ ረከሰው ስፍራ እንዲጥሉአቸው ያዝዛል።'),
  ('744439af-e20f-5fb5-aedf-4389c55a59ce', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 9, 41, 'ቤቱንም በውስጡ በዙሪያው ያስፍቀዋል፤ የፋቁትንም የምርጊቱን አፈር ከከተማው ወደ ውጭ ወደ ረከሰ ስፍራ ያፈስሱታል።'),
  ('508ff1af-a5c9-5d62-ab45-e25006069089', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 10, 42, 'በእነዚያም ድንጋዮች ስፍራ ሌሎች ድንጋዮችን ያገባሉ፤ ሌላም ጭቃ ወስደው ቤቱን ይመርጉታል።'),
  ('7d273e0a-4604-5a0a-a732-6b40a7fd8eec', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 11, 43, '“ደዌውም ዳግም ቢመለስ፥ ድንጋዮቹም ከወጡ፥ ቤቱም ከተፋቀና ከተመረገ በኋላ በቤቱ ውስጥ ቢሰፋ፥'),
  ('1d550b96-3e76-5613-ad68-9cf96f095d08', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 12, 44, 'ካህኑ ገብቶ ያያል፤ እነሆም፥ ደዌው በቤቱ ውስጥ ቢሰፋ፥ በቤቱ ውስጥ ያለው እየፋገ የሚሄድ ለምጽ ነው፤ ርኩስ ነው።'),
  ('dff45e54-9816-557a-a370-c205a121daa9', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 13, 45, 'ቤቱንም፥ ድንጋዮቹንም፥ ዕንጨቱንም፥ የቤቱንም ምርጊት ሁሉ ያፈርሳል፤ እነርሱንም ከከተማው ወደ ውጭ ወደ ርኩስ ስፍራ ያወጣል።'),
  ('be64416a-434c-5f0c-adf8-a4876acfd697', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 14, 46, 'በተዘጋበትም ጊዜ ሁሉ ወደ ቤቱ የሚገባ እስከ ማታ ድረስ ርኩስ ይሆናል።'),
  ('9e2e0153-3601-5b32-a1a2-eb62c8a762c5', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 15, 47, 'በቤቱም የሚተኛ ልብሱን ያጥባል፤ እስከ ማታም ርኩስ ነው፤ በቤቱም የሚበላ ልብሱን ያጥባል፤ እስከ ማታም ርኩስ ነው።'),
  ('9ff899ac-f519-5135-a1d1-70b39dabe42e', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 16, 48, '“ካህኑም ገብቶ ቢያየው፥ እነሆም፥ ቤቱ ከተመረገ በኋላ ደዌው በቤቱ ውስጥ ባይሰፋ፥ ደዌው ስለ ሻረ ካህኑ ቤቱን፦ ንጹሕ ነው ይለዋል።'),
  ('66305629-f9cd-584c-a3c9-8f045140c1ca', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 17, 49, 'ካህኑም ቤቱን ለማንጻት ሁለት ዶሮዎች፥ የዝግባ ዕንጨት፥ ቀይ ግምጃ፥ ሂሶጵም ይወስዳል።'),
  ('7de9bace-f18f-5244-accc-f9bc884a6ef3', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 18, 50, 'አንደኛዪቱንም ዶሮ በሸክላ ዕቃ ውስጥ ከምንጩ ውኃ በላይ ያርዳል።'),
  ('1e08ac80-fe04-5874-a062-26da574240ca', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 19, 51, 'የዝግባውን ዕንጨት፥ ሂሶጱንም፥ ቀዩንም ግምጃ፥ ደኅነኛዪቱንም ዶሮ ወስዶ በታረደችው ዶሮ ደምና በምንጩ ውኃ ውስጥ ይነክራቸዋል፥ ቤቱንም ሰባት ጊዜ ይረጨዋል።'),
  ('b3c52754-5729-54d4-a58f-4e7c87132fb5', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 20, 52, 'ቤቱንም በዶሮዪቱ ደም በምንጩም ውኃ፥ በደኅነኛዪቱም ዶሮ፥ በዝግባውም ዕንጨት፥ በሂሶጱም፥ በቀዩም ግምጃ ያነጻዋል።'),
  ('edc8abdf-9754-5a66-a45a-f44461ef6784', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 21, 53, 'ደኅነኛዪቱንም ዶሮ ከከተማ ወደ ሜዳ ይሰድዳታል፤ ለቤቱም ያስተሰርይለታል፤ ንጹሕም ይሆናል።'),
  ('80a54ccc-8b9b-52f9-a76c-9b0b6e585936', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 22, 54, '“ይህም ሕግ ነው፤ ለሁሉ ዓይነት ለምጽና የቈረቈር ደዌ ሕጉ ይህ ነው፤'),
  ('b5e7d000-e83e-5105-a754-8d78e456cd85', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 23, 55, 'በልብስና በቤትም ላለ ለምጽ፥'),
  ('f8634e0e-4938-5edc-abe7-e485323e775a', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 24, 56, 'ለዕባጭም፥ ለብጕርም፥ ለቋቍቻም፤'),
  ('32c3f993-c04e-5b97-a3aa-f0c7081bc590', 'c4c3cc84-9215-5cdf-af84-62a0ba1a34ac', '1da81996-7b96-5fa7-ac84-b378b451dbda', 25, 57, 'በሚረክስና በሚነጻ ጊዜ እንዲያስታውቅ ይህ የለምጽ ሕግ ነው።”'),
  ('483f800f-8c8a-5bd4-abf6-83f6d86dcda4', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 1, 1, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፥'),
  ('4dc0b3ec-b0ed-586f-af8c-59fbfdf15d48', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብላችሁ ንገሩአቸው፦ ከሰውነቱ ዘር የሚፈስሰው ሰው ቢኖር ስለሚፈስሰው ነገር ርኩስ ነው።'),
  ('5b0c8e62-f548-5a4b-a713-5dd8335db2c1', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 3, 3, 'ከሰውነቱ ፈሳሽ ለሚፈስሰው ሰው የርኵሰቱ ሕግ ይህ ነው፤ ፈሳሽ የሚፈስሰው ሰው ፈሳሹ እየፈሰሰው በሚኖርበት ጊዜ ሁሉ ርኩስ ነው፤ ፈሳሹ ያረክሰዋል።'),
  ('ffc0e92c-c33c-5107-ab16-469112388244', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 4, 4, 'ፈሳሽ ነገር ያለበት ሰው የሚተኛበት መኝታ ሁሉ ርኩስ ነው፤ የሚቀመጥበትም ነገር ሁሉ ርኩስ ነው።'),
  ('c74a84c4-528d-5ab4-a986-95f7d84299d4', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 5, 5, 'መኝታውንም የሚነካ ሰው ሁሉ ልብሱን ይጠብ፤ በውኃም ሰውነቱን ይታጠብ፤ እስከ ማታም ድረስ ርኩስ ነው።'),
  ('ed657fa5-84c3-5126-a2e8-9a13feeca4e8', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 6, 6, 'ፈሳሽ ነገር ያለበት ሰው በተቀመጠበት ነገር ላይ የሚቀመጥበት ሰው ልብሱን ይጠብ፤ በውኃም ይታጠብ፤ እስከ ማታም ድረስ ርኩስ ነው።'),
  ('bc613367-f3f6-54d0-aabb-bbbefcb31ee3', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 7, 7, 'ፈሳሽ ነገር ያለበትን የሰውን ሥጋ የሚነካ ልብሱን ይጠብ፤ በውኃም ይታጠብ፤ እስከ ማታም ድረስ ርኩስ ነው።'),
  ('601d225c-68b5-5337-ac33-3e53fd823263', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 8, 8, 'ፈሳሽ ነገር ያለበት ሰው በንጹሕ ሰው ላይ ቢተፋ ልብሱን ይጠብ፤ በውኃም ይታጠብ፤ እስከ ማታም ድረስ ርኩስ ነው።'),
  ('5b7d772a-bc12-54c5-aa1b-de2d770e773e', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 9, 9, 'ፈሳሽ ነገር ያለበት ሰው የተቀመጠበት ኮርቻ ሁሉ ርኩስ ነው።'),
  ('74a36cb5-0a86-5cee-aada-b0c62e2b4f9e', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 10, 10, 'ከበታቹም ያለውን ነገር የሚነካ ሁሉ እስከ ማታ ድረስ ርኩስ ነው፤ እነዚህንም ነገሮች የሚያነሣ ሁሉ ልብሱን ይጠብ፤ በውኃም ይታጠብ፤ እስከ ማታም ድረስ ርኩስ ነው።'),
  ('9e9ec2f7-7507-535b-af53-6927e4b9733b', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 11, 11, 'ፈሳሽ ነገር ያለበት ሰው እጁን በውኃ ሳይታጠብ የሚነካው ሁሉ ልብሶቹን ይጠብ፤ በውኃም ይታጠብ፤ እስከ ማታም ርኩስ ነው።'),
  ('a2369689-b9aa-51ee-a640-612fc9a8917b', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 12, 12, 'ፈሳሽ ነገር ያለበት ሰው የሚነካውን የሸክላ ዕቃ ይስበሩት፤ የዕንጨቱንም ዕቃ ሁሉ በውኃ ይጠቡት፤ ንጹሕም ይሆናል።'),
  ('d7f1ece1-a403-5b9c-a128-2f94d7cfce32', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 13, 13, '“ፈሳሽ ነገር ያለበት ሰው ከፈሳሹ ነገር ሲነጻ ስለ መንጻቱ ሰባት ቀን ይቈጥራል፤ ልብሶቹንም ያጥባል፤ ገላውንም በምንጭ ውኃ ይታጠባል፤ ንጹሕም ይሆናል።'),
  ('c16872ca-5a06-5df1-ad60-b89c8fe5c2a9', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 14, 14, 'በስምንተኛውም ቀን ሁለት ዋኖሶች ወይም ሁለት የርግብ ግልገሎች ይዞ ወደ ምስክሩ ድንኳን ደጃፍ በእግዚአብሔር ፊት ያመጣል፤ ለካህኑም ይሰጠዋል።'),
  ('a5176892-f87f-5e8b-a50d-5a9293183328', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 15, 15, 'ካህኑም አንዲቱን ለኀጢአት መሥዋዕት፥ አንዲቱንም ለሚቃጠል መሥዋዕት ያቀርባል፤ ካህኑም በእግዚአብሔር ፊት ስለ ፈሳሹ ነገር ሁሉ ያስተሰርይለታል።'),
  ('ae62aaa8-bace-5f38-a880-3a9eab38f0f5', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 16, 16, '“ማንም ሰው ዘር ከእርሱ ቢወጣ፥ ገላውን ሁሉ በውኃ ይታጠባል፤ እስከ ማታም ርኩስ ነው።'),
  ('7f8fe990-3f64-5210-a50a-121fcfcd770d', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 17, 17, 'ዘር የነካው ልብስ ሁሉ፥ ቍርበትም ሁሉ በውኃ ይታጠባል፤ እስከ ማታም ድረስ ርኩስ ነው።'),
  ('59803f3d-190f-5da6-aae8-d68e9cd2ce40', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 18, 18, 'ሴት ፈሳሽ ከአለበት ወንድ ጋር ብትገናኝ ሁለቱም በውኃ ይታጠባሉ፤ እስከ ማታም ድረስ ርኩሳን ናቸው።'),
  ('99fc88ba-bf0e-5eab-aa7d-707ee8f3a655', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 19, 19, '“ሴት ፈሳሽ ነገር ቢኖርባት፥ በሥጋዋም ያለው ፈሳሽ ነገር ደም ቢሆን፥ በግዳጅዋ ሰባት ቀን ትቀመጣለች፤ የሚነካትም ሁሉ እስከ ማታ ድረስ ርኩስ ነው።'),
  ('a5da1d39-4c45-51ee-a146-215195146e3f', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 20, 20, 'በግዳጅም ሳለች የምትተኛበት ነገር ሁሉ ርኩስ ነው፤ የምትቀመጥበትም ነገር ሁሉ ርኩስ ነው።'),
  ('4167f0ad-813f-5025-a81a-ff0da246bff8', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 21, 21, 'መኝታዋንም የሚነካ ሁሉ ልብሶቹን ያጥባል፤ በውኃም ሰውነቱን ይታጠባል፤ እስከ ማታም ድረስ ርኩስ ነው።'),
  ('84f74e1b-6492-5425-ae0d-705048173121', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 22, 22, 'የምትቀመጥበትንም ነገር ሁሉ የሚነካ ሁሉ ልብሶቹን ያጥባል፤ በውኃም ሰውነቱን ይታጠባል፤ እስከ ማታም ርኩስ ነው።'),
  ('ecb6f829-5ecc-526e-a253-538275c4368a', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 23, 23, 'በመኝታዋም ላይ ወይም በምትቀመጥበት ነገር ላይ ቢሆን ሲነካው እስከ ማታ ድረስ ርኩስ ነው።'),
  ('7298ad1c-91f3-5309-a59a-34c8c35f6bf3', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 24, 24, 'ማንም ከእርስዋ ጋር ቢተኛ፥ ግዳጅዋም ቢነካው፥ ሰባት ቀን ርኩስ ነው፤ የሚተኛበትም መኝታ ሁሉ ርኩስ ነው።'),
  ('44989539-689e-5a43-aa2a-e2e732d019a4', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 25, 25, '“ሴትም ከግዳጅዋ ቀን ሌላ ደምዋ ብዙ ቀን ቢፈስስ፥ ወይም ደምዋ ከግዳጅዋ ወራት በኋላ ቢፈስስ፥ በግዳጅዋ ወራት እንደ ሆነች እንዲሁ በፈሳሽዋ ርኩስነት ወራት ትሆናለች፤ ርኵስት ናት።'),
  ('e7a8a17c-0ac3-5f17-a2a2-326121b43236', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 26, 26, 'ደምዋም በሚፈስስበት ወራት ሁሉ የምትተኛበት መኝታ ሁሉ በግዳጅዋ ጊዜ እንደ ነበረው መኝታ ያለ ይሆንባታል፤ የምትቀመጥበት ነገር ሁሉ እንደ ግዳጅዋ ርኩስነት ርኩስ ነው።'),
  ('9ff02209-20e4-5bfe-a6f3-42058e4004a9', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 27, 27, 'እነዚህንም ነገሮች የሚነካ ሁሉ ርኩስ ነው፤ ልብሱንም ያጥባል፤ በውኃም ይታጠባል፤ እስከ ማታም ርኩስ ነው።'),
  ('8b82c70d-b813-52a5-aee9-dd50ff3a8b95', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 28, 28, 'ከፈሳሽዋም ብትነጻ ሰባት ቀን ትቈጥራለች፤ ከዚያም በኋላ ንጽሕት ትሆናለች።'),
  ('bf8e5fe5-5542-5a69-a9d3-6e4e52b62f48', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 29, 29, 'በስምንተኛውም ቀን ሁለት ዋኖሶች ወይም ሁለት የርግብ ግልገሎች ይዛ ወደ ካህኑ ወደ ምስክሩ ድንኳን ደጃፍ ታመጣቸዋለች።'),
  ('d2d11a3d-8907-5963-af7e-b7076f680248', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 30, 30, 'ካህኑም አንዲቱን ለኀጢአት መሥዋዕት፥ አንዲቱንም ለሚቃጠል መሥዋዕት ያቀርባል፤ ካህኑም ስለ ፈሳሽዋ ርኩስነት በእግዚአብሔር ፊት ያስተሰርይላታል።'),
  ('1b675228-db38-5095-a78c-283bbf4cfc96', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 31, 31, '“እንዲሁም በእነርሱ መካከል ያለችውን ድንኳኔን ባረከሱ ጊዜ፥ በርኩስነታቸው እንዳይሞቱ የእስራኤልን ልጆች ከርኩስነታቸው አንጹአቸው።'),
  ('4e01ed96-f2e9-557b-ac4d-c447cba6d218', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 32, 32, '“ፈሳሽ ነገር ላለበት ሰው፥ ይረክስም ዘንድ ዘሩ ለሚወጣበት ሰው፥'),
  ('b82b0d63-238c-54dc-ab91-420e36cf1b7d', '72441860-bf1b-523c-a620-28bb0ef9a924', 'e1958a0e-d248-5a97-ad35-95182e48f013', 33, 33, 'በግዳጅዋም ደም ለሚፈስሳት፥ ፈሳሽም ነገር ላለባቸው ለወንድም ለሴትም፥ ከረከሰችም ሴት ጋር ለሚተኛ ሰው ሕጉ ይህ ነው።”'),
  ('34015bca-9f82-5842-a2ec-b6603c79f986', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 1, 1, 'በእግዚአብሔር ፊት ሌላ እሳትን ስላመጡ የሞቱ ሁለቱ የአሮን ልጆች ከሞቱ በኋላ እግዚአብሔር ሙሴን ተናገረው።'),
  ('748781ac-c99a-5657-addc-c8a2f3dc14b7', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 2, 2, 'እግዚአብሔርም ሙሴን አለው፥ “እኔ በስርየቱ መክደኛ ላይ በደመናው ውስጥ እታያለሁና እንዳይሞት በመጋረጃው ውስጥ በምስክሩ ታቦት ላይ ወዳለው ወደ ስርየቱ መክደኛ ወደ ተቀደሰው ስፍራ ሁልጊዜ እንዳይገባ ለወንድምህ ለአሮን ንገረው።'),
  ('0229bf70-59d5-5aed-a9c4-77182cb470a4', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 3, 3, 'እንዲሁ አሮን ለኀጢአት መሥዋዕት ከላሞች ወይፈን፥ ለሚቃጠል መሥዋዕትም አውራ በግ ይዞ ወደ ተቀደሰው ስፍራ ይግባ።'),
  ('9153d2c4-ee22-5fab-ab56-99fdd9780aa4', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 4, 4, 'የተቀደሰውንም የተልባ እግር ቀሚስ ይልበስ፤ የተልባ እግርም ሱሪ በገላው ላይ ይሁን፤ የተልባ እግር መታጠቂያ ይታጠቅ፤ የተልባ እግር አክሊልም በራሱ ላይ ያድርግ፤ እነዚህ የተቀደሱ ልብሶች ናቸው፤ ገላውንም በውኃ ታጥቦ ይልበሳቸው።'),
  ('686bd797-6179-59d7-a84f-b2cdcaf7136e', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 5, 5, 'ከእስራኤልም ልጆች ማኅበር ለኀጢአት መሥዋዕት ሁለት የፍየል ጠቦቶች፥ ለሚቃጠል መሥዋዕት አንድ አውራ በግ ይውሰድ።'),
  ('5a860d0d-7785-5a25-a930-085dd9b64ac5', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 6, 6, '“አሮንም የኀጢአቱን መሥዋዕት ወይፈን ያቀርባል፤ ለራሱም፥ ለቤተሰቡም ያስተሰርያል።'),
  ('df16dc8a-8d53-5199-aa8a-c411d3c3ddf2', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 7, 7, 'ሁለቱንም የፍየል ጠቦቶች ወስዶ በምስክሩ ድንኳን ደጃፍ አጠገብ በእግዚአብሔር ፊት ያቆማቸዋል።'),
  ('9463a53c-e7d8-559d-a9ca-8815240ba852', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 8, 8, 'አሮንም በሁለቱ የፍየል ጠቦቶች ላይ ዕጣ ይጥልባቸዋል፤ አንዱን ዕጣ ለእግዚአብሔር፥ ሌላውንም ዕጣ ለሚለቀቅ።'),
  ('55dcb500-ad1b-51a0-af95-c1c5a2a58165', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 9, 9, 'አሮንም የእግዚአባሔር ዕጣ የሆነበትን ፍየል ያቀርባል፤ ስለ ኀጢአትም መሥዋዕት ያደርገዋል።'),
  ('3a741978-510e-5eff-ac67-0b23e5c1b361', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 10, 10, 'የመለቀቅም ዕጣ የሆነበትን ፍየል ያስተሰርይበት ዘንድ፥ ለመለቀቅም ወደ ምድረ በዳ ይሰድደው ዘንድ በሕይወቱ በእግዚአብሔር ፊት ያቆመዋል።'),
  ('068b116c-e367-58bd-a99d-929bec69a6d7', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 11, 11, '“አሮንም ስለ ራሱ ኀጢአት የሚሠዋውን መሥዋዕት ወይፈኑን ያቀርባል፤ ለራሱም ለቤተሰቡም ያስተሰርያል፤ ስለ ኀጢአቱ የእርሱን መሥዋዕት ወይፈኑን ያርዳል።'),
  ('4013ff09-ba46-579d-a5f3-f9be335afb0b', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 12, 12, 'በእግዚአብሔርም ፊት ከአለው መሠዊያ ላይ የእሳት ፍም አምጥቶ ጥናውን ይሞላል፤ ከተወቀጠውም ልቅምና ደቃቅ ዕጣን እጁን ሙሉ ይወስዳል፤ ወደ መጋረጃውም ውስጥ ያመጣዋል።'),
  ('a9faf965-8a27-5332-afb5-72867901aea5', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 13, 13, 'እንዳይሞትም የጢሱ ደመና በምስክሩ ታቦት ላይ ያለውን መክደኛ ይሸፍን ዘንድ በእግዚአብሔር ፊት ዕጣኑን በእሳቱ ላይ ያደርጋል።'),
  ('6c1b9d09-817d-541a-a9b0-91ef8dd2eeea', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 14, 14, 'ከወይፈኑም ደም ወስዶ በስርየቱ መክደኛ ላይ ወደ ምሥራቅ በጣቱ ይረጨዋል፤ ከደሙም በመክደኛው ፊት በጣቱ ሰባት ጊዜ ይረጫል።'),
  ('784f423b-a084-5be2-a4ce-fe44d92099a5', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 15, 15, '“ስለ ሕዝቡም ኀጢአት የሚሠዋውን መሥዋዕት ፍየል ያርዳል፤ ደሙንም ወደ መጋረጃው ውስጥ ያመጣዋል፤ በወይፈኑም ደም እንዳደረገ በፍየሉ ደም ያደርጋል፤ በመክደኛው ላይና በመክደኛው ፊት ይረጨዋል።'),
  ('51f514cb-a1ef-57bc-abbf-205e9432870e', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 16, 16, 'ከእስራኤል ልጆች ርኩስነት፥ ከመተላለፋቸውም፥ ከኀጢአታቸውም የተነሣ ለመቅደሱ ያስተሰርይለታል፤ እንዲሁም በርኩስነታቸው መካከል ከእነርሱ ጋር ለኖረች ለምስክሩ ድንኳን ያደርጋል።'),
  ('0f5b8cf7-e65f-5de6-ad41-01be578cba91', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 17, 17, 'እርሱ ለማስተስረይ ወደ መቅደሱ በገባ ጊዜ ለራሱ፥ ለቤተሰቡም፥ ለእስራኤል ጉባኤ ሁሉ አስተስርዮ እስኪወጣ ድረስ በምስክሩ ድንኳን ውስጥ ማንም አይኖርም።'),
  ('9ded7aeb-1af4-50f5-a453-521bc8420104', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 18, 18, 'በእግዚአብሔርም ፊት ወዳለው ወደ መሠዊያው ወጥቶ ያስተሰርይለታል፤ ከወይፈኑም ደም፥ ከፍየሉም ደም ወስዶ በመሠዊያው ዙሪያ ያሉትን ቀንዶች ያስነካል።'),
  ('5dcc359a-ee2a-51ac-ae46-b3815e2d030b', '57630970-7f74-5d4a-a02f-076adff5ff59', '10e696d3-d1fc-5ffa-a758-8ded3d60e626', 19, 19, 'ከደሙም በእርሱ ላይ ሰባት ጊዜ በጣቱ ይረጫል፤ ከእስራኤልም ልጆች ርኩስነት ያነጻዋል፤ ይቀድሰውማል።'),
  ('2fa1610a-a11b-5660-aa50-3f01030c598a', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 1, 20, '“ስለመቅደሱ፥ስለ ምስክሩም ድንኳን፥ ስለ መሠዊያውም ማስተስረያና ስለ ካህናትም ማንጻት ከፈጸመ በኋላ ደኅነኛውን ፍየል ያቀርባል።'),
  ('41394ffe-7055-59b7-ac53-449b26751524', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 2, 21, 'አሮንም ሁለቱን እጆቹን በደኅነኛው ፍየል ራስ ላይ ይጭናል፤ በላዩም የእስራኤልን ልጆች በደል ሁሉ፥ መተላለፋቸውን ሁሉ፥ ኀጢአታቸውንም ሁሉ ያስተሰርያል፤ በፍየሉም ራስ ላይ ያሸክመዋል፤ በተዘጋጀው ሰውም እጅ ወደ ምድረ በዳ ይሰድደዋል።'),
  ('77a37f6e-9b8d-5ebf-a282-916aca9cb4f7', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 3, 22, 'ፍየሉም ኀጢአታቸውን ሁሉ ወደ በረሃ ይሸከማል፤ ፍየሉንም ዛፍ በሌለበት በምድረ በዳ ውስጥ ይለቅቀዋል።'),
  ('8dea8781-cda8-59c6-a7bc-651469111aa5', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 4, 23, '“አሮንም ወደ ምስክሩ ድንኳን ይገባል፤ ወደ መቅደሱም በገባ ጊዜ የለበሰውን የተልባ እግር ልብስ ያወልቃል፤ በዚያም ይተወዋል።'),
  ('2252d0b4-c00a-584e-a4b7-6ecb98c0a467', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 5, 24, 'በተቀደሰውም ስፍራ ገላውን በውኃ ይታጠባል፤ ሌላውንም ልብስ ለብሶ ይወጣል፤ የእርሱንም የሚቃጠል መሥዋዕት ያቀርባል፤ ለካህናቱ እንዳስተሰረየ ለራሱም፥ ለሕዝቡም ያስተሰርያል።'),
  ('4184c87c-bdf2-5161-a90b-4c6fbdcfee7d', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 6, 25, 'የኀጢአቱንም መሥዋዕት ስብ በመሠዊያው ላይ ያቃጥለዋል።'),
  ('8134090f-dd7e-5264-a51f-88bbccd11bb6', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 7, 26, 'ለመለቀቅ የሚሆነውን ፍየል የወሰደ ሰው ልብሱን ያጥባል፤ ገላውንም በውኃ ይታጠባል፤ ከዚያም በኋላ ወደ ሰፈሩ ይገባል።'),
  ('04667da5-9892-5ac3-a6c2-2492d6d5f9d7', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 8, 27, 'ለማስተስረያም እንዲሆን ደማቸው ወደ መቅደስ የገባውን የኀጢአቱን መሥዋዕት ወይፈንና የኀጢአቱን መሥዋዕት ፍየል ከሰፈሩ ወደ ውጭ ያወጡአቸዋል፤ ቍርበታቸውንም፥ ሥጋቸውንም፥ ፈርሳቸውንም በእሳት ያቃጥላሉ።'),
  ('2e6d39e7-7645-5bad-a1be-1c5b9d6c2c52', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 9, 28, 'ያቃጠላቸውም ሰው ልብሱን ያጥባል፤ ገላውንም በውኃ ይታጠባል፤ ከዚያም በኋላ ወደ ሰፈር ይገባል።'),
  ('8cad7573-58a7-59c9-a590-8e391cf1918c', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 10, 29, '“ይህም የዘለዓለም ሥርዐት ይሁንላችሁ።'),
  ('47937bf5-a681-5254-affc-3afdc8fbaa5a', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 11, 30, 'በዚህ ቀን ትነጹ ዘንድ ማስተስረያ ይሆንላችኋልና በሰባተኛው ወር ከወሩም በዐሥረኛው ቀን ራሳችሁን አስጨንቋት፤ የሀገር ልጅም፥ በእናንተም መካከል የተቀመጠ እንግዳ ሥራን ሁሉ አትሥሩበት፤ በእግዚአብሔርም ፊት ከኀጢአታችሁ ሁሉ ትነጻላችሁ።'),
  ('a2a90fdc-1533-548c-a5d4-90146ddfc947', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 12, 31, 'ታላቅ ሰንበት ይሆንላችኋል፤ ራሳችሁንም ታዋርዳላችሁ፤ የዘለዓለም ሥርዐት ነው።'),
  ('c10d1300-079b-54ca-ad41-ab282ef68600', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 13, 32, 'የሚቀባውም፥ በአባቱም ፋንታ ካህን ሊሆን የሚካነው ካህን ያስተስርይ፤ የተቀደሰውንም የተልባ እግር ልብስ ይልበስ።'),
  ('75a7bdb7-91ae-5a5a-aa37-040cf06c9842', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 14, 33, 'ለቅድስተ ቅዱሳንም ያስተስርይ፤ ለምስክሩ ድንኳን፥ ለመሠዊያውም ያስተስርይ፤ ለካህናቱም፥ ለጉባኤውም ሕዝብ ሁሉ ያስተስርይ።'),
  ('cf134eb5-4611-5048-ae72-d446b7748b10', '57630970-7f74-5d4a-a02f-076adff5ff59', '6e0a565c-09d4-55fd-a4cd-fb8ee259c9aa', 15, 34, 'ይህም አንድ ጊዜ በዓመት ለእስራኤል ልጆች ስለ ኀጢአታቸው ሁሉ ያስተሰርይ ዘንድ የዘለዓለም ሥርዐት ይሁንላችሁ።” እግዚአብሔርም ሙሴን እንዳዘዘው እንዲሁ አደረገ።'),
  ('9231b7c1-d632-5ddb-acd6-647226bdb621', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው-'),
  ('033387b5-462f-56bc-ac1a-d306ad2de7e5', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 2, 2, '“ለአሮንና ለልጆቹ፥ ለእስራኤልም ልጆች ሁሉ እንዲህ ብለህ ንገር፦ እግዚአብሔር ያዘዘው ይህ ነው፤ እንዲህም አለ፦'),
  ('e5db2371-2852-5e8b-a95c-a0495656cdc8', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 3, 3, 'ከእስራኤል ቤት ከመካከላቸውም ከሚኖሩ እንግዶች ማናቸውም ሰው በሬ፥ ወይም በግ፥ ወይም ፍየል ቢያርድ፥ በሰፈሩ ውስጥ ወይም ከሰፈሩ ውጭ ቢያርደው፥'),
  ('9736cd11-d87a-56a4-a423-c17176787035', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 4, 4, 'ለእግዚአብሔር በጎ መዓዛ ያለው የተመረጠ የሚቃጠል መሥዋዕት፥ ወይም የድኅነት መሥዋዕት ያደርገው ዘንድ ወደ ምስክሩ ድንኳን ደጃፍ ባያመጣው፥ በሌላም ቦታ ቢያርደው፥ በእግዚአብሔር ማደሪያ ፊት ለእግዚአብሔር ቍርባን ያቀርብ ዘንድ ወደ ምስክሩ ድንኳን ባያመጣው፥ ደሙ በዚያ ሰው ላይ ይቈጠርበታል፤ ደም አፍስሶአልና፤ ያም ከሕዝቡ ተለይቶ ይጥፋ።'),
  ('e6dec9a7-9f16-5e04-a233-68e45011f030', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 5, 5, 'ስለዚህ የእስራኤል ልጆች በሜዳ የሚያርዱትን መሥዋዕታቸውን ወደ እግዚአብሔር ወደ ምስክሩ ድንኳን ደጃፍ ያመጡታል፤ ወደ ካህኑም አምጥተው ለእግዚአብሔር ለድኅነት መሥዋዕት ይሠዉታል።'),
  ('22a2d058-c5a2-599d-aa1c-c536774e58db', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 6, 6, 'ካህኑም በምስክሩ ድንኳን ደጃፍ ባለው በመሠዊያው ላይ በእግዚአብሔር ፊት ደሙን ይረጨዋል፤ ስቡንም ለእግዚአብሔር በጎ መዓዛ እንዲሆን ያቃጥለዋል።'),
  ('5db70d57-6ea7-5e6f-a62d-8d14e7dd6efe', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 7, 7, 'መሥዋዕታቸውንም ደግሞ ተከትለው ላመነዘሩባቸው ለሰይጣናት አይሠዉ። ይህ ለእነርሱ ለልጅ ልጃቸው ለዘለዓለም ሥርዐት ይሁን።”'),
  ('52c19f5e-8d1e-5c44-a60d-e74681238653', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 8, 8, 'ለእነርሱ እንዲህ በላቸው፥ “ከእስራኤል ቤት ከመካከላቸው ከሚኖሩ እንግዶች ማናቸውም ሰው የሚቃጠል መሥዋዕት ወይም ሌላ መሥዋዕት ቢያቀርብ፥'),
  ('9bbeae11-91a1-5219-adbb-3755fc3c1f8d', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 9, 9, 'ለእግዚአብሔር ይሠዋ ዘንድ ወደ ምስክሩ ድንኳን ደጃፍ ባያመጣው፥ ያ ሰው ከሕዝቡ ተለይቶ ይጥፋ።'),
  ('21654e31-6471-5762-ad96-02170a31a391', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 10, 10, '“ከእስራኤልም ልጆች፥ ወይም በመካከላቸው ከሚኖሩ እንግዶች ማናቸውም ሰው ደም ቢበላ፥ ደም በሚበላው በዚያ ሰው ላይ ፊቴን አከብድበታለሁ፤ ያንም ሰው ከሕዝቡ ለይች አጠፋዋለሁ።'),
  ('c474d85c-4e4a-5c33-a632-f20e671ae579', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 11, 11, 'የሥጋ ሁሉ ሕይወት ደሙ ነው፤ ደሙም ከሕይወቱ የተነሣ ያስተሰርያልና በመሠዊያው ላይ ለነፍሳችሁ ማስተስረያ ይሆን ዘንድ እኔ ለእናንተ ሰጠሁት።'),
  ('1d0ad38f-4eb4-5d57-a9c2-a11024bee51b', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 12, 12, 'ስለዚህ የእስራኤልን ልጆች፦ ‘ከእናንተ ማንም ደምን አይበላም፤ በመካከላችሁም ከሚኖሩ እንግዶች ማንም ደምን አይበላም’ አልሁ።'),
  ('be24e262-2238-5470-a43b-b378a6e2871a', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 13, 13, '“ከእስራኤልም ልጆች፥ ወይም በመካከላቸው ከሚኖሩ እንግዶች ማናቸውም ሰው የሚበላ እንስሳ ወይም ወፍ እያደነ ቢይዝ፥ ደሙን ያፈስሳል፤ በአፈርም ይከድነዋል።'),
  ('0f98a4f8-0105-533a-a5a0-de3eb995f8e0', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 14, 14, 'የሥጋ ሁሉ ሕይወት ደሙ ነውና፤ ስለዚህ ለእስራኤል ልጆች፦ የሥጋ ሁሉ ሕይወት ደሙ ነውና የሥጋውን ሁሉ ደም አትብሉ፤ የሚበላውም ሁሉ ተለይቶ ይጥፋ አልኋቸው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('a4173ec6-723e-5e59-ad2b-8c5ecdc834a0', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 15, 15, 'የሞተውን ወይም አውሬ የሰበረውን የሚበላ ሰው ሁሉ፥ የሀገር ልጅ ወይም እንግዳ ቢሆን፥ ልብሱን ያጥባል፤ በውኃም ይታጠባል፤ እስከ ማታም ርኩስ ይሆናል፤ ከዚያም በኋላ ንጹሕ ይሆናል።'),
  ('93823b40-865e-5b62-af2c-2a460590e513', 'bfd5965a-371e-580b-a495-62595174792f', 'fe4af3a1-ef9d-513c-a73f-f6ca48e77c81', 16, 16, 'ልብሱንና ገላውን ባያጥብ ግን ኀጢአቱን ይሸከማል።”'),
  ('43365ba2-f01d-5865-ad37-c8cbea7c2633', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('5a23c0c9-9b14-55fb-a389-3cc0a9fb4d67', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('a077689c-3798-5ca0-a534-9e0a66e388f3', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 3, 3, 'እንደ ተቀመጣችሁባት እንደ ግብፅ ምድር ሥራ አትሥሩ፤ እኔም ወደ እርስዋ እንደማገባችሁ እንደ ከነዓን ምድር ሥራ አትሥሩ፤ በሥርዐታቸውም አትሂዱ።'),
  ('539d44c0-3e1e-57c8-a0a3-1fa01d1272bd', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 4, 4, 'ፍርዴን አድርጉ፤ በእርስዋም ትሄዱ ዘንድ ሥርዐቴን ጠብቁ፤ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('bce66d44-9fae-59b3-a4a9-917a9a9750a3', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 5, 5, 'የሚሠራቸው ሰው በእነርሱ በሕይወት ይኖራልና ሥርዐቴንና ፍርዴን ጠብቁ፤ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('431824a8-beeb-5758-af83-b3b261b1c84d', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 6, 6, '“ከእናንተም ማንም ሰው ኀፍረተ ሥጋውን ይገልጥ ዘንድ ወደ ሥጋ ዘመዱ ሁሉ አይቅረብ፤ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('7a0d401b-b117-5058-a651-b2a09ae3b266', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 7, 7, 'የአባትህን ኀፍረተ ሥጋና የእናትህን ኀፍረተ ሥጋ አትግለጥ፤ እናትህ ናትና ኀፍረተ ሥጋዋን አትግለጥ።'),
  ('1f1db50c-de99-5f1a-a189-6441ece8109f', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 8, 8, 'የአባትህን ሚስት ኀፍረተ ሥጋ አትግለጥ፤ የአባትህ ኀፍረተ ሥጋ ነው።'),
  ('eed86dd7-0247-539e-a787-530cb232e2c4', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 9, 9, 'የእኅትህን ኀፍረተ ሥጋ አትግለጥ፤ የአባትህ ልጅ ወይም የእናትህ ልጅ በቤት ወይም በውጭ የተወለደች ብትሆን፥ ኀፍረተ ሥጋዋን አትግለጥ።'),
  ('843b3459-0fc4-56d6-a407-0dab6b052f2f', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 10, 10, 'የወንድ ልጅህን ሴት ልጅ ኀፍረተ ሥጋ ወይም የሴት ልጅህን ሴት ልጅ ኀፍረተ ሥጋ አትግለጥ፤ የአንተ ኀፍረተ ሥጋ ነውና።'),
  ('831dd946-6056-5cb2-ab77-5ec3e05a2687', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 11, 11, 'ከአባትህ የተወለደችውን የአባትህን ሚስት ልጅ ኀፍረተ ሥጋ አትግለጥ፤ ከአባትህ የተወለደች እኅትህ ናት፤ ኀፍረተ ሥጋዋን አትግለጥ።'),
  ('7b5d318b-d2e9-590b-afa8-61f32ea6e611', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 12, 12, 'የአባትህን እኅት ኀፍረተ ሥጋ አትግለጥ፤ የአባትህ ዘመድ ናትና።'),
  ('5d6ba3fa-9f21-503b-adcb-43c7dd22f579', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 13, 13, 'የእናትህን እኅት ኀፍረተ ሥጋ አትግለጥ፤ የእናትህ ዘመድ ናትና።'),
  ('f7f1b445-e284-56ea-af4f-5a88e3a6f6f8', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 14, 14, 'የአባትህን ወንድም ሚስት ኀፍረተ ሥጋ አትግለጥ፤ ዘመድህ ናትና።'),
  ('2ac6112d-04f4-5acd-ac12-dcf4fb9087f3', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 15, 15, 'የምራትህን ኀፍረተ ሥጋ አትግለጥ፤ የልጅህ ሚስት ናት፤ ኀፍረተ ሥጋዋን አትግለጥ።'),
  ('7e99349f-5375-55eb-a4b5-f47e013827f0', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 16, 16, 'የወንድምህን ሚስት ኀፍረተ ሥጋ አትግለጥ፤ የወንድምህ ኀፍረተ ሥጋ ነውና።'),
  ('89a46a3b-2a6f-50ac-ac6e-3da512bed954', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 17, 17, 'የሴትንና የሴት ልጅዋን ኀፍረተ ሥጋ አትግለጥ፤ የወንድ ልጅዋን ሴት ልጅ ወይም የሴት ልጅዋን ሴት ልጅ ኀፍረተ ሥጋዋን ትገልጥ ዘንድ አታግባ፤ ዘመዶች ናቸው፤ ኀጢአት ነውና።'),
  ('0dff04c4-1278-5a26-a389-39a0d32b56ee', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 18, 18, 'በእኅቷ ላይ እንዳትቀና ሚስትህ በሕይወት ሳለች የእኅቷን ኀፍረተ ሥጋ አትግለጥ።'),
  ('7e8c1215-259c-569a-a2aa-f2a888606c00', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 19, 19, '“እርስዋም በግዳጅዋ ርኵሰት ሳለች ኀፍረተ ሥጋዋን ትገልጥ ዘንድ ሳትነጻ በግዳጅዋ ወደ አለች ሴት አትቅረብ።'),
  ('529faaa3-163d-58df-ab85-a722f207c299', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 20, 20, 'ከባልንጀራህ ሚስት ጋር አትተኛ፤ ዘርህንም አትዝራባት።'),
  ('16d5af0e-3a06-591c-a5e1-c01486c6573d', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 21, 21, 'ከዘርህም ለሞሎክ አትስጥ የአምላክህንም ስም አታርክስ፤ እኔ አምላክህ እግዚአብሔር ነኝ።'),
  ('a3002c3d-ff10-5909-a105-cb34dcd3af31', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 22, 22, 'ከሴትም ጋር እንደምትተኛ ከወንድ ጋር አትተኛ፤ ጸያፍ ነገር ነውና።'),
  ('b30dede9-6f6b-5220-a366-b5d4cf9b2c27', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 23, 23, 'ዘርህን በእርስዋ ላይ እንዳትዘራና እንዳትረክስባት ወደ እንስሳ አትሂድ፤ ሴት ከእርሱ ጋር ትተኛ ዘንድ በእንስሳ ፊት አትቁም፤ የተጠላ ነገር ነውና።'),
  ('a618e2e8-872d-5341-a71e-56b91eb0299d', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 24, 24, '“ከፊታችሁ የማሳድዳቸው አሕዛብ በእነዚህ ሁሉ ረክሰዋልና በእነዚህ ነገሮች ሁሉ አትርከሱ።'),
  ('71edc251-0b59-5e4e-aac7-2527ffaddb97', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 25, 25, 'ምድሪቱም ረከሰች፤ ስለዚህ ኀጢአቷን በእርስዋ ላይ እመልሳለሁ፤ ምድሪቱም የሚኖሩባትን ሰዎች ትተፋለች።'),
  ('a5bfd004-1fae-5a76-a320-f516e65e112e', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 26, 26, 'ሥርዐቴንና ፍርዴን ጠብቁ፤ እናንተም የሀገሩ ልጆች፥ በእናንተም መካከል የሚኖሩት እንግዶች ከዚህ ርኵሰት ምንም አትሥሩ፤'),
  ('17849a2c-b0fa-5be6-adba-a975f29539c9', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 27, 27, 'ከእናንተ በፊት የነበሩት የሀገሩ ልጆች ይህን ርኵሰት ሁሉ ሠርተዋልና፥ ምድሪቱንም አርክሰዋታልና፤'),
  ('5333608f-5113-5c9f-aea8-c1565e68dca9', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 28, 28, 'ምድሪቱም ከእናንተ በፊት የነበረውን ሕዝብ እንደ ተፋች ባረከሳችኋት ጊዜ እናንተንም እንዳትተፋችሁ ተጠንቀቁ።'),
  ('0f6f9f52-9cd0-58a3-ac99-c2ce03b3f7a5', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 29, 29, 'ከዚህ ርኵሰት ሁሉ ማናቸውን የሚያደርግ ያ ሰው ከሕዝቡ መካከል ተለይቶ ይጠፋልና።'),
  ('89383b78-c31c-56f5-a984-eb5652785e39', '486584a9-814f-5741-af99-4d267b966c8b', '743434c5-6dca-5d4c-a833-9855df581525', 30, 30, 'ስለዚህ ከእናንተ በፊት የነበሩ ሰዎች የሠሩትን ጸያፍ የሆነውን ወግ ሁሉ እንዳትሠሩ፥ በእርሱም እንዳትረክሱ ሥርዐቴን ጠብቁ፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።”'),
  ('8ab27aa9-332e-5227-ad6a-9fd6f0228c9f', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('d45968c5-4241-5dd0-a94c-c9181768d892', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 2, 2, '“ለእስራኤል ልጆች ማኅበር ሁሉ እንዲህ በላቸው፦ እኔ እግዚአብሔር አምላካችሁ ቅዱስ ነኝና እናንተ ቅዱሳን ሁኑ።'),
  ('8d55c522-bfd3-5a39-a933-2351a15f2e64', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 3, 3, 'ከእናንተ እያንዳንዱ አባቱንና እናቱን ይፍራ፤ ሰንበታቴንም ጠብቁ፤ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('8c04f854-f932-5ee9-a310-0e6a544af831', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 4, 4, 'ጣዖታትንም አትከተሉ፤ ቀልጠው የተሠሩትንም የአማልክት ምስሎች ለእናንተ አታድርጉ፤ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('87cc5154-f47a-5166-abf2-4396fd156e29', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 5, 5, '“የድኅነትን መሥዋዕት ለእግዚአብሔር ስትሠዉ ንጹሕ አድርጋችሁ ሠዉት።'),
  ('068ec73c-ecfe-522d-a9d3-a8a9baf60a1f', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 6, 6, 'በምትሠዉበት ቀንና በነጋው ይበላል፤ እስከ ሦስተኛውም ቀን ድረስ ቢተርፍ በእሳት ይቃጠላል።'),
  ('0b0cb9b9-bd43-57c0-a28f-0bfa816491cb', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 7, 7, 'በሦስተኛውም ቀን ቢበላ ጸያፍ ነው፤ ተቀባይነት የለውም፤'),
  ('bf58c971-29e1-56ab-ac02-8d8aa404cb91', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 8, 8, 'የበላውም ለእግዚአብሔር የተቀደሰውን ነገር አርክሶአልና ኀጢአቱን ይሸከማል፤ ያም ሰው ከሕዝቡ ተለይቶ ይጥፋ።'),
  ('60f9687c-b083-5086-a083-70a0360c89ce', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 9, 9, '“የምድራችሁንም መከር በሰበሰባችሁ ጊዜ የእርሻችሁን አጨዳ አታጥሩ፤ ስታጭዱም የወደቀውን ቃርሚያ አትልቀሙ።'),
  ('d403d018-5198-506e-a121-d3edecc3a4a8', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 10, 10, 'የወይንህን ቃርሚያ አጥርተህ አትቃርም፤ የወደቀውንም የወይንህን ፍሬ አትሰብስብ፤ ለድሆችና ለእንግዶች ተወው፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።'),
  ('99f30ebc-4fee-5870-a0e2-c09fe9cffa27', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 11, 11, '“አትስረቁ፤ አትዋሹም፤ ባልንጀራውንም የሚቀማ አይኑር።'),
  ('1ac0dabb-2d87-5eeb-aa9a-826c2ba6b657', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 12, 12, 'በስሜም በሐሰት አትማሉ፤ የአምላካችሁን ቅዱስ ስም አታርክሱ፤ እኔ አምላካችሁ እግዚአብሔር ነኝና።'),
  ('f2ef9538-8ff3-5fd8-a906-a0847382d3bd', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 13, 13, '“በባልንጀራህ ግፍ አታድርግ፤ አትቀማውም። የሞያተኛው ዋጋ እስከ ነገ ድረስ በአንተ ዘንድ አይደርብህ።'),
  ('49fb30c3-dbfc-523b-a608-8b42b72b0681', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 14, 14, 'ደንቆሮውን አትስደብ፤ በዕውርም ፊት ዕንቅፋት አታድርግ፤ ነገር ግን አምላክህን እግዚአብሔርን ፍራ፤ እኔ አምላክህ እግዚአብሔር ነኝ።'),
  ('4202342b-cc6a-5be0-aa24-982a80c0e731', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 15, 15, '“በፍርድ ዐመፃ አታድርጉ፤ ለድሃ አታድላ፤ ባለጠጋውንም አታክብር፤ ነገር ግን ለባልንጀራህ በእውነት ፍረድ።'),
  ('69521f7e-cef2-58bc-a241-f6e74555e5c1', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 16, 16, 'በሕዝብህ መካከል በሸንጋይነት አትዙር፤ በባልንጀራህም ደም ላይ አትቁም፤ እኔ እግዚአብሔር አምላክህ ነኝ።'),
  ('806a4dd9-f110-50db-ace4-5ef1872531ac', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 17, 17, '“ወንድምህን አትበድለው፤ በልብህም አትጥላው፤ በእርሱ ምክንያት ኀጢአት እንዳይሆንብህ ባልንጀራህን የምትነቅፍበትን ንገረው፤ ገሥጸውም።'),
  ('9b23f219-4a63-5892-ad79-5ba6e695fd52', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 18, 18, 'አትበቀል፤ በሕዝብህም ልጆች ቂም አትያዝ፤ ነገር ግን ባልንጀራህን እንደ ራስህ ውደድ፤ እኔ እግዚአብሔር አምላክህ ነኝና።'),
  ('ed1509a7-c925-5569-a8dc-07202bdde6ab', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 19, 19, '“ሥርዐቴን ጠብቁ፤ በበሬህ በባዕድ ቀንበር አትረስ፤ በወይን ቦታህ የተለያየ ዘር አትዝራ፤ ከሁለት ዐይነት ነገር የተሠራ ልብስ ኀፍረት ነውና አትልበስ።'),
  ('185548f1-f8c0-58ad-ae10-9a04478b5258', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 20, 20, '“ማናቸውም ሰው ከሴት ባሪያ ጋር ቢተኛ፥ እርስዋም ለባል የተሰጠች፥ ዋጋዋም ያልተከፈለ፥ አርነት ያልወጣች ብትሆን፥ ቅጣት አለባቸው፤ አርነት አልወጣችምና አይገደሉም።'),
  ('1087a329-cf10-57d2-ab61-9f1df470b956', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 21, 21, 'እርሱም የበደሉን መሥዋዕት አውራ በግ ወደ እግዚአብሔር ወደ ምስክሩ ድንኳን ደጃፍ ያመጣል።'),
  ('fbec8d6f-7c80-5dd0-a6b0-6f6b73b8eefe', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 22, 22, 'ካህኑም ስለ ሠራው ኀጢአት በእግዚአብሔር ፊት በበደል መሥዋዕት በግ ያስተሰርይለታል፤ የሠራውም ኀጢአት ይቀርለታል።'),
  ('cca2d921-7e4f-5ef8-a5f1-dd9f1d9c3357', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 23, 23, '“አምላካችሁ እግዚአብሔር ወደሚሰጣችሁ ምድር በገባችሁ ጊዜ፥ የሚበላ የፍሬ ዛፍ ሁሉ በተከላችሁም ጊዜ ከርኵሰቱ ሁሉ ታጠሩታላችሁ፤ የሦስቱ ዓመት ፍሬም ርኩስ ነው፤ አይበላም።'),
  ('1c3dca03-aee2-5f70-ad95-ce6358ca4780', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 24, 24, 'በአራተኛውም ዓመት ፍሬ ሁሉ ለእግዚአብሔር ምስጋና ቅዱስ ይሁን።'),
  ('da791138-d4b9-5578-ac36-b89a19ea3620', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 25, 25, 'በአምስተኛውም ዓመት ፍሬውን ብሉ፤ ፍሬውም ይበዛላችኋል፤ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('23b3a2bf-fc41-5695-a16a-455a452dc441', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 26, 26, '“በተራራ ላይ አትብሉ፤ አትርከሱ፥ በወፍም አታሟርቱ።'),
  ('a3b277bb-c929-5a86-a94f-a4c1eebca82f', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 27, 27, 'የራስ ጠጕራችሁንም ዙሪያውን አትከርክሙት፤ ጢማችሁንም አትላጩ።'),
  ('26157c76-72c6-5efa-a7bd-359ea82a177f', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 28, 28, 'ሰው ቢሞት ምላጭ ወደ ሥጋችሁ አታቅርቡ፤ ገላችሁንም አትንቀሱት፤ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('98bb5026-982d-53d1-a039-267049609971', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 29, 29, '“ምድሪቱ ከግልሙትና፥ ከርኵሰትም እንዳትሞላ ሴት ልጅህን ታመነዝር ዘንድ አታርክሳት።'),
  ('00e169d5-e780-5aa9-a467-5042ac688ecd', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 30, 30, 'ሰንበታቴን ጠብቁ፤ መቅደሴንም አክብሩ፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።'),
  ('9b9959fa-8282-5886-a106-64c040382e50', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 31, 31, '“ወደ መናፍስት ጠሪዎችና ወደ ጠንቋዮች አትሂዱ፤ እንዳትረክሱባቸውም አትፈልጉአቸው፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።'),
  ('09b14e63-5bf7-5791-a835-e9dd7e4bf554', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 32, 32, '“በሽበታሙ ፊት ተነሣ፤ ሽማግሌውንም አክብር፤ አምላክህን እግዚአብሔርንም ፍራ፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።'),
  ('8f762cbc-3476-5009-a304-3fa41bcdc491', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 33, 33, '“በሀገራችሁ ውስጥ እንግዳ ከእናንተ ጋር ቢቀመጥ ግፍ አታድርጉበት።'),
  ('2199c12c-9a45-5d7b-ac20-eec4db4cad67', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 34, 34, 'እናንተ በግብፅ ምድር እንግዶች ነበራችሁና፤ ወደ እናንተ የመጣ እንግዳ እንደ ሀገር ልጅ ይሁንላችሁ፤ እርሱን እንደ ራሳችሁ ውደዱት፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።'),
  ('588c06da-cf43-5142-a3c8-90e0904cb62b', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 35, 35, '“በፍርድ፥ በመለካትም፥ በመመዘንም፥ በመስፈርም ዐመፃ አታድርጉ።'),
  ('ebf68a60-008d-5bf0-a973-22875915eaa6', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 36, 36, 'የእውነትም ሚዛን፥ የእውነትም መመዘኛ፥ የእውነትም የፈሳሽ መስፈሪያ ይሁንላችሁ፤ ከግብፅ ምድር ያወጣኋችሁ እግዚአብሔር አምላካችሁ እኔ ነኝ።'),
  ('b789b245-b326-57d6-aba2-bec7041b369a', '1d7d1950-6588-5991-aa8e-75ae2aa4c7cf', '9fc377ea-5ffb-5537-a123-bb9836166e79', 37, 37, 'ሕጌን ሁሉ፥ ትእዛዜንም ሁሉ ጠብቁ፤ አድርጉትም፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።”'),
  ('fe54b2a9-6d17-515b-af2c-aac4b8cd3784', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('43f98b35-5b4a-522d-a2bb-de5489cf513e', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 2, 2, '“ደግሞ የእስራኤልን ልጆች እንዲህ በላቸው፦ ከእስራኤል ልጆች ወይም በእስራኤል ዘንድ ከሚቀመጡ እንግዶች ማናቸውም ሰው ዘሩን ለሞሎክ አገልግሎት ቢሰጥ ፈጽሞ ይገደል፤ የሀገሩ ሕዝብ በድንጋይ ይውገሩት።'),
  ('41b7736d-d9e0-5861-a880-1324b4995052', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 3, 3, 'መቅደሴን ያረክስ ዘንድ፥ የቅዱሳኔንም ስም ያጐስቍል ዘንድ ዘሩን ለሞሎክ አገልግሎት ሰጥቶአልና እኔ በዚያ ሰው ላይ ፊቴን አከብዳለሁ፤ ከሕዝቡም መካከል ለይች አጠፋዋለሁ።'),
  ('34d02916-acaa-5cb2-a926-5295fc66bb4c', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 4, 4, 'ዘሩንም ለሞሎክ ሲሰጥ፥ የሀገሩ ሕዝብ ያን ሰው ቸል ቢሉት፥ አይተው እንዳላዩ ቢሆኑ፥ ባይገድሉትም፥ እኔ በዚያ ሰውና በቤተ ሰቡ ላይ ፊቴን አከብዳለሁ።'),
  ('4b8e3569-a8ea-5d42-ae8b-81ede8ae272d', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 5, 5, 'እርሱንና ከሞሎክ ጋር ያመነዝሩ ዘንድ የሚከተሉትን ሁሉ ከሕዝባቸው መካከል ለይች አጠፋለሁ።'),
  ('d262c85f-2a06-52e2-a845-430e2d53a0eb', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 6, 6, '“እነርሱን ተከትሎ ያመነዝር ዘንድ መናፍስት ጠሪዎችንና ጠንቋዮችን የሚከተል ሰው ቢኖር፥ በዚያ ሰው ላይ ፊቴን አከብዳለሁ፤ ከሕዝቡም መካከል ለይች አጠፋዋለሁ።'),
  ('7096430f-37e6-5b0c-a330-b81e17200b5d', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 7, 7, 'እንግዲህ እኔ እግዚአብሔር አምላካችሁ ቅዱስ ነኝና ቅዱሳን ሁኑ።'),
  ('e7777607-ccc2-5390-a7e4-94bdfb417718', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 8, 8, 'ሕጌንና ትእዛዜን ጠብቁ፤ አድርጉትም፤ እኔ የምቀድሳችሁ እግዚአብሔር አምላካችሁ ነኝና።'),
  ('5b3efbbc-d36e-5d54-a1ec-c433ce017d14', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 9, 9, 'ማናቸውም ሰው አባቱን ወይም እናቱን ቢሰድብ ፈጽሞ ይገደል፤ አባቱንና እናቱን ሰድቦአልና በደለኛ ነው።'),
  ('a6ce1c54-11b7-5fdb-adec-e8a772148989', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 10, 10, '“ማናቸውም ሰው ከሌላ ሰው ሚስት ወይም ከባልንጀራው ሚስት ጋር ቢያመነዝር አመንዝራውና አመንዝራዪቱ ፈጽመው ይገደሉ።'),
  ('a8749a7a-e56f-5abe-a0cc-0980a3fea523', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 11, 11, 'ማናቸውም ሰው ከአባቱ ሚስት ጋር ቢተኛ የአባቱን ኀፍረተ ሥጋ ገልጦአል፤ ሁለቱም ፈጽመው ይገደሉ፤ በደለኞች ናቸው።'),
  ('119017c8-ecb8-528b-a8a0-850cb83777db', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 12, 12, 'ማናቸውም ሰው ከምራቱ ጋር ቢተኛ ሁለቱ ፈጽመው ይገደሉ፤ ጸያፍ ነገር አድርገዋል፤ በደለኞች ናቸው።'),
  ('7bd9429a-2b58-5351-a777-b6e338fc485a', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 13, 13, 'ማናቸውም ሰው ከሴት ጋር እንደሚተኛ ከወንድ ጋር ቢተኛ ሁለቱ ጸያፍ ነገር አድርገዋል፤ ፈጽመው ይገደሉ፤ በደለኞች ናቸው።'),
  ('a2085d1f-cad3-57b9-ac8f-adcff0b90f49', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 14, 14, 'ማናቸውም ሰው እናቲቱንና ልጂቱን ቢያገባ ኀጢአት ነው፤ በመካከላቸው ኀጢአት እንዳይሆን እርሱንና እነርሱን በእሳት ያቃጥሉአቸው።'),
  ('c5a2369a-3bed-5de7-aab9-897895073b97', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 15, 15, 'ማናቸውም ሰው ከእንስሳ ጋር ቢገናኝ ፈጽሞ ይገደል፤ እንስሳዪቱንም ግደሉአት።'),
  ('8147f910-bb6b-51cd-a49b-1b3f797974e4', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 16, 16, 'ማንኛዪቱም ሴት ወደ እንስሳ ብትቀርብ፥ ከእርሱም ጋር ብትገናኝ፥ ሴቲቱንና እንስሳውን ግደሉ፤ ፈጽመው ይገደሉ፤ በደለኞች ናቸው።'),
  ('f2388a1f-1c13-5cf0-aa8a-19dd5ae9098f', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 17, 17, '“ማናቸውም ሰው የአባቱን ልጅ ወይም የእናቱን ልጅ እኅቱን ቢያገባ፥ ኀፍረተ ሥጋዋንም ቢያይ፥ እርስዋም ኀፍረተ ሥጋውን ብታይ፥ ይህ ጸያፍ ነገር ነው፤ በሕዝባቸውም ልጆች ፊት ይገደሉ፤ የእኅቱን ኀፍረተ ሥጋ ገልጦአልና ኀጢአቱን ይሸከማል።'),
  ('06e455aa-0455-54c3-a342-4e4fb87d13ba', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 18, 18, 'ማናቸውም ሰው ከባለ ግዳጅ ሴት ጋር ቢተኛ ኀፍረተ ሥጋዋንም ቢገልጥ፥ ፈሳሽዋን ገልጦአልና፥ እርስዋም የደምዋን ፈሳሽ ገልጣለችና ሁለቱ ከሕዝባቸው መካከል ተለይተው ይጥፉ።'),
  ('d06393c9-a36d-5945-ac66-5e64fdd83537', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 19, 19, 'የአባትህን ወይም የእናትህን እኅት ኀፍረተ ሥጋ አትግለጥ፤ ይህን የሚያደርግ የዘመድን ኀፍረተ ሥጋ ገልጦአል፤ ኀጢአታቸውን ይሸከማሉ።'),
  ('c5d6977c-c988-55e5-addb-17b328fd7e13', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 20, 20, 'ሰውም ከቅርብ ዘመዱ ሚስት ጋር ቢተኛ የቅርብ ዘመዱን ኀፍረተ ሥጋ ገልጦአል፤ ያለ ልጅ ይሞታሉ።'),
  ('178a9b52-ef82-5f6c-af7a-e771d78b2f11', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 21, 21, 'ሰውም የወንድሙን ሚስት ቢያገባ ርኵሰት ነው፤ የወንድሙን ኀፍረተ ሥጋ ገልጦአል፤ ያለ ልጅም ይሙቱ።'),
  ('79a26043-2220-5f1a-a9b4-c08638081b97', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 22, 22, '“እንግዲህ ትቀመጡባት ዘንድ የማገባችሁ ምድር እንዳትተፋችሁ ትእዛዜን ሁሉ፥ ፍርዴንም ሁሉ ጠብቁ፤ አድርጉትም።'),
  ('603a4564-50fb-5ec7-a48f-53fd00dd4bbc', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 23, 23, 'ከፊታችሁ በማወጣቸው ሕዝብ ሕግ አትሂዱ፤ ይህን ሁሉ አድርገዋልና ተጸየፍኋቸው'),
  ('36b8a5b6-5536-5a29-a317-85b6f5d0d7b1', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 24, 24, 'ነገር ግን እናንተ፦ ምድራቸውን ትወርሳላችሁ፤ ትወርሱአትም ዘንድ ወተትና ማር የምታፈስሰውን ምድር እሰጣችኋለሁ አልኋችሁ፤ እኔ ከአሕዛብ የለየኋችሁ አምላካችሁ እግዚአብሔር ነኝ።'),
  ('8422a3fe-96a6-58ea-ac8b-be482d7129b6', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 25, 25, 'እንግዲህ በንጹሕና በርኩስ እንስሳ መካከል፥ በንጹሕና በርኩስም ወፍ መካከል ለየሁላችሁ፤ ርኩሳን ናቸው ብዬ በለየኋቸው በእንስሳና በወፍ፥ በምድርም ተንቀሳቃሽ ሁሉ ነፍሳችሁን አታርክሱ።'),
  ('9c3134dc-84e5-5317-affb-27f11fc5b214', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 26, 26, 'እኔ እግዚአብሔር ቅዱስ ነኝና፥ ለእኔም ትሆኑ ዘንድ ከአሕዛብ ለይቻችኋለሁና ቅዱሳን ትሆኑልኛላችሁ።'),
  ('e17b3ae8-003a-5383-acd2-ab29210ec93a', 'd3bb8c01-4662-52aa-a1b6-2bac3a840e11', '8469b4bb-7895-5e28-a61d-9b789c519b8b', 27, 27, '“ወንድ ወይም ሴት መናፍስትን ቢጠሩ፥ ወይም ጠንቋዮች ቢሆኑ ፈጽመው ይገደሉ፤ በድንጋይም ይውገሩአቸው፤ በደለኞች ናቸውና።”'),
  ('63465edb-ad78-5d23-a66d-99fc0b871fc7', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ሲል ተናገረው፥ “ከወገናቸው በሞተ ሰው ራሳቸውን እንዳያረክሱ ለካህናቱ ለአሮን ልጆች ንገራቸው።'),
  ('c286ea3e-7e5d-56cc-a500-ac9f281b3dbc', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 2, 2, 'ከቅርብ ዘመዶቻቸው፥ ከአባቶቻቸው፥ ወይም ከእናቶቻቸው፥ ወይም ከወንዶች ልጆቻቸው፥ ወይም ከሴቶች ልጆቻቸው፥ ወይም ከወንድሞቻቸው፥'),
  ('c1590297-fef0-56d4-a10f-af1397ae3dea', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 3, 3, 'ወይም ከቀረበች ያላገባች ድንግል እኅት በቀር ራሳቸውን አያርክሱ።'),
  ('4d668ac3-34cd-52fd-ad34-0b15ef5a33f0', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 4, 4, 'ራሱን ያጐሰቍል ዘንድ ከሕዝቡ በማንም አይርከስ።'),
  ('256d3313-4a03-5359-adb0-46b095cecfeb', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 5, 5, 'ስለ ሞተው ሰው ራሳቸውን አይላጩ፤ ጢማቸውንም አይላጩ፤ ሥጋቸውንም አይንጩ።'),
  ('2b0305bc-fead-54a8-adf8-6566e487bd0f', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 6, 6, 'ለአምላካቸው ቅዱሳን ይሁኑ፤ የአምላካቸውንም ስም አያርክሱ፤ የእግዚአብሔርን መሥዋዕትና የአምላካቸውን መባ ያቀርባሉና ቅዱሳን ይሁኑ።'),
  ('1d18ab38-9e1c-5fa8-a428-e7ba6e802edc', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 7, 7, 'ለአምላኩ ለእግዚአብሔር የተቀደሰ ነውና ጋለሞታን ሴት ወይም የረከሰችውን አያግባ፤ ወይም ከባልዋ የተፋታችውን አያግባ።'),
  ('2a3a08a6-3d52-542d-a23b-a4c089318ece', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 8, 8, 'የአምላክህን መባ ያቀርባልና ስለዚህ ትቀድሰዋለህ፤ እኔም የምቀድሳችሁ እግዚአብሔር ቅዱስ ነኝና እርሱ ቅዱስ ይሁንልህ።'),
  ('9c938255-cc71-56e9-a1bc-5eb6f2ea3dc1', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 9, 9, 'የካህንም ሰው ልጅ በግልሙትና ራስዋን ብታረክስ በግልሙትና አባቷን ታረክሰዋለች፤ በእሳት ትቃጠል።'),
  ('7e020f9a-ec40-534d-a345-fe84a6bb4194', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 10, 10, '“በራሱም ላይ የቅባት ዘይት የፈሰሰበት፥ የክህነትም ልብስ ይለብስ ዘንድ የተቀደሰ፥ ከወንድሞቹ የተለየው ካህን ራሱን አይላጭ፤ ልብሱንም አይቅደድ።'),
  ('2d288d5f-f038-54b8-af10-66aad20376d0', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 11, 11, 'ወደ ሞተ ሰው ሁሉ አይግባ፤ በአባቱም ወይም በእናቱ አይርከስ።'),
  ('5b43e1c7-3403-50eb-a524-d0e1f2fc9fa3', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 12, 12, 'የአምላኩም ቅባት ዘይት ቅዱስነት በላዩ ነውና ከመቅደስ አይውጣ፤ የአምላኩንም ቅዱስ ስም አያርክስ፤ እኔ እግዚአብሔር ነኝ።'),
  ('ba6d3581-2a35-5d4b-aca6-113c7eee056e', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 13, 13, 'እርሱም ከወገኑ ድንግል ሴትን ያግባ።'),
  ('9b29429b-c854-561a-a8b5-fb98c01b3d4b', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 14, 14, 'ባልዋ የሞተባትን፥ ወይም የተፋታችውን፥ የተጠላችውን ወይም ጋለሞታዪቱን አያግባ፤ ነገር ግን ከወገኑ ድንግሊቱን ያግባ፤'),
  ('fab28b41-abc7-5f0e-a86d-321cbb62e27c', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 15, 15, 'እኔም የምቀድሰው እግዚአብሔር ነኝና በሕዝቡ መካከል ዘሩን አያጐስቍል።”'),
  ('a3e92f6c-cbed-5a41-acc3-67a91fe64eca', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 16, 16, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('05fa01be-08d9-543f-a612-3d1e9bb840aa', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 17, 17, '“ለአሮን እንዲህ ብለህ ንገረው፦ ከወገንህ በትውልዳቸው ነውር ያለበት ሰው ሁሉ የአምላኩን መባ ያቀርብ ዘንድ አይቅረብ።'),
  ('9e371333-c598-5ace-a506-825b607edbbd', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 18, 18, 'ንጹሕ ያልሆነ ሰው ሁሉ አይቅረብ፤ ዕውር፥ ወይም አንካሳ፥ ወይም አፍንጫ ደፍጣጣ፥ ወይም ጆሮ ቈራጣ፥'),
  ('eb33f0cb-cdd5-5185-ae75-0bc0aad2f050', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 19, 19, 'ወይም እጀ ሰባራ፥ ወይም እግረ ሰባራ፥'),
  ('efa52979-f978-5097-ada4-00dde5921ae4', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 20, 20, 'ወይም ጎባጣ፥ ወይም ድንክ፥ ወይም ዐይነ መጭማጫ፥ ወይም ቅንድበ መላጣ፥ ወይም እከካም፥ ወይም ቋቍቻም፥ ወይም የአባለዘሩ ፍሬ አንድ የሆነ ነውረኛ ሁሉ አይቅረብ።'),
  ('377de3a8-e82d-55c7-a861-d54f206d41dd', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 21, 21, 'ከካህኑ ከአሮን ዘር ነውር ያለበት ሰው የእግዚአብሔርን መሥዋዕት ያቀርብ ዘንድ አይቅረብ፤ ነውረኛ ነው፤ የአምላኩን መባ ያቀርብ ዘንድ አይቅረብ።'),
  ('f62af436-ed1f-5f66-a47c-cce554ab2fc4', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 22, 22, 'የቅዱሱንና የቅዱሰ ቅዱሳኑን የአምላኩን መባ ይብላ፤'),
  ('81f6bed0-bd80-5772-a0a5-eca159a71b49', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 23, 23, 'ነገር ግን ነውረኛ ነውና መቅደሶችን እንዳያረክስ ወደ መጋረጃው አይግባ፤ ወደ መሠዊያውም አይቅረብ፤ የምቀድሳቸው እኔ እግዚአብሔር ነኝና።”'),
  ('2bf1514b-c5dd-5de0-a5e6-433808e6ac1e', 'd99c9a95-9a32-5a44-afd2-5b774026480c', '496d0b27-458f-5a1c-a920-2e3d22062c10', 24, 24, 'ሙሴም ይህን ለአሮን፥ ለልጆቹም፥ ለእስራኤልም ልጆች ሁሉ ነገራቸው።'),
  ('1f327745-b6b0-50fb-a874-9fe0202630a8', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('f7e99604-1fe9-5849-a0c5-0bb0e2b706be', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 2, 2, '“የእስራኤል ልጆች ለእኔ ከሚቀድሱአቸው ከቅዱሳን ነገሮች ራሳቸውን እንዲለዩ፥ የተቀደሰውንም ስሜን እንዳያረክሱ ለአሮንና ለልጆቹ ንገራቸው፤ እኔ እግዚአብሔር ነኝ።'),
  ('56e3ba5e-99c9-5ad5-ad96-fc18fabab3eb', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 3, 3, 'እንዲህ በላቸው፦ ማናቸውም ሰው ከዘራችሁ በትውልዳችሁ ርኵሰት እያለበት የእስራኤል ልጆች ለእግዚአብሔር ወደሚቀድሱት ወደ ቅዱስ ነገር ቢቀርብ፥ ያ ሰው ከፊቴ ተለይቶ ይጥፋ፤ እኔ እግዚአብሔር ነኝ።'),
  ('8b0650d6-07b0-5b42-aee6-fbcca01d0e21', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 4, 4, 'ከአሮን ዘር ለምጽ ወይም ፈሳሽ ነገር ያለበት ሁሉ ንጹሕ እስኪሆን ድረስ ከተቀደሰው አይብላ። ከበድንም የተነሣ ርኩስ የሆነውን፥ ወይም ዘሩ ከእርሱ የሚፈስስበትን የሚነካ፥'),
  ('05b41503-80ff-52c5-ad54-f83a69568a36', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 5, 5, 'ወይም የሚያረክሰውን ተንቀሳቃሽ፥ ወይም በሁሉ ዐይነት የረከሰውን ሰው የሚነካ፥'),
  ('ac449c6c-9b3f-5d67-ac22-13de2f7a6b4e', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 6, 6, 'እነዚህን ሁሉ የሚነካ ሰው እስከ ማታ ድረስ ርኩስ ይሆናል፤ ገላውን በውኃ ካልታጠበ ከተቀደሰው አይብላ።'),
  ('72a2e3f0-0a7f-55e5-ad2b-b5d5f7b1e79d', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 7, 7, 'ፀሐይም በገባች ጊዜ ንጹሕ ይሆናል፤ ከዚያም በኋላ ምግቡ ነውና ከተቀደሰው ይብላ።'),
  ('756ee511-17b5-5029-a840-adea02335ac9', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 8, 8, 'በእርሱም እንዳይረክስ፥ የሞተውን፥ አውሬም የሰበረውን አይብላ፤ እኔ እግዚአብሔር ነኝና።'),
  ('ccbb743f-39ce-590f-a04b-69ad5f487481', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 9, 9, 'ቢያረክሱአት እንዳይሞቱ፥ ስለ እርስዋም ኀጢአትን እንዳይሸከሙ፥ ሕግን ይጠብቁ፤ የምቀድሳቸው እኔ እግዚአብሔር ነኝና።'),
  ('36317a94-b1e5-589b-a9d0-9335678982c2', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 10, 10, '“ከባዕድ ወገን የሆነ ሰው ከተቀደሰው አይብላ፤ የካህኑም እንግዳ፥ ደመወዘኛውም ከተቀደሰው አይብላ።'),
  ('5fb9679e-1684-5004-afdb-9fa067461836', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 11, 11, 'ካህኑ ግን በገንዘቡ አገልጋይ ቢገዛ እርሱ ከምግቡ ይብላ፤ በቤቱም የተወለዱት ከእንጀራው ይብሉ።'),
  ('6c16e151-650c-597a-ae5c-d0a5992ad58b', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 12, 12, 'የካህንም ልጅ ከሌላ ወገን ጋር ብትጋባ፥ እርስዋ ከተቀደሰው ዐሥራት አትብላ።'),
  ('b9f16ba2-7321-548f-af64-d66fd85464fe', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 13, 13, 'የካህን ልጅ ግን ባልዋ ቢሞት፥ ወይም ብትፋታ፥ ልጅም ባይኖራት፥ በብላቴንነቷ እንደ ነበረች ወደ አባቷ ቤት ብትመለስ፥ ከአባቷ እንጀራ ትብላ፤ ከሌላ ወገን የሆነ ባዕድ ሰው ግን ከእርሱ አይብላ።'),
  ('c86fc5e1-56fd-52ae-ab55-496f150dfa40', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 14, 14, 'ማናቸውም ሰው ሳያውቅ ከተቀደሰው ቢበላ አምስተኛ እጅ ጨምሮ የተቀደሰውን ለካህኑ ይስጥ።'),
  ('eab56b36-ec67-5d97-af90-a82e5d1965bd', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 15, 15, 'ወደ እግዚአብሔር የሚያቀርቡትን፥ በእስራኤል ልጆች ዘንድ የተቀደሰውን ነገር አያርክሱ።'),
  ('0d7dbb20-ff53-54cd-acc5-db79443fe844', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 16, 16, 'በኀጢአት ሳሉ ከተቀደሰው መሥዋዕት ከበሉ ግን ኀጢአትና በደል ይሆንባቸዋል፤ የማነጻቸው እኔ እግዚአብሔር ነኝና።”'),
  ('12d006fc-65dc-5c5f-ad9a-a135b6e78905', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 17, 17, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('a4d7ecaf-ed79-52c6-a803-75b0a415e872', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 18, 18, '“ለአሮንና ለልጆቹ፥ ለእስራኤልም ልጆች ሁሉ እንዲህ ብለህ ንገራቸው፦ ከእስራኤል ቤት ወይም ከእናንተ መካከል ከሚቀመጡት እንግዶች ማናቸውም ሰው ስእለቱን ሁሉ፥ በፈቃዱም የሚያቀርበውን ሁሉ፥ ለእግዚአብሔር ለሚቃጠል መሥዋዕት የሚያቀርበውን ቍርባን ቢያቀርብ፥'),
  ('8c709388-32fc-5247-a930-13c3c03fb689', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 19, 19, 'ይሠምርላችሁ ዘንድ ከበሬ፥ ወይም ከበግ፥ ወይም ከፍየል ነውር የሌለበትን ተባቱን አቅርቡ።'),
  ('de6d69ee-06f2-5b42-afa7-d414a0ae12cf', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 20, 20, 'ነገር ግን አይሠምርላችሁምና ነውር ያለበትን ለእግዚአብሔር አታቅርቡ።'),
  ('e69525f1-c8d2-57f3-a97e-76f185a47f6a', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 21, 21, 'ማናቸውም ሰው ስእለቱን ለመፈጸም ወይም በፈቃዱ ለማቅረብ የደኅንነትን መሥዋዕት፥ ወይም በሬን፥ ወይም በግን፥ ለእግዚአብሔር ቢያቀርብ፥ ይሰምርለት ዘንድ ፍጹም ይሁን፤ ነውርም አይሁንበት።'),
  ('7725bc4c-af05-5df4-adfa-97a4477a3950', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 22, 22, 'ዕውር፥ ወይም ሰባራ፥ ወይም ምላሱ የተቈረጠ፥ ወይም የሚመግል ቍስል ያለበት፥ ወይም እከካም፥ ወይም ቋቍቻም ቢሆን፥ እነዚህን ሁሉ ለእግዚአብሔር አታቅርቡ፤ እነዚህንም ለእሳት ቍርባን በመሠዊያው ላይ ለእግዚአሔር አታሳርጉ።'),
  ('e2b8c4da-a031-5548-aefd-daddc2c0749b', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 23, 23, 'በሬው፥ ወይም በጉ ጆሮው፥ ወይም ጅራቱ የተቈረጠ ቢሆን፥ ቈጥረህ የራስህ ገንዘብ አድርገው እንጂ ለስእለት አይቀበልህም።'),
  ('4100a668-bb21-5ebb-a83c-fdd15da15342', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 24, 24, 'የተቀጠቀጠውን፥ ወይም የተሰበረውን፥ ወይም የተቈረጠውን ወይም የተሰነጋውን ለእግዚአብሔር አታቅርቡ፤ በምድራችሁም እነዚህን አትሠዉ።'),
  ('898a6520-7be1-5e56-a2ab-a4e1396d15ac', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 25, 25, 'ከእነዚህም ከባዕድ ወገን ከሆነ ሰው እጅ ለአምላካችሁ መባ አታቅርቡ፤ ርኵሰትም፥ ነውርም አለባቸውና አይቀበላችሁም።”'),
  ('7decf145-f2ba-54f8-a7cc-ce2a93b2c934', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 26, 26, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('b7a486c1-10ef-5cc8-a594-2c9dff71eb8e', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 27, 27, '“ላም፥ ወይም በግ፥ ወይም ፍየል ሲወለድ ሰባት ቀን ከእናቱ ጋር ይቀመጥ፤ በስምንተኛውም ቀን፥ ከዚያም በላይ ለእግዚአብሔር የእሳት ቍርባን የሠመረ ይሆናል።'),
  ('f1342a4d-8019-5502-a67e-004c38ec3478', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 28, 28, 'ላም፥ ወይም በግ፥ ወይም ፍየል ብትሆን እርስዋንና ልጅዋን በአንድ ቀን አትረዱ።'),
  ('6118e7a3-0321-568d-ad93-cba9327e86a4', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 29, 29, 'የምስጋናንም መሥዋዕት ለእግዚአብሔር ስትሠዉ እንዲቀበላችሁ ሠዉለት።'),
  ('d9059292-4ec8-5bd9-af95-694c8ed8b89d', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 30, 30, 'በዚያው ቀን ይብሉት፤ ከእርሱ እስከ ነገ ምንም አትተዉ፤ እኔ እግዚአብሔር ነኝና።'),
  ('885fc8f9-8075-50cb-aac0-0391e0757a3a', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 31, 31, 'ትእዛዛቴን ጠብቁ፤ አድርጉትም፤ እኔ እግዚአብሔር ነኝና።'),
  ('6b1ef39b-224e-55ce-add9-a5886e8cbcb8', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 32, 32, 'የተቀደሰውንም ስሜን አታርክሱ፤ እኔ ግን በእስራኤል ልጆች መካከል እቀደሳለሁ፤'),
  ('3fb92e63-d7f9-5be4-a2c4-8514040a4192', '3f6d2910-0161-52a2-ab06-77a31d0f90f8', '0040a5d5-9ae9-5656-af70-e884319293b3', 33, 33, 'የምቀድሳችሁ እኔ እግዚአብሔር ነኝና። አምላካችሁም እሆን ዘንድ ከግብፅ ምድር ያወጣኋችሁ እኔ እግዚአብሔር ነኝና።”'),
  ('e262902e-feb1-5da8-a87d-3e7ebe00088e', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', 'fc89e063-27fe-58a3-ae96-648cccb82d2c', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('4300d43f-7314-55d2-a462-a7a224319b38', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', 'fc89e063-27fe-58a3-ae96-648cccb82d2c', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ቅዱሳት ጉባኤያት ብላችሁ የምትጠሩአቸው በዓላቴ፥ የእግዚአብሔር በዓላት እነዚህ ናቸው።'),
  ('2dd80663-7ef4-5d01-ad4d-c61a8d2d9f68', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', 'fc89e063-27fe-58a3-ae96-648cccb82d2c', 3, 3, 'ስድስት ቀን ሥራህን ትሠራለህ፤ በሰባተኛው ቀን ግን የዕረፍት ሰንበት ነው፤ ለእግዚአብሔር ቅዱስ ጉባኤ ይሆንበታል፤ ምንም ሥራ አትሠሩም፤ በምትኖሩበት ሁሉ ለእግዚአብሔር ሰንበት ነው።'),
  ('bad3859e-b374-5c54-ac46-06cb4e79375e', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', 'fc89e063-27fe-58a3-ae96-648cccb82d2c', 4, 4, 'እነዚህ የእግዚአብሔር በዓላት፥ በየዘመናቸው የምታውጁአቸው፥ የተቀደሱ ጉባኤያት ናቸው።'),
  ('6af363b9-534c-5279-a657-a4661d6a0005', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 1, 5, '“በመጀመሪያው ወር በዐሥራ አራተኛው ቀን ሲመሽ የእግዚእብሔር ፋሲካ ነው።'),
  ('8d2fd2f7-dc7c-5d61-ac8a-976969d68dc6', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 2, 6, 'በዚህም ወር በዐሥራ አምስተኛው ቀን ለእግዚአብሔር የቂጣ በዓል ነው፤ ሰባት ቀን ቂጣ ብሉ።'),
  ('09fbf95d-91f8-53f7-adf1-354b4be7cbf4', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 3, 7, 'መጀመሪያይቱ ቀን ቅድስት ጉባኤ ትሁንላችሁ፤ የተግባር ሥራ ሁሉ አትሥሩባት።'),
  ('161903bf-f713-5a84-a15d-060999c0ec62', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 4, 8, 'ሰባት ቀንም ለእግዚአብሔር የሚቃጠል መሥዋዕት አቅርቡ፤ ሰባተኛዋ ቀን ቅድስት ጉባኤ ትሁንላችሁ፤ የተግባር ሥራ ሁሉ አትሥሩባት።”'),
  ('fa339cd9-9ba8-5dfb-afde-82ed79bb41ab', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 5, 9, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('fe8757e3-1a45-5173-a48f-bbb8a2e9ab8d', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 6, 10, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ወደምሰጣችሁ ምድር በገባችሁ ጊዜ፥ መከሩንም ባጨዳችሁ ጊዜ፥ የእናንተን መከር በኵራት ነዶ ወደ ካህኑ አምጡ፤'),
  ('28c0aa37-f612-56ca-a705-678b89219317', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 7, 11, 'እርሱም ነዶውን በእግዚአብሔር ፊት እንዲሠምርላችሁ ያቀርበዋል፤ በማግስቱ ከሰንበት በኋላ ካህኑ ያቅርበው፤'),
  ('57670730-698a-5fa8-ad05-da065b5d4da0', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 8, 12, 'ነዶውንም ባቀረባችሁበት ቀን ነውር የሌለበትን የአንድ ዓመት ተባት ጠቦት ለሚቃጠል መሥዋዕት ለእግዚአብሔር አቅርቡ።'),
  ('3537cc24-4bb5-5f7d-a20f-22485321fce5', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 9, 13, 'የስንዴም ቍርባን ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ የሆነ በዘይት የተለወሰ መልካም የስንዴ ዱቄት ለእግዚአብሔር በጎ መዓዛ ያለው ቍርባን ይሁን፤ የመጠጡም ቍርባን የወይን ጠጅ የኢን መስፈሪያ አራተኛ እጅ ይሁን።'),
  ('39f65dc9-0559-5170-a189-39d277c5d819', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '550c3bd8-6f8d-5767-a180-abbe91ad06f4', 10, 14, 'እንጀራውንም፥ የተጠበሰውንም እሸት፥ ለምለሙንም እሸት የአምላካችሁን ቍርባን እስከምታቀርቡበት እስከዚህ ቀን ድረስ አትብሉ። ይህ በምትቀመጡበት ሀገር ሁሉ ለልጅ ልጃችሁ የዘለዓለም ሥርዐት ነው።'),
  ('42c1107b-ec00-5d64-ae56-aba6614ea150', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '5fce6fde-3b14-51a1-a1b0-a9cdc387eae3', 1, 15, '“ያቀረባችሁትን ነዶ ከምታመጡበት ቀን በኋላ ከሰንበት ማግስት ፍጹም ሰባት ሱባዔ ቍጠሩ፤'),
  ('55de638e-7368-56f2-a47e-5d2dd80085e2', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '5fce6fde-3b14-51a1-a1b0-a9cdc387eae3', 2, 16, 'እስከ መጨረሻዋ ሰባተኛ ሰንበት ማግስት ድረስ አምሳ ቀን ቍጠሩ፤ አዲሱንም መሥዋዕት ለእግዚአብሔር አቅርቡ።'),
  ('379dd282-fe2a-50e0-a829-0f9165c559cd', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '5fce6fde-3b14-51a1-a1b0-a9cdc387eae3', 3, 17, 'ከየማደሪያችሁ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ ከሆነ መልካም የስንዴ ዱቄት የተሠራ ሁለት የቍርባን እንጀራ ታመጣላችሁ፤ ከእህላችሁ ቀዳምያት ለእግዚአብሔር በእርሾ ይጋገራል።'),
  ('e5342404-0ddc-5a44-ac32-1cc2a515a00e', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '5fce6fde-3b14-51a1-a1b0-a9cdc387eae3', 4, 18, 'ከኅብስቱም ጋር ነውር የሌለባቸውን የአንድ ዓመት ሰባት ጠቦቶች፥ ከመንጋውም አንድ ወይፈን፥ ሁለትም ነውር የሌለባቸው አውራ በጎች ታቀርባላችሁ፤ ለእግዚአብሔር በጎ መዓዛ ያለው መሥዋዕት እንዲሆን መሥዋዕታቸውና ቍርባናቸው፥ ወይናቸውም ለእግዚአብሔር ይሁን።'),
  ('ff5c7ec0-6e7c-56bb-afe3-de3300a06ef7', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '5fce6fde-3b14-51a1-a1b0-a9cdc387eae3', 5, 19, 'አንድም አውራ ፍየል ለኀጢአት መሥዋዕት፥ ሁለትም የአንድ ዓመት ተባት ጠቦቶች ከመጀመሪያው የእህል ቍርባን ጋር ለደኅንነት መሥዋዕት አቅርቡ።'),
  ('c884d9cd-e326-5f0e-a469-64779d27aa3d', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '5fce6fde-3b14-51a1-a1b0-a9cdc387eae3', 6, 20, 'ካህኑም ከበኵራቱ ኅብስት፥ ከሁለቱም ጠቦቶች ጋር በእግዚአብሔር ፊት ለቍርባን ያቅርበው፤ ለእግዚአብሔር የተቀደሰ ፈንታ ነው፤ ላቀረበው ለካህኑ ይሁን።'),
  ('e7c8762b-e5f0-5bd7-a9ef-43b46d3ce3bf', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '5fce6fde-3b14-51a1-a1b0-a9cdc387eae3', 7, 21, 'ያችንም ቀን ቅድስት ጉባኤ ብላችሁ ታውጃላችሁ፤ የተግባር ሥራ ሁሉ አታድርጉባት፤ በምትቀመጡበት ሀገር ሁሉ ለልጅ ልጃችሁ የዘለዓለም ሥርዐት ነው።'),
  ('aa4046d2-54b1-58db-a933-8ddc20a12779', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '5fce6fde-3b14-51a1-a1b0-a9cdc387eae3', 8, 22, '“የምድራችሁን መከር በሰበሰባችሁ ጊዜ በእርሻችሁ የቀረውን አጥርታችሁ አትጨዱ፤ የመከሩንም ቃርሚያ አትልቀሙ፤ ለድሆችና ለእንግዶች ተዉት፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።”'),
  ('3db888be-fd63-57e7-a930-1dde2330384e', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '22f2b0f8-7b67-5512-ad8e-13a4478f0fa1', 1, 23, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('6403926b-65c5-501d-a207-a24118c9d38e', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '22f2b0f8-7b67-5512-ad8e-13a4478f0fa1', 2, 24, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ በሰባተኛው ወር ከወሩም በመጀመሪያው ቀን ዕረፍት፥ በመለከት ድምፅ መታሰቢያ፥ የተቀደሰች ጉባኤ ትሁንላችሁ።'),
  ('279da017-8d04-5042-afff-929abdf4bae0', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '22f2b0f8-7b67-5512-ad8e-13a4478f0fa1', 3, 25, 'የተግባር ሥራ ሁሉ አታድርጉባት፤ ለእግዚአብሔር የሚቃጠል መሥዋዕት አቅርቡ።”'),
  ('59dab59d-8bfe-52c3-ac00-1547db406820', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '1af22b0c-4270-5cc8-af93-f02ce622acee', 1, 26, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('cff2cfbd-1195-54f1-ab6f-adb2b0adfa8e', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '1af22b0c-4270-5cc8-af93-f02ce622acee', 2, 27, '“በዚህ በሰባተኛው ወር ዐሥረኛዋ ቀን የማስተስረያ ቀን ናት፤ ቅድስት ጉባኤ ትሁንላችሁ፤ ሰውነታችሁን አስጨንቋት፤ ለእግዚአብሔርም የሚቃጠል መሥዋዕት አቅርቡ።'),
  ('0e209cc1-cf64-53f8-ae32-09f6348048a7', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '1af22b0c-4270-5cc8-af93-f02ce622acee', 3, 28, 'በአምላካችሁ በእግዚአብሔር ፊት ስለ እናንተ ማስተስረያ ትሆንላችሁ ዘንድ የማስተስረያ ቀን ናትና በዚያች ቀን ሥራ ሁሉ አትሥሩባት።'),
  ('e9973114-5cdd-513c-a3e3-77e48ed93aeb', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '1af22b0c-4270-5cc8-af93-f02ce622acee', 4, 29, 'በዚያችም ቀን ራሱን የማያዋርድ ሰው ሁሉ ከሕዝቡ ተለይቶ ይጥፋ።'),
  ('956d94bb-3955-5c0b-ab9b-65a907acbcb1', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '1af22b0c-4270-5cc8-af93-f02ce622acee', 5, 30, 'በዚያችም ቀን ሥራ የሚሠራ ሰው ከሕዝቡ መካከል ተለይቶ ይጠፋል።'),
  ('2ea6edc4-bc54-5162-ab3a-7dc4f59656a0', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '1af22b0c-4270-5cc8-af93-f02ce622acee', 6, 31, 'ሥራ ሁሉ አታድርጉባት፤ በምትቀመጡበት ሀገር ሁሉ ለልጅ ልጃችሁ የዘለዓለም ሕግ ነው።'),
  ('4f312e65-8e4b-5410-a836-63bec3535f6b', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '1af22b0c-4270-5cc8-af93-f02ce622acee', 7, 32, 'የዕረፍት ሰንበት ትሁንላችሁ፤ ሰውነታችሁንም አዋርዱ፤ በወሩ በዘጠነኛው ቀን ከማታ ጀምራችሁ እስከ ዐሥረኛው ቀን ማታ ድረስ፥ ሰንበታችሁን አድርጉ።”'),
  ('9dad9ea6-ba6e-57bc-a117-38dbc3abbddc', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 1, 33, 'እግዚአብሔር ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('2d6bea4c-506d-548f-a582-fff87b6be28e', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 2, 34, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ በዚህ በሰባተኛው ወር ከዐሥራ አምስተኛው ቀን ጀምሮ ሰባት ቀን ለእግዚአብሔር የዳስ በዓል ይሆናል።'),
  ('fcfb3ea0-c8a1-5335-af85-01b0826fa8e9', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 3, 35, 'የመጀመሪያዋ ቀን ቅድስት ጉባኤ ትሁንላችሁ፤ የተግባር ሥራ ሁሉ አታድርጉባት።'),
  ('435136e5-f043-5721-ae6f-ee326420d1f6', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 4, 36, 'ሰባት ቀን ለእግዚአብሔር የሚቃጠል መሥዋዕት አቅርቡ፤ ስምንተኛዋም ቀን የተቀደሰች ጉባኤ ትሁንላችሁ፤ ለእግዚአብሔርም የሚቃጠለውን መሥዋዕት አቅርቡ፤ የመሰናበቻ በዓል ነውና፤ የተግባር ሥራ ሁሉ አትሥሩበት።'),
  ('9bb87f74-fefa-58e7-a3a1-aaa6b75c36b2', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 5, 37, '“የሚቃጠለውን መሥዋዕት፥ የእህሉንም ቍርባን፥ መሥዋዕቱንም፥ የመጠጡንም ቍርባን፥ በየቀኑ የሚቃጠል መሥዋዕት ለእግዚአብሔር ታቀርቡባቸው ዘንድ የተቀደሱ በዓላት እንዲሆኑ የምታውጁአቸው የእግዚአብሔር በዓላት እነዚህ ናቸው።'),
  ('c90d57c8-5dbd-5c7f-a38a-dc4f4de78e8c', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 6, 38, 'እነዚህም ከእግዚአብሔር ሰንበታት ሌላ፥ ለእግዚአብሔርም ከምትሰጡት ከስጦታችሁ ሌላ፥ ከስእለቶቻችሁም ሁሉ ሌላ፥ በፈቃዳችሁም ከምታቀርቡአቸው ሁሉ ሌላ ናቸው።'),
  ('d24fe437-878e-5c38-a91e-df4690d6f5f7', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 7, 39, 'ከሰባተኛውም ወር በዐሥራ አምስተኛው ቀን የምድሩን ፍሬ ካከማቻችሁ በኋላ፥ የእግዚአብሔርን በዓል ሰባት ቀን ታደርጋላችሁ፤ የመጀመሪያዋ ቀን ዕረፍት ትሁን፤ ስምንተኛዋም ቀን ዕረፍት ትሁን።'),
  ('084dcce8-963e-50d1-a2f3-fee2dce82f37', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 8, 40, 'በመጀመሪያዋ ቀን የመልካም ዛፍ ፍሬ፥ የዘንባባውንም ቅርንጫፍ፥ የለመለመውንም ዛፍ ቅርንጫፍ፥ የወንዝም አኻያ ዛፍ ውሰዱ፤ በአምላካችሁም በእግዚአብሔር ፊት በየዓመቱ ሰባት ቀን ደስ ይበላችሁ።'),
  ('92316471-8ffd-50ea-a794-9aae5ece8621', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 9, 41, 'በየዓመቱ በሰባተኛው ወር ይህን በዓል ታደርጉ ዘንድ ለልጅ ልጃችሁ የዘለዓለም ሕግ ይሁንላችሁ።'),
  ('a2384efc-7703-57d6-a0ed-e34aa3b1cc14', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 10, 42, 'ሰባት ቀን በዳሶች ውስጥ ትቀመጣላችሁ፤'),
  ('a0dc5acf-6d76-5e9c-a8e6-dfe2d6d69988', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 11, 43, 'ከግብፅ ምድር ባወጣኋቸው ጊዜ የእስራኤልን ልጆች በዳስ ውስጥ እንዳስቀመጥኋቸው የልጅ ልጆቻችሁ ያውቁ ዘንድ፥ በእስራኤል ያሉት የሀገር ልጆች ሁሉ በዳስ ውስጥ ይቀመጡ፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።”'),
  ('e9b7b576-e4f1-5e5d-a6db-f7018f4d25d1', '747dfc0a-31c8-55de-a36e-f0b620f6e5e2', '3113a32b-6839-5b82-ab73-2773d159136c', 12, 44, 'ሙሴም የጌታን የእግዚአብሔርን በዓላት ሁሉ ለእስራኤል ልጆች ተናገረ።'),
  ('2e748f53-b6ee-5836-add9-779183b25994', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'bfccf085-d465-5aef-ac57-1b78345974bc', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('1e119c65-1e45-566b-a859-e52228cd5df3', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'bfccf085-d465-5aef-ac57-1b78345974bc', 2, 2, '“መብራቱን ሁል ጊዜ እንድታበራበት ለመብራት ጥሩ ተወቅጦ የተጠለለ የወይራ ዘይት ያመጡልህ ዘንድ የእስራኤልን ልጆች እዘዛቸው።'),
  ('9f08ea86-9d76-5ac0-acd4-93b070cdca72', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'bfccf085-d465-5aef-ac57-1b78345974bc', 3, 3, 'በምስክሩ ድንኳን ከመጋረጃው ውጭ አሮንና ልጆቹ ከማታ እስከ ማለዳ ድረስ በእግዚአብሔር ፊት ሁል ጊዜ ያበሩታል፤ ለዘለዓለም ለልጅ ልጃችሁ ሥርዐት ይሁን።'),
  ('52ea2e6b-8e3d-5598-a421-dd2175aaf225', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'bfccf085-d465-5aef-ac57-1b78345974bc', 4, 4, 'በእግዚአብሔር ፊት በጥሩ መቅረዝ ላይ መብራቶቹን ሁል ጊዜ እስኪነጋ አብሩአቸው።'),
  ('e4530f47-88a6-57a0-a691-cc9929415a61', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'edb5328e-db4e-58ab-a5c8-4c3a32cf910f', 1, 5, '“የስንዴ ዱቄት ወስደህ ዐሥራ ሁለት ኅብስት ጋግር፤ በእያንዳንዱ ኅብስት ውስጥ ከመስፈሪያው ከዐሥር እጅ ሁለት እጅ ይሁን።'),
  ('aba5a257-3832-5095-a306-e4b1034ce6ed', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'edb5328e-db4e-58ab-a5c8-4c3a32cf910f', 2, 6, 'እነዚህንም ስድስት ስድስቱን በሁለት ተርታ አድርገህ በእግዚአብሔር ፊት በንጹሕ ገበታ ላይ አኑራቸው።'),
  ('c53f7652-ec0a-56a6-a9be-6d274afe3125', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'edb5328e-db4e-58ab-a5c8-4c3a32cf910f', 3, 7, 'በሁለቱም ተራ ንጹሕ ዕጣንና ጨው ታደርጋለህ፤ እነዚህም ነገሮች በእግዚአብሔር ፊት ለመታሰቢያ ለተዘጋጁት ኅብስቶች ይሁኑ።'),
  ('89165e83-4c60-5575-a6ed-9800a311132f', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'edb5328e-db4e-58ab-a5c8-4c3a32cf910f', 4, 8, 'በእግዚአብሔር ፊት ሁል ጊዜ በሰንበት ቀን ሁሉ ያድርጉት፤ በእስራኤል ልጆች ዘንድ የዘለዓለም ቃል ኪዳን ነው።'),
  ('71d4e5f1-7143-54e1-aa58-4a02bc1b7b5b', 'a721b757-1e4c-5545-ada5-df2400a5c000', 'edb5328e-db4e-58ab-a5c8-4c3a32cf910f', 5, 9, 'ለአሮንና ለልጆቹም ይሁን፤ በእሳት ከተደረገው ከእግዚአብሔር ቍርባን ለዘለዓለም ሥርዐት ለእርሱ ቅዱሰ ቅዱሳን ነውና በተቀደሰ ስፍራ ይብሉት።”'),
  ('7ac0618a-ec84-5e6e-a5f2-f4f87a4104df', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 1, 10, 'አባቱ ግብፃዊ የነበረ የእስራኤላዊት ሴት ልጅ በእስራኤል ልጆች መካከል ወጣ፤ የእስራኤላዊቱ ሴት ልጅና አንድ እስራኤላዊ ሰው በሰፈር ውስጥ ተጣሉ፤'),
  ('dd6cf472-305f-5bd2-a59f-f2857685eb7e', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 2, 11, 'የእስራኤላዊቱም ሴት ልጅ የእግዚአብሔርን ስም ጠርቶ ሰደበ፤ ወደ ሙሴም አመጡት። እናቱም ከዳን ነገድ የዳቤር ልጅ ነበረች፤ ስምዋም ሰሎሚት ነበረ።'),
  ('f4c032d5-d152-588e-a2b9-51a753cd23e0', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 3, 12, 'በእግዚአብሔርም ትእዛዝ እስኪፈርዱበት ድረስ በግዞት አኖሩት።'),
  ('80265299-7ab7-5dce-afe6-932e9ed3d0a0', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 4, 13, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('f29a4351-e517-5f9f-ab2d-fc7f5ab882e4', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 5, 14, '“ተሳዳቢውን ከሰፈር ወደ ውጭ አውጣው፤ የሰሙትም ሁሉ እጃቸውን በራሱ ላይ ይጫኑበት፤ ማኅበሩም ሁሉ በድንጋይ ይውገሩት።”'),
  ('90f2d6ec-ed76-56aa-a859-f104748748be', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 6, 15, 'ለእስራኤል ልጆች እንዲህ ብለህ ትነግራለህ፥ “ማናቸውም ሰው አምላኩን ቢሰድብ ኀጢአቱን ይሸከማል።'),
  ('191d0b3e-a951-5bff-a7ef-4d479c98fd1b', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 7, 16, 'የእግዚአብሔርንም ስም ጠርቶ የሚሰድብ ሁሉ ፈጽሞ ይገደል፤ ማኅበሩም ሁሉ በድንጋይ ይውገሩት፤ መጻተኛ ወይም የሀገር ልጅ ቢሆን፥ የእግዚአብሔርን ስም ጠርቶ ቢሳደብ ይገደል።'),
  ('a533d0c6-2c4d-5a87-abfb-2357a8f69210', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 8, 17, 'ሰውን የገደለ ሰው ሁሉ ፈጽሞ ይገደል።'),
  ('2ee8b223-7670-506d-af22-2e860a99da8d', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 9, 18, 'እንስሳንም ቢገድል በነፍስ ፋንታ ነፍስ ይክፈል።'),
  ('6be84df7-e614-5646-a45f-babbf97db8b3', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 10, 19, 'ሰውም ባልንጀራውን ቢጎዳ፥ እርሱ እንዳደረገ እንዲሁ ይደረግበት።'),
  ('7b1a4c52-8649-594f-adad-06d8f4a3d487', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 11, 20, 'ስብራት በስብራት ፋንታ፥ ዐይን በዐይን ፋንታ፥ ጥርስ በጥርስ ፋንታ፥ ሰውን እንደ ጎዳ እንዲሁ ይደረግበት።'),
  ('5e5e6977-8023-5376-ab71-6fdba2cd9500', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 12, 21, 'ሰውንም የመታና የገደለ ፈጽሞ ይገደል።'),
  ('3bfb9455-5895-508b-a6d8-6d5cebe02de2', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 13, 22, 'እኔ እግዚአብሔር አምላካችሁ ነኝና ለመጻተኛና ለሀገር ልጅ አንድ ዐይነት ሕግ ይሁንላችሁ።”'),
  ('f47f7a38-3c84-5ccf-a0b7-742663aaa787', 'a721b757-1e4c-5545-ada5-df2400a5c000', '7285852b-1a89-5446-ac86-ec569566e44d', 14, 23, 'ሙሴም ለእስራኤል ልጆች ተናገራቸው፤ ተሳዳቢውንም ከሰፈር ወደ ውጭ አወጡት፤ በድንጋይም ወገሩት። የእስራኤልም ልጆች እግዚአብሔር ሙሴን እንዳዘዘው አደረጉ።'),
  ('9aee4da9-fb7d-5a57-a979-b6883d41de6e', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '867e48a9-a405-5a8b-ad95-449c104da34b', 1, 1, 'እግዚአብሔርም ሙሴን በሲና ተራራ ላይ እንዲህ ብሎ ተናገረው፦'),
  ('e0fd294a-b9d9-560a-ad62-64623aa4c3ed', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '867e48a9-a405-5a8b-ad95-449c104da34b', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ እኔ ወደምሰጣችሁ ምድር በገባችሁ ጊዜ እኔ የምሰጣችሁ ምድር ታርፋለች፤ ለእግዚአብሔርም ሰንበት ታደርጋለች።'),
  ('775b1240-ffdd-5701-ab78-906bf8bec2c1', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '867e48a9-a405-5a8b-ad95-449c104da34b', 3, 3, 'ስድስት ዓመት እርሻህን ትዘራለህ፤ ስድስት ዓመትም ወይንህን ትቈርጣለህ፤ ፍሬዋንም ትሰበስባለህ።'),
  ('00cdd531-3e8f-5a37-aefb-829f1d69fbb9', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '867e48a9-a405-5a8b-ad95-449c104da34b', 4, 4, 'በሰባተኛው ዓመት ግን ሰንበት ነው፤ የምድር ዕረፍት ነው፤ ለእግዚአብሔር ሰንበት ነው፤ እርሻህን አትዝራ፤ ወይንህንም አትቍረጥ።'),
  ('efdfff4f-6042-5b0a-a030-f338e3fa2a28', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '867e48a9-a405-5a8b-ad95-449c104da34b', 5, 5, 'የምድራችሁን ገቦ አትጨደው፤ የተቀደሰውንም የወይንህን ፍሬ አታከማች፤ ለምድሪቱ የዕረፍት ዓመት ይሆናል።'),
  ('ff9d63e5-9dc2-594a-a656-b42830c2680b', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '867e48a9-a405-5a8b-ad95-449c104da34b', 6, 6, 'የምድርም ሰንበት ለአንተ፥ ለወንድ ባሪያህም፥ ለሴት ባሪያህም፥ ለምንደኛም፥ ከአንተ ጋር ለሚኖር ለመጻተኛም ምግብ ይሁን።'),
  ('b29513c3-1137-5f61-afef-27aef78d3645', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '867e48a9-a405-5a8b-ad95-449c104da34b', 7, 7, 'ለእንስሶችህም፥ በምድርህም ላሉት አራዊት ፍሬዋ ሁሉ ምግብ ይሁን።'),
  ('ad3de0cf-9985-504a-a2e7-7065a1472d5b', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 1, 8, '“የዓመታትን ሰባት ሰንበቶች ሰባት ጊዜ ሰባት ለራስህ ትቈጥራለህ፤ እነዚህም ሰባት የዓመታት ሱባዔያት አርባ ዘጠኝ ዓመታት ይሆናሉ።'),
  ('d80d0130-3e78-5107-a56e-b7e2444e116a', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 2, 9, 'ከዚያም በኋላ በሰባተኛው ወር ከወሩ በዐሥረኛው ቀን በምድራችሁ ሁሉ በቀንደ መለከት ታውጃለህ፤ በማስተስረያ ቀን በምድራችሁ ሁሉ በቀንደ መለከት ታውጃላችሁ።'),
  ('c3293d62-157e-5d04-ac18-7cce1b137596', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 3, 10, 'አምሳኛውንም ዓመት ትቀድሳላችሁ፤ በምድሪቱም ለሚኖሩት ሁሉ ነጻነትን ታውጃላችሁ፤ እርሱ ለእናንተ ኢዮቤልዩ ነው፤ ሰው ሁሉ ወደ ርስቱና ወደ ወገኑ ይመለስ።'),
  ('e69c58bf-2022-537d-ac82-5c17ddb92ab8', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 4, 11, 'ያ አምሳኛው ዓመት ለእናንተ ኢዮቤልዩ ይሆናል፤ በእርሱም አትዝሩ፤ የገቦውንም አትጨዱ፤ የተቀደሰውንም በእርሱ አትልቀሙ።'),
  ('42d2d7fe-4499-5a9a-a4b4-b63e836d3695', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 5, 12, 'ኢዮቤልዩ ነውና የተቀደሰ ይሁንላችሁ፤ በሜዳ ላይ የበቀለውን ብሉ።'),
  ('6968a49d-0ca6-5561-a700-0f0888a81cec', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 6, 13, '“በዚች ኢዮቤልዩ ዓመት ሰው ሁሉ ወደ ርስቱ ይመለሳል።'),
  ('bf42284c-eb1d-5831-a9b1-16ceca41d210', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 7, 14, 'ለባልንጀራህም አንዳች ብትሸጥለት፥ ወይም ከባልንጀራህ እጅ ብትገዛ፥ ሰው ባልንጀራውን አያስጨንቀው።'),
  ('373a3682-f753-52f4-a05e-73669a376c82', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 8, 15, 'ከኢዮቤልዩ ዓመት በኋላ እንደ ዓመታቱ ቍጥር ከባልንጀራህ ትገዛለህ፤ እርሱም እንደ መከሩ ዓመታት ቍጥር ይከፍልሃል።'),
  ('052b549d-eff0-5d09-a748-68aea03207fd', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 9, 16, 'እንደ ዓመታቱ ብዛት ዋጋውን ያበዛል፤ እንደ ዓመታቱም ማነስ ዋጋውን ያሳንሳል፤ እንደ መከሩ ቍጥር ይሸጥልሃል።'),
  ('68b27677-5548-5e86-a22d-cdcbb190d5af', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 10, 17, 'እኔም እግዚአብሔር አምላካችሁ ነኝና ሰው ባልንጀራውን አያስጨንቅ፤ ነገር ግን አምላክህን እግዚአብሔርን ፍራ።'),
  ('017d10af-0f23-54e0-a356-bc200888b93a', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 11, 18, '“ሥርዐቴንም አድርጉ፤ ፍርዴንም ጠብቁ፤ አድርጉትም፤ በምድሪቱም ውስጥ ተዘልላችሁ ትኖራላችሁ።'),
  ('2a5e1cdb-0bfa-5eb6-a648-9a0430770cdf', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 12, 19, 'ምድሪቱም ፍሬዋን ትሰጣለች፤ እስክትጠግቡም ድረስ ትበላላችሁ፤ በእርስዋም ውስጥ ተዘልላችሁ ትኖራላችሁ።'),
  ('117f80a6-d3c7-510e-af6f-958241f329aa', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 13, 20, 'እናንተም፦ ‘ካልዘራን፥ እህላችንንም ካላከማቸን በሰባተኛው ዓመት ምን እንበላለን?’ ብትሉ፥'),
  ('a2ae6d27-ee51-5f76-a6a8-63ae6e4755ed', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 14, 21, 'እኔ በስድስተኛው ዓመት በረከቴን በላያችሁ እሰጣለሁ፤ ምድሪቱም የሦስት ዓመት ፍሬ ታፈራለች።'),
  ('5a38e31f-5287-5144-abf1-8e87d123cffd', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', 'b92f7f50-9b20-5ec2-a473-f5c6a593e4f7', 15, 22, 'በስምንተኛውም ዓመት ትዘራላችሁ፤ ከከረመውም እህል ትበላላችሁ፤ ፍሬዋ እስኪገባ፥ እስከ ዘጠነኛው ዓመት ድረስ፥ ከከረመው እህል ትበላላችሁ።'),
  ('e9feacb9-6c5a-5ef3-ab84-654beac9879b', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 1, 23, '“ምድርም ለእኔ ናትና፥ እናንተም በእኔ ፊት እንግዶችና መጻተኞች ናችሁና ምድርን ለዘለዓለም አትሽጡ።'),
  ('ad3d1e6f-1887-5ecc-adb3-aea403c3b4b7', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 2, 24, 'በርስታችሁም ምድር ሁሉ መቤዠትን ለምድሪቱ አድርጉ።'),
  ('ec4f5852-59e4-5b62-af7f-ac07d769bd45', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 3, 25, 'ወንድምህም ቢደኸይ፥ ከርስቱም ቢሸጥ፥ ለእርሱ የቀረበ ዘመዱ መጥቶ ወንድሙ የሸጠውን ይቤዠዋል።'),
  ('b0408eef-c391-58ab-a77e-7419131115bd', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 4, 26, 'የሚቤዠውም ሰው ቢያጣ፥ እርሱም እጁ ቢረጥብ፥ ለመቤዠትም የሚበቃ ቢያገኝ፥'),
  ('e18190ce-ef98-525b-a680-e3f9769ff50b', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 5, 27, 'የሽያጩን ዘመን ቈጥሮ የቀረውን ወደ ገዛው ሰው ይመልስ፤ እርሱም ወደ ርስቱ ይመለስ።'),
  ('0793f84b-72cb-5cae-a9a4-8f224eac021d', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 6, 28, 'ለራሱም ዕዳውን መክፈል ባይችል፥ ሽያጩ በገዛው ሰው እጅ እስከ ኢዮቤልዩ ዓመት ድረስ ይቀመጥ፤ በኢዮቤልዩም ዓመት ይውጣ፤ እርሱም ወደ ርስቱ ይመለስ።'),
  ('984dfd43-edbe-5962-a4c3-1bd51c8899be', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 7, 29, '“ሰውም ቅጥር ባለበት ከተማ መኖርያ ቤትን ቢሸጥ፥ ከተሸጠ በኋላ አንድ ዓመት እስኪፈጸም ድረስ ለመቤዠት ይችላል፤ ለአንድ ሙሉ ዓመት መቤዠት ይችላል።'),
  ('87fcbedc-fed5-51e7-a0b1-f282f2383f84', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 8, 30, 'አንድ ዓመት እስኪጨረስ ባይቤዠው ቤቱ ለገዡ ይሆናል፤ ቅጥር ባለበት ከተማ ያለውን ያን ቤት ይመረምሩለታል፤ ለገዛው ሰው ለልጅ ልጁ ለዘለዓለም ይጸናለታል፤ በኢዮቤልዩ ዓመትም አይወስዱበትም።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8e0816d8-f324-52e7-a3db-3e66a85ebdba', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 9, 31, 'ቅጥር በሌለበት መንደር ያሉ ቤቶች ግን እንደ እርሻ ይቈጠራሉ፤ ይቤዣሉ፤ በኢዮቤልዩ ዓመትም ይመለሳሉ።'),
  ('7c48482e-bdc7-527f-acf9-43c31d2ec83b', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 10, 32, 'የሌዋውያንን ከተሞች፥ በከተሞቻቸውም ያሉ ቤቶቻቸውን ሌዋውያን ለዘለዓለም መቤዠት ይችላሉ።'),
  ('ad7c19bd-6660-5984-ac12-424a3b2c86db', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 11, 33, 'ማናቸውም ሰው ከሌዋውያን ቢገዛ፥ በእስራኤል ልጆች መካከል የሌዋውያን ከተሞች ቤቶች ርስቶቻቸው ናቸውና በርስቱ ከተማ ያለ የተሸጠው ቤት በኢዮቤልዩ ዓመት ይመለሳል።'),
  ('a3dcf456-d930-5ad0-a716-88e15c2870e7', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '7ea23ca0-12b5-52f3-a50d-00c0010029fa', 12, 34, 'በከተማዎቻቸው ዙሪያ ያሉ እርሻዎቻቸውም የዘለዓለም ርስቶቻቸው ናቸውና አይሸጡም።'),
  ('781ff863-2aeb-56b3-a800-888870614226', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '1e374f9d-5377-5835-ad1e-460fc7b1ec78', 1, 35, '“ከአንተ ጋር ያለው ወንድምህ ቢደኸይ፥ እጁም በአንተ ዘንድ ቢደክም እንደ እንግዳና እንደ መጻተኛ ትረዳዋለህ፤ ከአንተም ጋር ይኑር።'),
  ('3a13b301-d5f9-5b8d-a530-b742a3c258ff', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '1e374f9d-5377-5835-ad1e-460fc7b1ec78', 2, 36, 'ወንድምህ ከአንተ ጋር ይኖር ዘንድ ከእርሱ ምንም ወለድ ወይም ትርፍ አትውሰድ፤ ነገር ግን አምላክህን ፍራ፤ እኔ እግዚአብሔር ነኝና።'),
  ('e690d394-e739-56e4-ab4c-8d0cefaad197', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '1e374f9d-5377-5835-ad1e-460fc7b1ec78', 3, 37, 'ብርህን በወለድ አታበድረው፤ እህልህንም በትርፍ አትስጠው።'),
  ('5fc33357-2678-5f34-aeb5-7d049dbb33e0', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '1e374f9d-5377-5835-ad1e-460fc7b1ec78', 4, 38, 'የከነዓንን ምድር እሰጥህ ዘንድ፥ አምላክም እሆንህ ዘንድ ከግብፅ ምድር ያወጣሁህ እኔ እግዚአብሔር አምላክህ ነኝና።'),
  ('e17919c1-b524-5fb3-ac71-f3c578733679', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 1, 39, '“ወንድምህ ቢቸገር፥ ራሱንም ለአንተ ቢሸጥ፥ እንደ ባሪያ አድርገህ አትግዛው።'),
  ('73af21af-6156-5375-ac5a-46309c02b7e1', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 2, 40, 'እንደ ምንደኛና እንደ ስደተኛ ከአንተ ጋር ይሁን፤ እስከ ኢዮቤልዩ ዓመትም ያገልግልህ።'),
  ('85ffc76a-7ef4-52f1-ae9f-7bc45682537b', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 3, 41, 'በኢዮቤልዩ ዓመትም እርሱ ከልጆቹ ጋር ከአንተ ይወጣል፤ ወደ ወገኖቹም፥ ወደ አባቱም ርስት ይመለሳል።'),
  ('e05440a8-e743-570c-ad8c-f0b378d581e8', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 4, 42, 'ከግብፅ ምድር ያወጣኋቸው ባሪያዎች ናቸውና ባሪያ እንደሚሸጥ አይሸጡ።'),
  ('7bd55cc3-16b1-5da4-ac2a-2f3c5854ad5d', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 5, 43, 'በሥራ አታስጨንቀው፤ ነገር ግን አምላክህን እግዚአብሔርን ፍራ።'),
  ('5e9f84b4-7fda-5c71-a221-3d0c7399ffa1', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 6, 44, 'ምን ያህል ወንድ ባሪያና ሴት ባሪያ እንዲኖሩህ ብትፈልግ ግን በዙሪያችሁ ካሉት ከእነርሱ ከአሕዛብ ወንድና ሴት ባያሪያዎችን ግዙ።'),
  ('e29f6c7a-0382-5b97-a24c-27fbfd4a0c2f', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 7, 45, 'በእናንተ መካከል ከሚቀመጡት ስደተኞች ልጆች ለራሳችሁ ትገዛላችሁ፤ ከዘመዶቻቸውም በምድራችሁ የሚኖሩት ሁሉ ለርስታችሁ ይሁኑአችሁ።'),
  ('e8bdbff7-4740-59f1-a77b-f175176fa222', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 8, 46, 'ከእናንተም በኋላ ለልጆቻችሁ ታወርሱአቸዋላችሁ፤ እነርሱም ለእናንተ ለዘለዓለም ውርስ ይሆናሉ፤ ነገር ግን ከወንድሞቻችሁ ከእስራኤል ልጆች ማናቸውም ሰው ወንድሙን በሥራ አያስጨንቀው።'),
  ('761a5e82-2ad5-5ee7-aa68-fd4519c759dd', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 9, 47, '“በአንተም ዘንድ የሚኖር መጻተኛ ወይም እንግዳ ሀብታም ቢሆን፥ ወንድምህም በእርሱ አጠገብ ቢደኸይ፥ ራሱንም ለመጻተኛው፥ ወይም ለእንግዳው ወይም ለወገኖቹ ዘር ቢሸጥ፥'),
  ('3bd7468d-0ba6-52fb-a8b8-f4381383abc3', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 10, 48, 'ከተሸጠ በኋላ መቤዠት ይችላል፤ ከወንድሞቹ አንዱ ይቤዠው፤'),
  ('ecb461ee-a14c-5253-a8bd-32edb00895b6', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 11, 49, 'ወይም አጎቱ ወይም የአጎቱ ልጅ ይቤዠው፤ ወይም ከወገኑ ለእርሱ የቀረበ ዘመድ ይቤዠው፤ ወይም እርሱ እጁ ቢረጥብ ራሱን ይቤዠው።'),
  ('44436419-d750-57b9-a687-4e88f38265cc', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 12, 50, 'ከገዛውም ሰው ጋር ከገዛበት ዓመት ጀምሮ እስከ ኢዮቤልዩ ዓመት ድረስ ይቍጠር፤ የሽያጩም ብር እንደ ዓመታቱ ቍጥር ይሁን፤ እንደ ምንደኛውም ዘመን ከእርሱ ጋር ይሁን።'),
  ('e552b0ff-ba5f-59ac-af15-07be53478cbc', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 13, 51, 'ብዙ ዓመታትም ቢቀሩ እንደ እነርሱ ቍጥር ከሽያጩ ብር የመቤዠቱን ዋጋ ይመልስ።'),
  ('5ddf689a-fb48-5085-acf1-1d305e57fb5e', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 14, 52, 'እስከ ኢዮቤልዩ ዓመት ድረስ ጥቂት ዓመታት ቢቀሩ እንደ ዓመቱ ይቍጠሩለት፤ እንደ ኣመታቱም መጠን የመቤዠቱን ዋጋ ይመልስ።'),
  ('37fb1acd-3a4a-5bfd-abbd-d8b4df1954d5', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 15, 53, 'በየዓመቱ እንደ ምንደኛ ከእርሱ ጋር ይኑር፤ በፊትህ እንደ ቀደመው አያስጨንቀው።'),
  ('cb3843b9-f89d-50eb-a34b-d3daf6225293', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 16, 54, 'በዚህ ዘመን ሁሉ ግን ባይቤዥ በኢዮቤልዩ ዓመት እርሱ ከልጆቹ ጋር ይውጣ።'),
  ('79bb8100-6ff9-5da7-a7a4-1675102f5be2', 'b71e75c9-38e3-5ed4-ac4d-7944691bab13', '8ab91db9-e824-5971-aadf-1edc0e5a9124', 17, 55, 'የእስራኤል ልጆች ለእኔ ባሪያዎች ናቸውና፤ ከግብፅ ምድር ያወጣኋቸው ባሪያዎች ናቸው፤ እኔ እግዚአብሔር አምላካችሁ ነኝ።'),
  ('b183064a-ceb4-5eab-a554-5580a6a416a8', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 1, 1, '“ለእናንተ በእጅ የተሠራ ጣዖት አታድርጉ፤ የተቀረጸም ምስል ወይም ሐውልት አታቁሙ፤ ትሰግዱለትም ዘንድ በምድራችሁ ላይ የተቀረጸ ድንጋይ አታኑሩ፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።'),
  ('9ac367a4-741c-5c99-a8b2-36943ed59437', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 2, 2, 'ሰንበታቴንም ጠብቁ፤ የቀደስኋቸውንም ፍሩ፤ እኔ እግዚአብሔር ነኝና።'),
  ('b9060bb8-f850-5ec3-a34f-626954ce4ba3', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 3, 3, '“በሥርዐቴ ብትሄዱ፥ ትእዛዛቴንም ብትጠብቁ፥ ብታደርጉትም፥'),
  ('d80b9c86-9fe4-57b8-aec3-ffa8af97b47c', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 4, 4, 'ዝናሙን በወቅቱ አዘንማለሁ፤ ምድሪቱም እህልዋን ትሰጣለች፤ የሜዳው ዛፎችም ፍሬያቸውን ይሰጣሉ።'),
  ('5c087d11-5d2f-5be4-a2c7-326999ee17b5', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 5, 5, 'የእህሉም ማበራየት በእናንተ ዘንድ እስከ ወይኑ መቈረጥ ይደርሳል፤ የወይኑም መቈረጥ እስከ እህሉ መዝራት ይደርሳል፤ እስክትጠግቡም ድረስ እንጀራችሁን ትበላላችሁ፤ በምድራችሁም ላይ ተዘልላችሁ ትኖራላችሁ።'),
  ('c9fb2f93-17cd-5df5-aed7-fb86cfc989ed', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 6, 6, 'በምድራችሁም ላይ ሰላምን እሰጣለሁ፤ ትተኛላችሁ፤ የሚያስፈራችሁም የለም፤ ክፉዎችንም አራዊት ከምድራችሁ አጠፋለሁ።'),
  ('8529817d-5917-5dd6-a70a-d48c4411a0c1', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 7, 7, 'ጠላቶቻችሁንም ታሳድዳላችሁ፤ በፊታችሁም በሰይፍ ይወድቃሉ።'),
  ('f3268660-a100-5f91-aeea-f7597f40b703', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 8, 8, 'ከእናንተም አምስቱ መቶውን ያሳድዳሉ፤ መቶውም ዐሥሩን ሺህ ያሳድዳሉ፤ ጠላቶቻችሁም በፊታችሁ በሰይፍ ይወድቃሉ።'),
  ('9f0f6d79-11d7-518a-acc6-aa2c2549c9b2', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 9, 9, 'ወደ እናንተም እመለከታለሁ፤ አባዛችኋለሁ፤ ከፍ ከፍም አደርጋችኋለሁ፤ ቃል ኪዳኔንም ከእናንተ ጋር አጸናለሁ።'),
  ('84208f3f-ffa1-544c-acad-3d1adf6fac5d', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 10, 10, 'ብዙ ጊዜ የተቀመጠውን፥ የከረመውንም እህል ትበላላችሁ፤ አዲሱንም ታስገቡ ዘንድ የከረመውን ታወጣላችሁ።'),
  ('6921ac3d-6d13-50f5-a80d-801c88c1a8e9', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 11, 11, 'ማደሪያዬንም በእናንተ መካከል አደርጋለሁ፤ ነፍሴም አትጸየፋችሁም።'),
  ('f35deadf-1a6c-516b-a971-ffeda07000ec', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 12, 12, 'በመካከላችሁም እመላለሳለሁ፤ እኔም አምላክ እሆናችኋለሁ፤ እናንተም ሕዝብ ትሆኑልኛላችሁ።'),
  ('02bfdab2-fe1b-5674-a08d-ef1146c26ae4', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '95bf6720-32c5-56d1-abce-aba5a5049487', 13, 13, 'ባሪያዎች ከነበራችሁበት ከግብፅ ምድር ያወጣኋችሁ እኔ እግዚአብሔር አምላካችሁ ነኝ፤ የባርነታችሁን ቀንበር ሰብሬአለሁ፤ በግልጽም አወጣኋችሁ።'),
  ('79e7677b-f157-5e71-a725-8d0f90c3e73b', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 1, 14, '“ነገር ግን ባትሰሙኝ፥ እነዚህንም ትእዛዛት ሁሉ ባታደርጉ፥'),
  ('4513fcf6-dd60-57b8-a732-b36e0bcc5fe0', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 2, 15, 'ሥርዐቴንም ብትንቁ፥ ትእዛዛቴንም ሁሉ እንዳታደርጉ፥ ቃል ኪዳኔንም እንድታፈርሱ ሰውነታችሁ ፍርዴን ብትሰለች፥'),
  ('4844394f-a93a-5611-aa7e-a3a501fe74a9', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 3, 16, 'እኔም እንዲህ አደርግባችኋለሁ፤ ፍርሀትን፥ ክሳትንም፥ ዐይናችሁንም የሚያፈዝዝ፥ ሰውነታችሁንም የሚያጠፋ ትኩሳት አወርድባችኋለሁ፤ ዘራችሁንም በከንቱ ትዘራላችሁ፤ ጠላቶቻችሁ ይበሉታልና።'),
  ('a1c6e4e8-9e63-5cef-a415-fc7aa97fdf0b', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 4, 17, 'ፊቴንም አከብድባችኋለሁ፤ በጠላቶቻችሁም ፊት ትወድቃላችሁ፤ የሚጠሏችሁም ያሸንፉአችኋል። ማንም ሳያሳድዳችሁ ትሸሻላችሁ።'),
  ('85c85930-5bba-5866-a8ba-329d53d345c2', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 5, 18, 'እስከዚህም ድረስ ባትሰሙኝ፥ ስለ ኀጢአታችሁ በቅጣታችሁ ላይ ሰባት እጥፍ መቅሠፍትን እጨምራለሁ።'),
  ('a074804e-a28a-5bf2-a355-0e48d5e37a83', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 6, 19, 'የትዕቢታችሁን ስድብ አጠፋለሁ፤ ሰማያችሁንም እንደ ብረት፥ ምድራችሁንም እንደ ናስ አደርጋለሁ።'),
  ('0586d5cc-14eb-5b4b-aad5-ef05d3d7f0fc', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 7, 20, 'ጕልበታችሁም በከንቱ ያልቃል፤ ምድራችሁም እህልዋን አትሰጥም፤ የዱር ዛፎችም ፍሬያቸውን አይሰጡም።'),
  ('85407797-f37c-587e-a91d-6c19ad606291', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 8, 21, '“ከዚያም በኋላ በእንቢተኝነት ብትሄዱብኝ፥ ልትሰሙኝም ባትፈቅዱ እንደ ኀጢአታችሁ መጠን በመቅሠፍት ላይ ሰባት እጥፍ እጨምራለሁ።'),
  ('147c6822-15c6-5d80-acec-077051318ddc', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 9, 22, 'በእናንተ ላይ ክፉዎች የምድርን አራዊት እሰድዳለሁ፤ ይበሉአችኋል፤ እንስሶቻችሁንም ያጠፋሉ፤ እናንተንም ያሳንሳሉ፤ መንገዶቻችሁም በረሃ ይሆናሉ።'),
  ('9c94df09-1960-571b-abb4-4a7d69a6b91e', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 10, 23, '“እስከዚህም ድረስ ባትቀጡ፥ አግድማችሁም ብትሄዱ፥'),
  ('ee783fc0-b409-5828-aa03-3fc9cd061e43', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 11, 24, 'እኔ ደግሞ አግድሜ በቍጣ እሄድባችኋለሁ፤ ስለ ኀጢአታችሁም ሰባት እጥፍ እበቀላችኋለሁ።'),
  ('a930eee9-10c5-5cdf-a7ad-84a0c0e4f7f0', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 12, 25, 'የቃል ኪዳኔንም በቀል ይበቀልባችሁ ዘንድ ሰይፍ አመጣባችኋለሁ፤ ወደ ከተማችሁም ትሸሻላችሁ፤ ቸነፈርንም እሰድድባችኋለሁ። በጠላቶቻችሁም እጅ ተላልፋችሁ ትሰጣላችሁ፤'),
  ('ca2d6282-a7b5-51d1-aac0-f2a483c83f37', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 13, 26, 'በእህል ረሃብ ባስጨነክኋችሁ ጊዜ ዐሥር ሴቶች እንጀራ በአንድ ምጣድ ይጋግራሉ፤ በሚዛንም መዝነው እንጀራችሁን ይመልሱላችኋል፤ በበላችሁም ጊዜ አትጠግቡም።'),
  ('416296b7-a5a6-5a98-a87f-2b1880754488', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 14, 27, 'እስከዚህም ድረስ ባትሰሙኝ፥ አግድማችሁም ብትሄዱብኝ፥'),
  ('275e16ca-e694-5eba-a7b9-01b711947ab4', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 15, 28, 'እኔ ደግሞ አግድሜ በቍጣ እሄድባችኋለሁ፤ እንደ ኀጢአታችሁም ሰባት እጥፍ እቀጣችኋለሁ።'),
  ('0e4d2e7c-db10-5af3-ab97-b6aaada368b3', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 16, 29, 'የወንዶች ልጆቻችሁንም ሥጋ ትበላላችሁ፤ የሴቶች ልጆቻችሁንም ሥጋ ትበላላችሁ።'),
  ('7ea4f8e3-bb93-552f-af29-083be13dc945', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 17, 30, 'የኮረብታ መስገጃዎቻችሁን አፈርሳለሁ፤ በእጅ የተሠሩ የዕንጨት ምስሎቻችሁንም አጠፋለሁ፤ ሬሳችሁንም በጣዖቶቻችሁ ሬሳዎች ላይ እጥላለሁ፤ ነፍሴም ትጸየፋችኋለች።'),
  ('c487c9e1-4c73-58bb-ac74-4271fbb3b123', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 18, 31, 'ከተሞቻችሁንም ባድማ አደርጋለሁ፤ መቅደሶቻችሁንም አፈርሳለሁ፤ የመሥዋዕታችሁንም መዓዛ አላሸትትም።'),
  ('a742ab0f-5e8f-5822-a5dc-7117377579e7', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 19, 32, 'ምድሪቱንም የተፈታች አደርጋለሁ፤ የሚቀመጡባት ጠላቶቻችሁም ከእርስዋ የተነሣ ይደነቃሉ።'),
  ('54468f7d-88c6-56e1-a54e-64d84097646f', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 20, 33, 'እናንተንም በአሕዛብ መካከል እበትናችኋለሁ፤ በሄዳችሁበትም ሁሉ ሰይፍ ታጠፋችኋለች፤ ምድራችሁም የተፈታች ትሆናለች፤ ከተሞቻችሁም ባድማ ይሆናሉ።'),
  ('5d2110e3-159c-57df-a629-445fac1fa5c2', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 21, 34, '“በዚያም በተፈታችበት ዘመን ሁሉ እናንተም በጠላቶቻችሁ ምድር ሳላችሁ፥ ምድሪቱ ሰንበት በማድረግዋ ደስ ይላታል፤ በዚያም ጊዜ ምድሪቱ ታርፋለች፤ ስንበትንም በማድረግዋ ደስ ይላታል።'),
  ('939d1aee-2d08-5e65-ae91-866c9c6eb616', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 22, 35, 'እናንተ ተቀምጣችሁባት በነበረ ጊዜ በሰንበቶቻችሁ አላረፈችም ነበርና በተፈታችበት ዘመን ሁሉ ታርፋለች።'),
  ('bb474969-db60-5e78-a422-2fdaffc53d27', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 23, 36, 'በጠላቶቻቸውም ምድሮች ሳሉ ከእናንተ ተለይተው በቀሩት ላይ በልባቸው ድንጋጤን እሰድድባቸዋለሁ፤ በነፋስም የምትንቀሳቀስ የቅጠል ድምፅ ታሸብራቸዋለች፤ ከሰይፍ እንደሚሸሹ ይሸሻሉ ፤'),
  ('2af7b276-c209-538f-a7d3-47fe9b59a4d5', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 24, 37, 'ማንም ሳያሳድዳቸው ከሰይፍ እንዲሸሹ እርስ በርሳቸው ይሰነካከላሉ፤ እናንተም በጠላቶቻችሁ ፊት መቆም አትችሉም።'),
  ('82863e7e-d877-50ef-a158-e5a5aec56976', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 25, 38, 'በአሕዛብም መካከል ትጠፋላችሁ፤ የጠላቶቻችሁም ምድር ትውጣችኋለች።'),
  ('c22bcda0-b955-5b8e-a7af-e9b1cff97de3', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 26, 39, 'ከእናንተም ተለይተው የቀሩት ስለ ኀጢአታቸው ይጠፋሉ፤ በአባቶቻቸውም ኀጢአት ደግሞ በጠላቶቻቸው ምድር ይቀልጣሉ።'),
  ('3f023d5b-5b3e-595e-a1c0-69c5f54a9a4e', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 27, 40, '“እንደ ከዱኝ፥ ቸልም እንዳሉኝ፥ በፊቴም አግድመው እንደ ሄዱ፥ ኀጢአታቸውንና፥ የአባቶቻቸውን ኀጢአት ይናዘዛሉ።'),
  ('2c326425-c324-533d-a549-9895e6945f99', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 28, 41, 'እኔም ደግሞ አግድሜ ከእነርሱ ጋር በቍጣ ሄድሁ፤ በጠላቶቻቸውም ምድር አጠፋቸዋለሁ። ነገር ግን በዚያን ጊዜ ያልተገረዘው ልባቸው ያፍራል፤ ስለ ኀጢአታቸውም ይናዘዛሉ፤'),
  ('d1e0f3bd-aa03-5c89-a1ba-6440b3fcc4fa', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 29, 42, 'ያን ጊዜ እኔ ከያዕቆብ ጋር የገባሁትን ቃል ኪዳኔን አስባለሁ፤ ደግሞም ከይስሐቅ ጋር የገባሁትን ቃል ኪዳኔን፥ ከአብርሃምም ጋር የገባሁትን ቃል ኪዳኔን አስባለሁ፤ ምድሪቱንም አስባለሁ።'),
  ('ebfff38f-d679-5199-a289-41d3933a680c', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 30, 43, 'ምድርም ከእነርሱ መጥፋት የተነሣ ባዶ ትቀራለች፤ እነርሱም ሳይኖሩ በተፈታችበት ዘመን ዕረፍት ታደርጋለች፤ ፍርዴንም ስለ ናቁ፥ ነፍሳቸውም ሥርዐቴን ስለ ተጸየፈች የኀጢአታቸውን ቅጣት ይሸከማሉ።'),
  ('67a7fdac-a0af-5039-ae49-d912b792fdd7', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 31, 44, 'ነገር ግን እኔ እግዚአብሔር አምላካቸው ነኝና እነርሱ በጠላቶቻቸው ምድር ሳሉ፥ እስካጠፋቸው ድረስ ከእነርሱም ጋር ያለኝን ቃል ኪዳን እስካፈርስ ድረስ አልጥላቸውም፤ አልጸየፋቸውምም።'),
  ('518c8dad-8d63-5c44-a184-20442f8fc4a9', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 32, 45, 'እኔ አምላካቸው እሆን ዘንድ አሕዛብ እያዩ ከግብፅ ምድር ከግዞት ቤት እንዳወጣኋቸው የቀድሞ ቃል ኪዳናቸውን ስለ እነርሱ አስባለሁ፤ እኔ እግዚአብሔር ነኝና።”'),
  ('98cfa820-1bdf-51fe-a0b9-afcbde6ae339', 'f75dd2cc-0b0d-5217-ab99-fe93c7c82c04', '0f21d37f-8d61-5ec5-ad59-76e8ab86974c', 33, 46, 'እግዚአብሔርም በእርሱና በእስራኤል ልጆች መካከል በሲና ተራራ ላይ በሙሴ እጅ የሰጣቸው ሥርዐቶችና ፍርዶች፥ ሕግጋትም እነዚህ ናቸው።'),
  ('12b8ec39-1315-569c-ae64-877a8bde43f4', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 1, 1, 'እግዚአብሔር ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('983d96a1-51bc-5e0d-ae43-e003afa0ea1b', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ማናቸውም ሰው ስለ ነፍሱ ቤዛ ለእግዚአብሔር ስእለት ቢሳል አንተ እንደምትገምተው መጠን ስለ ሰውነቱ ዋጋውን ይስጥ።'),
  ('2b5bbe7d-9777-5638-a1d1-83f22068bd35', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 3, 3, 'ለወንድ ከሃያ ዓመት ጀምሮ እስከ ስድሳ ዓመት ድረስ እንደ መቅደሱ ሚዛን ግምቱ አምሳ የብር ዲድርክም ይሁን።'),
  ('46bf4255-3753-5382-abd4-006be86823ed', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 4, 4, 'ሴትም ብትሆን ግምቷ ሠላሳ የብር ዲድርክም ይሁን።'),
  ('675a8ab2-8999-5895-a757-4d968a095cb0', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 5, 5, 'ከአምስት ዓመትም ጀምሮ እስከ ሃያ ዓመት ድረስ ግምቱ ለወንድ ሃያ የብር ዲድርክም፥ ለሴትም ዐሥር የብር ዲድርክም ይሁን።'),
  ('64b3898e-c66a-54a1-a006-a2bf1dcf1053', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 6, 6, 'ከአንድ ወርም እስከ አምስት ዓመት ድረስ ለወንድ ግምቱ አምስት የብር ዲድርክም፥ ለሴትም ግምቷ ሦስት የብር ዲድርክም ይሁን።'),
  ('00ddc4ba-61f1-5a66-ac7c-19cfcc61483a', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 7, 7, 'ከስድሳ ዓመትም ጀምሮ ከዚያም በላይ ወንድ ቢሆን ግምቱ ዐሥራ አምስት ዲድርክም፥ ለሴትም ዐሥር ዲድርክም ይሁን።'),
  ('90ffbbcc-9438-517d-a8fd-5548c901b0cc', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 8, 8, 'ለግምቱ የሚከፍለውን ቢያጣ ግን በካህኑ ፊት ይቁም፤ ካህኑም የተሳለውን ሰው ከእጁ ባለው ገንዘብ መጠን ይገምትለት፤ ካህኑም የተሳለው ሰው እንደሚችል መጠን ይገምትለት።'),
  ('95b42a5d-8bd8-5e25-a209-137a1007c1f7', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 9, 9, '“ለእግዚአብሔርም መሥዋዕት አድርጎ የሚያቀርበው እንስሳ ቢሆን፥ ሰው ከእነዚህ ለእግዚአብሔር የሚሰጠው ሁሉ ቅዱስ ይሆናል።'),
  ('0e3a9943-8c39-55e9-ac31-5337ee5813ef', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 10, 10, 'መልካሙን በክፉ፥ ክፉውንም በመልካም አይለውጥ፤ እንስሳንም በእንስሳ ቢለውጥ እርሱና ልዋጩ የተቀደሱ ይሆናሉ።'),
  ('8df692ed-b442-5a94-a651-2ce70d62b00b', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 11, 11, 'እንስሳው ለእግዚአብሔር መሥዋዕት መሆን የማይገባው ርኩስ ቢሆን፥ እንስሳውን በካህኑ ፊት ያቁመው።'),
  ('43c7ba4e-8cb7-5efa-ae07-4be9e12f837a', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 12, 12, 'መልካምም ቢሆን ክፉም ቢሆን ካህኑ ይገምተው፤ ካህኑም እንደሚገምተው መጠን እንዲሁ ይሁን።'),
  ('57fc2e4b-17c7-5fc5-ab42-fdc74d24d17f', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 13, 13, 'ይቤዠው ዘንድ ቢወድድ ግን ከግምቱ በላይ አምስተኛ እጅ ይጨምር።'),
  ('4d35f102-376e-540a-a979-0bab4da70f9a', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 14, 14, '“ሰውም ለእግዚአብሔር ቅዱስ ይሆን ዘንድ ቤቱን ቢቀድስ፥ ካህኑ መልካም ወይም ክፉ እንደ ሆነ ይገምተዋል፤ ካህኑም እንደሚገምተው መጠን እንዲሁ ይቆማል።'),
  ('3ea97598-2dcd-5934-ae46-989331a91bde', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 15, 15, 'የተሳለውም ሰው ቤቱን ይቤዠው ዘንድ ቢወድድ ከግምቱ ገንዘብ በላይ አምስተኛ እጅ ይጨምር፤ ቤቱም ለእርሱ ይሆናል።'),
  ('d1cac072-2f65-5be4-aeb5-5e0d11a39fc2', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 16, 16, '“ሰውም ከርስቱ እርሻ ለእግዚአብሔር ቢሳል፥ እንደ መዘራቱ መጠን ይገመት፤ አንድ የቆሮስ መስፈሪያ ገብስ የሚዘራበት እርሻ አምሳ ወቄት ብር ይገመታል።'),
  ('0a145b8b-5c1d-5b3a-aaa2-9135c0cc5f3d', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 17, 17, 'እርሻውንም ከኢዮቤልዩ ዓመት ጀምሮ ቢሳል፥ እንደ ግምቱ መጠን ይቆማል።'),
  ('fd438130-2a11-5ced-a8a8-bed50b70f307', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 18, 18, 'እርሻውንም ከኢዮቤልዩ ዓመት በኋላ ቢሳል፥ ካህኑ እስከ ኢዮቤልዩ ዓመት ድረስ እንደ ቀሩት ዓመታት ገንዘቡን ይቈጥርለታል፤ ከግምቱም ይጐድላል።'),
  ('4b45d44d-6ade-5a0e-a25d-6f70c54d774c', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 19, 19, 'እርሻውንም የተሳለ ሰው ይቤዠው ዘንድ ቢወድድ፥ ከግምቱ ገንዘብ በላይ አምስተኛ እጅ ይጨምር፤ ለእርሱም ይሆናል።'),
  ('c01d93b6-e144-5fba-ab27-52bfaf1e6a39', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 20, 20, 'እርሻውንም ባይቤዠው፥ ወይም ለሌላ ሰው ቢሸጥ እንደ ገና ይቤዠው ዘንድ አይቻለውም።'),
  ('fc6c1ce2-02f1-56b2-adb4-f3ec1a9c90ed', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 21, 21, 'እርሻው ግን በኢዮቤልዩ ዓመት ሲወጣ ለእግዚአብሔር የተቀደሰ እርሻ ይሆናል፤ ርስቱም ለካህኑ ይሆናል።'),
  ('9a55aa7c-3584-556c-aaf6-b48435e33729', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 22, 22, 'ከርስቱ እርሻ ያልሆነውን የገዛውን እርሻ ለእግዚአብሔር ቢሳል፥'),
  ('fb3059c2-5cdf-541e-a80a-0fd88c68288c', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 23, 23, 'ካህኑ እስከ ኢዮቤልዩ ዓመት ድረስ የግምቱን ዋጋ ይቈጥርለታል፤ በዚያም ቀን ግምቱን እንደ ተቀደሰ ነገር ለእግዚአብሔር ይሰጣል።'),
  ('213d26f6-0a58-5fb4-a123-30e0462a9e96', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 24, 24, 'በኢዮቤልዩ ዓመት እርሻው የምድሪቱ ባለ ርስት ወደ ነበረው ወደ ሸጠው ሰው ይመለሳል፤ የራሱ ወሰን ምድር ነውና።'),
  ('f951857a-2e0e-5c38-a16b-539cb4c0c274', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 25, 25, 'ግምቱም ሁሉ እንደ መቅደሱ ሚዛን ይሆናል፤ አንዱ ዲድርክም ሃያ አቦሊ ይሆናል።'),
  ('80c58eb9-e1c7-57b3-aca7-d9a99dfe3ef8', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 26, 26, '“ከእንስሳህ የሚወለድ በኵር ሁሉ ለእግዚአብሔር ነው፤ ማንም ይለውጠው ዘንድ አይቻለውም፤ በሬ ቢሆን ወይም በግ ለእግዚአብሔር ነው።'),
  ('664c3939-3256-5b85-a9e8-0759af4d8855', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 27, 27, 'የረከሰም እንስሳ ቢሆን እንደ ግምቱ ይቤዠው፤ በእርሱም የዋጋውን አምስተኛ እጅ ይጨምርበታል፤ ባይቤዥም እንደ ግምቱ ይሸጣል።'),
  ('215fbc88-ecdf-5b21-a2a6-86d31a83c469', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 28, 28, '“ለእግዚአብሔርም የተለየ እርም የሆነ ነገር ሁሉ፥ ሰው ቢሆን ወይም እንስሳ ወይም የርስቱ እርሻ ቢሆን፥ አይሸጥም፤ አይቤዥም፤ እርም የሆነ ነገር ሁሉ ለእግዚአብሔር ቅዱሰ ቅዱሳን ነው።'),
  ('aea162e1-7265-55fe-a874-bed5db6cddff', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 29, 29, 'ከሰዎችም መባ ሆኖ የቀረበ ሁሉ እስኪሞት ድረስ አይቤዥም።'),
  ('6ac94ec2-9bca-58f7-ae52-0db20be4d481', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 30, 30, '“የምድርም ዐሥራት፥ ወይም የምድር ዘር፥ ወይም የዛፍ ፍሬ ቢሆን፥ የእግዚአብሔር ነው፤ ለእግዚአብሔር የተቀደሰ ነው።'),
  ('cc1abf3b-0096-585e-a93d-b6766f1f93b3', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 31, 31, 'ሰውም ዐሥራቱን ሊቤዥ ቢወድድ፥ አምስተኛ እጅ ይጨመርበታል።'),
  ('513c495f-7333-56c6-a499-932e6cf784d0', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 32, 32, 'ከበሬም ሁሉ ከዐሥር አንድ፥ ከበግም ሁሉ ከዐሥር አንድ፥ ከእረኛውም በትር በታች ከሚያልፍ ሁሉ ከዐሥር አንድ ለእግዚአብሔር የተቀደሰ ይሆናል።'),
  ('0ed3677e-13f4-57ae-a86e-87ee942f61a7', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 33, 33, 'መልካሙን በክፉ፥ ክፉውንም በመልካም አይለውጥ፤ ቢለውጠውም እርሱና ልዋጩ የተቀደሱ ይሆናሉ፤ አይቤዠውም።”'),
  ('576be017-a933-512c-aacd-9d3fefe78020', 'd4cf2cba-cc7d-569b-acdf-4fe5a9a16c6e', '7b2ad2c4-56f5-5438-ad45-2e64be678a37', 34, 34, 'እግዚአብሔር በሲና ተራራ ላይ ለእስራኤል ልጆች ያስተምራቸው ዘንድ ሙሴን ያዘዘው ትእዛዛት እነዚህ ናቸው።'),
  ('f94de262-e760-548a-a9e7-684ed594df60', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 1, 1, 'እግዚአብሔርም ሙሴን በሲና ምድረ በዳ በምስክሩ ድንኳን ውስጥ፥ በሁለተኛው ወር በመጀመሪያው ቀን፥ ከግብፅ ምድር ከወጡ በኋላ በሁለተኛው ዓመት እንዲህ ብሎ ተናገረው፦'),
