  ('65101d0f-f8ee-5223-a871-c4a8c1c50938', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 37, 37, 'ከጋድ ነገድ የተቈጠሩት አርባ አምስት ሺህ ስድስት መቶ አምሳ ነበሩ።'),
