  ('4a6e9f32-e92b-588e-af3c-55e3ddd97edc', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 39, 39, 'ከዳን ነገድ የተቈጠሩት ስድሳ ሁለት ሺህ ሰባት መቶ ነበሩ።'),
