  ('d51f733e-ceb3-5451-a06e-05ed6038cf1f', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 41, 41, 'ከአሴር ነገድ የተቈጠሩት አርባ አንድ ሺህ አምስት መቶ ነበሩ።'),
  ('65ee59af-2fa8-5527-afb0-1b0609246823', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 42, 42, 'የንፍታሌም ልጆች በየትውልዳቸው፥ በየወገናቸው፥ በየአባቶቻቸው ቤቶች፥ እንደ እየስማቸው ቍጥር፥ በየራሳቸው ከሃያ ዓመት ጀምሮ ከዚያም በላይ ያለው ወንድ ሁሉ፥ ወደ ሰልፍ የሚወጡት ሁሉ፥'),
  ('2c46a17d-9b41-5581-ac31-490cd64e0d05', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 43, 43, 'ከንፍታሌም ነገድ የተቈጠሩት አምሳ ሦስት ሺህ አራት መቶ ነበሩ።'),
  ('91042f9a-857c-5a6e-a4b4-78bbafef11d6', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 44, 44, 'ሙሴና አሮን ዐሥራ ሁለቱም የእስራኤል አለቆች እነርሱን የቈጠሩበት ቍጥር ይህ ነው።'),
  ('37c5f4bd-7ab4-550c-ac69-de8b262f8099', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 45, 45, 'ከእያንዳንዱ ነገድ ከየአባቶቻቸው ቤቶች አንድ አንድ አለቃ ነበረ። ከእስራኤልም ልጆች የተቈጠሩት ሁሉ፥ በየሠራዊታቸው፥ ከሃያ ዓመት ጀምሮ ከዚያም በላይ ያሉት፥ ወደ ሰልፍ የሚወጡት ሁሉ፥'),
  ('6fcc5863-3331-5ea7-a646-964b34736b7d', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 46, 46, 'የተቈጠሩት ሁሉ ስድስት መቶ ሦስት ሺህ አምስት መቶ አምሳ ነበሩ።'),
  ('b1cfd2ff-1123-53cc-ade5-e436a7ffe00f', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 47, 47, 'ሌዋውያን ግን በየአባቶቻቸው ነገድ ከእስራኤል ልጆች ጋር አልተቈጠሩም።'),
  ('01621d22-0b63-58be-a850-475f2978b9af', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 48, 48, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('17e2f2e8-322c-5f75-a0be-b5b588357968', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 49, 49, '“የሌዊን ነገድ እንዳትቈጥራቸው፥ ቍጥራቸውንም ከእስራኤል ልጆች ጋር እንዳትቀበል ዕወቅ፤'),
  ('215a30a7-4f7a-58f3-ae7f-99c5710577ef', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 50, 50, 'ነገር ግን በምስክሩ ድንኳንና በዕቃዎችዋ ሁሉ፥ በውስጥዋም ባለው ነገር ሁሉ ላይ ሌዋውያንን አቁማቸው። ድንኳንዋንና ዕቃዎችዋን ሁሉ ይሸከሙ፤ ያገልግሉአትም፤ በድንኳንዋም ዙሪያ ይስፈሩ።'),
  ('316d7a15-ed66-576a-a28d-f4dbba8ec8c3', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 51, 51, 'ድንኳንዋም ስትነሣ ሌዋውያን ይንቀሉአት፤ ድንኳንዋም ስታርፍ ሌዋውያን ይትከሉአት፤ ሌላ ሰው ግን ለመንካት ቢቀርብ ይገደል።'),
  ('38d10879-007c-506b-ae73-281f85ccc9d5', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 52, 52, 'የእስራኤልም ልጆች እያንዳንዱ ሰው በየሰፈሩ፥ እያንዳንዱም ሰው በየአለቃው፥ በየጭፍራውም ይሰፍራሉ።'),
  ('541a291f-c26c-5009-a37e-7376f44a0ec1', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 53, 53, 'ነገር ግን በእስራኤል ልጆች ላይ ዕዳ እንዳይሆንባቸው ሌዋውያን በምስክሩ ድንኳን ዙሪያ ፊት ለፊት ይስፈሩ፤ ሌዋውያን የምስክሩን ድንኳን ሕግ ይጠብቁ።”'),
  ('95961de3-7cde-5979-a3e6-afb10dfb63fb', 'bfaa03b6-a42a-5d18-a1da-be096bd1388e', '613d18dc-411a-509a-a5e8-0e8783ea996e', 54, 54, 'የእስራኤል ልጆችም እግዚአብሔር ለሙሴና ለአሮን ያዘዛቸውን ሁሉ አደረጉ፤ እንዲሁ አደረጉ።'),
  ('0ccf9fcb-4dc9-54d9-a162-045c1019a94f', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 1, 1, 'እግዚአብሔርም ለሙሴና ለአሮን እንዲህ ብሎ ተናገረ፦'),
  ('b4436247-efc9-5e84-a6ee-eb1752446ba8', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 2, 2, '“የእስራኤል ልጆች እያንዳንዱ በየሥርዐቱ፥ በየዓላማው፥ በየአባቶቻቸው ቤቶች፥ በምስክሩ ድንኳን ዙሪያ አንጻር ይስፈሩ።'),
  ('5cbc0223-2e52-5165-af8e-b3d53d7fb1ea', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 3, 3, 'በመጀመሪያ በምሥራቅ በኩል የሚሰፍሩት ከሠራዊቶቻቸው ጋር የይሁዳ ሰፈር ሰዎች ይሆናሉ፤ የይሁዳ ልጆችም አለቃ የአሚናዳብ ልጅ ነአሶን ነበረ።'),
  ('be8356b4-8675-5ca8-a4f1-303ddc2dc5be', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 4, 4, 'የተቈጠሩ ሠራዊቱም ሰባ አራት ሺህ ስድስት መቶ ነበሩ።'),
  ('0a660d3f-d4db-53ee-ad20-6d3772fdfaa3', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 5, 5, 'በእነርሱም አጠገብ የሚሰፍሩ የይሳኮር ነገድ ይሆናሉ፤ የይሳኮርም ልጆች አለቃ የሰገር ልጅ ናትናኤል ነበረ።'),
  ('f48b347c-77aa-5e90-a1d3-c17c78b34270', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 6, 6, 'የተቈጠሩ ሠራዊቱም አምሳ አራት ሺህ አራት መቶ ነበሩ።'),
  ('afefe110-42fe-52ac-aae8-cd2910cf1160', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 7, 7, 'በእነርሱም አጠገብ የዛብሎን ነገድ ነበረ፤ የዛብሎንም ልጆች አለቃ የኬሎን ልጅ ኤልያብ ነበረ።'),
  ('f03c7efc-4ac0-57d6-a085-5f9e396f2ea2', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 8, 8, 'የተቈጠሩ ሠራዊቱም አምሳ ሰባት ሺህ አራት መቶ ነበሩ።'),
  ('76d5eae9-1b1d-5f08-a9ed-b15ed54c0e5b', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 9, 9, 'ከይሁዳ ሰፈር የተቈጠሩ ሁሉ በየሠራዊቶቻቸው መቶ ሰማንያ ስድስት ሺህ አራት መቶ ነበሩ። እነዚህም አስቀድመው ይጓዛሉ።'),
  ('5bfbde4c-7d90-559d-a079-f0c50d6e20a0', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 10, 10, '“በአዜብ በኩል በየሠራዊቶቻቸው የሮቤል ሰፈር ዓላማ ይሆናል፤ የሮቤልም ልጆች አለቃ የሴድዮር ልጅ ኤሊሱር ነበረ።'),
  ('770ea4a8-ebf1-5664-a2d4-b63ea5628b14', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 11, 11, 'የተቈጠሩ ሠራዊቱም አርባ ስድስት ሺህ አምስት መቶ ነበሩ።'),
  ('98847aee-b2ba-5055-afc5-919b39ebccae', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 12, 12, 'በእነርሱም አጠገብ የሚሰፍሩ የስምዖን ነገድ ናቸው፤ የስምዖንም ልጆች አለቃ የሲሩሳዴ ልጅ ሰላምያል ነበረ።'),
  ('003aa76d-9032-5a60-a4d1-1ebdb0adf569', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 13, 13, 'የተቈጠሩ ሠራዊቱም አምሳ ዘጠኝ ሺህ ሦስት መቶ ነበሩ።'),
  ('7fc0a34c-2a08-5d07-af16-e447f23fa507', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 14, 14, 'በእነርሱም አጠገብ የጋድ ነገድ ነበረ፤ የጋድም ልጆች አለቃ የራጉኤል ልጅ ኤልሳፍ ነበረ።'),
  ('1cb24c2b-b390-54a2-ac53-937741901e0a', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 15, 15, 'የተቈጠሩ ሠራዊቱም አርባ አምስት ሺህ ስድስት መቶ አምሳ ነበሩ።'),
  ('83725f4a-8a8e-5934-a166-442284405f38', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 16, 16, 'ከሮቤል ሰፈር የተቈጠሩ ሁሉ በየሠራዊቶቻቸው መቶ አምሳ አንድ ሺህ አራት መቶ አምሳ ነበሩ። እነርሱም ቀጥለው ይጓዛሉ።'),
  ('0a72dda3-1cbe-544f-aa76-9067e78d025d', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 17, 17, '“ከዚያም በኋላ የምስክሩ ድንኳን፥ በሰፈሮቹም መካከል የሌዋውያን ወገን ይጓዛል፤ እንደ አሰፋፈራቸው ሰው ሁሉ በየስፍራው፥ በየዓላማውም ይጓዛሉ።'),
  ('00d8140e-0aad-5ad2-ab56-17c7bf241354', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 18, 18, '“በባሕር በኩል እንደ ሠራዊቶቻቸው የኤፍሬም ሰፈር ዓላማ ይሆናል፤ የኤፍሬም ልጆች አለቃ የኤሜሁድ ልጅ ኤሌሳማ ነበረ።'),
  ('09a2f51e-21d4-582e-adfd-aede896deccb', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 19, 19, 'የተቈጠሩ ሠራዊቱም አርባ ሺህ አምስት መቶ ነበሩ።'),
  ('542f07d2-ea38-5270-a29b-e67c75d4ca4c', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 20, 20, 'በእነርሱም አጠገብ የምናሴ ነገድ ይሆናል፤ የምናሴም ልጆች አለቃ የፈዳሱር ልጅ ገማልያል ነበረ።'),
  ('a4599cd4-1072-5bf6-aec1-f1b629b2bd18', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 21, 21, 'የተቈጠሩ ሠራዊቱም ሠላሳ ሁለት ሺህ ሁለት መቶ ነበሩ።'),
  ('7a986815-10f2-5f27-a1be-6c661498df64', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 22, 22, 'በእነርሱም አጠገብ የብንያም ነገድ ይሆናል፤ የብንያምም ልጆች አለቃ የጋዴዮን ልጅ አቢዳን ነበረ።'),
