  ('7e4aae75-519d-56a0-ae0d-acab59e6cc4d', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 24, 24, 'ከኤፍሬም ሰፈር የተቈጠሩ ሁሉ በየሠራዊቶቻቸው መቶ ስምንት ሺህ አንድ መቶ ነበሩ። እነርሱም ሦስተኛ ሆነው ይጓዛሉ።'),
  ('ed4dd793-6c6b-5c0d-ac59-c121ec8a39d7', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 25, 25, '“በመስዕ በኩል እንደ ሠራዊቶቻቸው የዳን ሰፈር ዓላማ ይሆናል፤ የዳንም ልጆች አለቃ የአሚሳዲ ልጅ አክያዜር ነበረ።'),
  ('0a78c74b-ed8e-589a-a8a6-ae8c30aaf50a', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 26, 26, 'የተቈጠሩ ሠራዊቱም ስድሳ ሁለት ሺህ ሰባት መቶ ነበሩ።'),
  ('f6b3094f-0c07-5f1d-abee-57bdedccb5e9', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 27, 27, 'በእነርሱም አጠገብ የሚሰፍሩ የአሴር ነገድ ይሆናሉ፤ የአሴርም ልጆች አለቃ የኤክራን ልጅ ፋጋኤል ነበረ።'),
  ('5bea8b30-bab5-5937-a051-a8db5c77da3c', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 28, 28, 'የተቈጠሩ ሠራዊቱም አርባ አንድ ሺህ አምስት መቶ ነበሩ።'),
  ('0b5a1ad0-fb9d-5e61-a2ae-2febc4ff194f', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 29, 29, 'በእነርሱም አጠገብ የንፍታሌም ነገድ ይሆናል፤ የንፍታሌምም ልጆች አለቃ የዔናን ልጅ አኪሬ ነበረ።'),
  ('abcdaf05-4d88-5260-a2be-5984e39654d7', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 30, 30, 'የተቈጠሩ ሠራዊቱም አምሳ ሦስት ሺህ አራት መቶ ነበሩ።'),
  ('b0c72849-7c02-556d-af88-beef248cbd9a', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 31, 31, 'ከዳን ሰፈር የተቈጠሩ ሁሉ መቶ አምሳ ሰባት ሺህ ስድስት መቶ ነበሩ። እነርሱም በየዓላማቸው በመጨረሻ ይጓዛሉ።”'),
  ('3625cb54-1927-5fb0-a705-f516d9b9efe8', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 32, 32, 'ከእስራኤል ልጆች በየአባቶቻቸው ቤቶች የተቈጠሩ እነዚህ ናቸው፤ ከየሰፈሩ በየሠራዊቶቻቸው የተቈጠሩ ሁሉ ስድስት መቶ ሦስት ሺህ አምስት መቶ አምሳ ነበሩ።'),
  ('59fe8dff-884a-5053-ad04-15482e1f56ad', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 33, 33, 'ሌዋውያን ግን እግዚአብሔር ሙሴን እንዳዘዘ ከእስራኤል ልጆች ጋር አልተቈጠሩም።'),
  ('02d7afd0-5f36-5f80-a301-6750ee05b897', 'cb561970-c5ee-5605-a6a8-0b5daed37f9d', '28937a10-0ec6-5ce8-a88a-7906f7db7021', 34, 34, 'የእስራኤል ልጆች እንዲሁ አደረጉ፤ እግዚአብሔር ሙሴን እንዳዘዘው ሁሉ እንዲሁ በየዓላማዎቻቸው ሰፈሩ፤ እንዲሁም በየወገኖቻቸው፥ በየአባቶቻቸው ቤቶች ተጓዙ።'),
  ('87498a6d-52f0-5dec-a679-8628112ac1b5', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '5567908f-0840-5213-a237-396d5665147a', 1, 1, 'እግዚአብሔር በሲና ተራራ ላይ ሙሴን በተናገረበት ቀን የአሮንና የሙሴ ትውልድ ይህ ነበረ።'),
  ('966b50ac-c17f-55f5-af5d-0ccaec08a0f7', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '5567908f-0840-5213-a237-396d5665147a', 2, 2, 'የአሮን ልጆች ስም ይህ ነው፤ በኵሩ ናዳብ፥ አብዩድ፥ አልዓዛር፥ ኢታምር።'),
  ('a4ac646b-2c8f-5a31-ac4f-ced80b37b5de', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '5567908f-0840-5213-a237-396d5665147a', 3, 3, 'በክህነት ያገለግሉ ዘንድ የተቀቡና እጆቻቸውን የተቀደሱ የአሮን ልጆች ስም ይህ ነው።'),
  ('640b9471-fbb7-51e4-aed6-89225f6ed979', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '5567908f-0840-5213-a237-396d5665147a', 4, 4, 'ናዳብና አብዩድ በሲና ምድረ በዳ በእግዚአብሔር ፊት ከሌላ እሳት ጭረው አምጥተዋልና በእግዚአብሔር ፊት ሞቱ፤ ልጆችም አልነበሩአቸውም። አልዓዛርና ኢታምር ከአባታቸው ከአሮን ጋር በክህነት ያገለግሉ ነበር።'),
  ('ef7e12ae-3462-533f-ab35-36d245848e06', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 1, 5, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('2b396675-30f6-55d3-a087-c9fb699e3a5c', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 2, 6, '“የሌዊን ነገድ አቅርበህ ያገለግሉት ዘንድ በካህኑ በአሮን ፊት አቁማቸው።'),
  ('2f041016-5b85-580c-a690-537af9a4df39', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 3, 7, 'የድንኳኑን ሥራ ይሠሩ ዘንድ ሕጉንና የእስራኤልን ልጆች ሕግ በምስክሩ ድንኳን ፊት ይጠብቁ።'),
  ('d4ada241-802c-5353-a25b-230ab3fbc45c', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 4, 8, 'እንደ ድንኳኑ ሥራዎች ሁሉ የምስክሩን ድንኳን ዕቃና የእስራኤልን ልጆች ሕግ ይጠብቁ።'),
  ('272ac705-7449-5feb-a433-f6e729b2c299', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 5, 9, 'ሌዋውያንንም ወደ ወንድምህ ወደ አሮንና ወደ ልጆቹ ወደ ካህናቱ ታገባቸዋለህ። ከእስራኤል ልጆች ተለይተው ለእኔ ሀብት ሆነው ተሰጥተዋልና።'),
  ('2b9bcb14-570e-5b87-ab28-4cd604e8c56b', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 6, 10, 'አሮንንና ልጆቹን በምስክሩ ድንኳን ፊት አቁማቸው፤ ክህነታቸውንም፥ በመሠዊያውና በመጋረጃው ውስጥ ያለውንም ሁሉ ይጠብቁ፤ ከሌላ ወገን የዳሰሰ ቢኖር ይገደል።”'),
  ('d1d63841-2815-5be7-af05-2da9abe83b82', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 7, 11, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('5079e1f4-2665-537e-ab15-74f18ab3c716', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 8, 12, '“እነሆ፥ እኔ በእስራኤል ልጆች ዘንድ መጀመሪያ በሚወለደው በበኵር ሁሉ ፋንታ ሌዋውያንን ከእስራኤል ልጆች መካከል ለይች ወስጃለሁ፤ በእነርሱ ፋንታ ሌዋውያን ለእኔ ይሁኑ፤'),
  ('ae51067a-2acd-57e6-ae6a-1be181fd7f84', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0525ab6f-efe3-5ef9-a3f6-caa35d798a0d', 9, 13, 'በኵር ሁሉ ለእኔ ነውና፤ በግብፅ ምድር በኵርን ሁሉ በመታሁ ቀን ከእስራኤል ዘንድ በኵርን ሁሉ፥ ሰውንና እንስሳን፥ ለእኔ ለይችአለሁ፤ ለእኔ ይሁኑ። እኔ እግዚአብሔር ነኝና።”'),
  ('e73edefc-3992-501f-ad63-3e97f63c405c', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 1, 14, 'እግዚአብሔርም ሙሴን በሲና ምድረ በዳ እንዲህ ብሎ ተናገረው፦'),
  ('af525b1f-4972-5ebc-abba-e2a2dfdf0dc0', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 2, 15, '“የሌዊን ልጆች በየአባቶቻቸው ቤቶች፥ በየወገናቸውም ቍጠር፤ ወንዱን ሁሉ ከአንድ ወር ጀምሮ ከዚያም በላይ ያለውን ቍጠራቸው።”'),
  ('b26439cb-c1e4-5b3f-a2f2-65cc86792e22', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 3, 16, 'ሙሴና አሮንም እንደ እግዚአብሔር ቃል፥ እግዚአብሔር እንደ አዘዛቸው ቈጠሩአቸው።'),
  ('407339a6-3181-5275-a8a3-e7d71be18a3b', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 4, 17, 'የሌዊ ልጆች በየስማቸው እነዚህ ናቸው፤ ጌድሶን፥ ቀዓት፥ ሜራሪ።'),
  ('28764d7b-a44f-5430-a104-3ab80175fcd9', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 5, 18, 'የጌድሶንም ልጆች ስሞች በየወገናቸው እነዚህ ናቸው፤ ሎቤን፥ ሰሜይ።'),
  ('2fc53b1a-0bd3-56ad-a305-fae4c9582bc8', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 6, 19, 'የቀዓትም ልጆች በየወገናቸው እንበረም፥ ይሳዓር፥ ኬብሮን፥ አዛሄል።'),
  ('6a33128a-0e44-53ea-ad73-8bc24b75fe2c', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 7, 20, 'የሜራሪም ልጆች በየወገናቸው፤ ሞሐሊ፥ ሙሲ። የሌዋውያን ወገኖች በየአባቶቻቸው ቤቶች እነዚህ ናቸው።'),
  ('86567e0d-331b-56c9-adaa-6edcbdc0e316', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 8, 21, 'ለጌድሶን የሎቤን ወገን፥ የሰሜይም ወገን ነበሩት፤ የጌድሶን ወገኖች እነዚህ ናቸው።'),
  ('d734eb0f-9bec-5038-a844-68f145be192f', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 9, 22, 'ከእነርሱ የተቈጠሩት የወንዶች ሁሉ ቍጥር ከአንድ ወር ጀምሮ ከዚያም በላይ የተቈጠሩት ሰባት ሺህ አምስት መቶ ነበሩ።'),
  ('7922855c-d8fb-5a8b-a487-47eb38889ec2', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 10, 23, 'የጌድሶን ልጆች ከድንኳን በኋላ በባሕር በኩል ይሰፍራሉ።'),
  ('ec96557c-a7fc-5d0d-af2f-580fc8bb3768', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 11, 24, 'የጌድሶን አባቶች ቤት አለቃ የዳሔል ልጅ ኤሊሳፍ ይሆናል።'),
  ('b45e23ef-fed0-5376-ae1b-62380bdb96e7', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 12, 25, 'የጌድሶን ልጆች በምስክሩ ድንኳን የሚጠብቁት ማደሪያውና ድንኳኑ፥ መደረቢያውም፥ የምስክሩ ድንኳን ደጃፍ መጋረጃ፥'),
  ('3b1b17bb-807d-5e90-a0df-cf22f9ab1ae3', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 13, 26, 'የአደባባዩ መጋረጃ፥ በድንኳኑ አደባባይ በር ያለው መጋረጃና የቀረውም ሥራዋ ሁሉ ይሆናል።'),
  ('0807a31b-b669-57d6-afe7-981b3e049da0', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 14, 27, 'ለቀዓትም የእንበረም ወገን፥ የይስዓር ወገን፥ የኬብሮንም ወገን፥ የአዛሔልም ወገን ነበሩ፤ የቀዓት ወገኖች እነዚህ ናቸው።'),
  ('c29821eb-0d14-556a-a523-edbe8f2f2818', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 15, 28, 'ወንዶች ሁሉ እንደ ቍጥራቸው ከአንድ ወር ጀምሮ ከዚያም በላይ ስምንት ሺህ ስድስት መቶ ነበሩ፤ መቅደሱንም ይጠብቁ ነበር።'),
  ('e6be1708-97b6-54c9-aaa9-550e9d311d64', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 16, 29, 'የቀዓት ልጆች ወገኖች በድንኳኑ አጠገብ በአዜብ በኩል ይሰፍራሉ።'),
  ('a83181ab-ce9a-5834-a776-b4f9e4ab6c63', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 17, 30, 'የቀዓት ወገኖች አባቶች ቤት አለቃ የአዛሔል ልጅ ኤሊሳፋ ይሆናል።'),
  ('6f4f257f-643e-52a2-ac88-97b4056cf540', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 18, 31, 'ታቦቱንም፥ ገበታውንም፥ መቅረዙንም፥ መሠዊያዎቹንም፥ የሚያገለግሉበትንም የመቅደሱን ዕቃ፥ መጋረጃውንም፥ ማገልገያውንም ሁሉ ይጠብቃሉ።'),
  ('cda88fd3-4de3-5824-ab34-0248cd8e3a1e', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 19, 32, 'የሌዋውያንም አለቆች አለቃ የተቀደሱ ነገሮችን ይጠብቅ ዘንድ የተሾመው የካህኑ የአሮን ልጅ አልዓዛር ነው።'),
  ('562c78e8-7a60-5f68-ae08-75cf204ccd75', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 20, 33, 'ለሜራሪ የሞሖሊ ወገን የሙሲ ወገን ነበሩ፤ የሜራሪ ወገኖች እነዚህ ናቸው።'),
  ('5ea9c075-263f-57cd-a55d-d46d7830f763', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 21, 34, 'ከእነርሱም ወንዶች ሁሉ እንደ ቍጥራቸው ከአንድ ወር ጀምሮ ከዚያም በላይ የተቈጠሩት ስድስት ሽህ አምሳ ነበሩ።'),
  ('ff768981-1121-5ae5-a7ad-290ae442aa67', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 22, 35, 'የሜራሪም ወገኖች አባቶች ቤት አለቃ የአቢኪያ ልጅ ሱራሔል ነበረ፤ በድንኳኑ አጠገብ በሰሜን በኩል ይሰፍራሉ።'),
  ('9cecbc8d-5b81-5d51-ac60-673c163b97d0', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 23, 36, 'የሜራሪም ልጆች የሚጠብቁት የድንኳኑ ምሰሶዎች፥ ኩላቦች፥ መወርወሪያዎችም፥ ተራዳዎችም፥ እግሮቹም፥'),
  ('08457b29-f652-5569-a0e1-87cb9850e72e', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 24, 37, 'ዕቃውም ሁሉ፥ ማገልገያውም ሁሉ፥ በዙሪያውም የሚቆሙ የአደባባይ ምሰሶዎች፥ እግሮቹም፥ ካስማዎቹም፥ አውታሮቹም ይሆናሉ።'),
  ('23eeb48a-410c-59fe-a66c-7bd9acd1bd59', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 25, 38, 'በምሥራቅ በኩል በምስክሩ ድንኳን ፊት የሚሰፍሩት ሙሴና አሮን ልጆቹም ይሆናሉ፥ እንደ እስራኤል ልጆች ሕግም የመቅደሱን ሕግ ይጠብቃሉ፥ ከሌላ ወገን የዳሰሰ ቢኖር ይገደል።'),
  ('245ae55e-09bd-5d92-ab76-c52d898df06b', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '701d0e1d-628a-574e-a452-2028a086c8b2', 26, 39, 'በእግዚአብሔር ትእዛዝ ሙሴና አሮን የቈጠሩአቸው፥ ከሌዋውያን ወንዶች ሁሉ ከአንድ ወር ጀምሮ ከዚያም በላይ በየወገናቸው የተቈጠሩት ሁሉ ሃያ ሁለት ሺህ ነበሩ።'),
  ('1acca36b-8479-56ee-a3b8-3c6f329d49f1', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 1, 40, 'እግዚአብሔርም ሙሴን፥ “የእስራኤልን ልጆች ወንዱን በኵር ሁሉ ከአንድ ወር ጀምሮ ከዚያም በላይ ያሉትን ቍጠር፤ ቍጥራቸውንም በየስማቸው ውሰድ፤'),
  ('e48b913e-2c2e-5095-acfc-79c873908912', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 2, 41, 'ሌዋውያንንም በእስራኤል ልጆች በኵር ሁሉ ፋንታ፥ የሌዋውያንንም እንስሶች በእስራኤል ልጆች እንስሶች በኵር ሁሉ ፋንታ ለእኔ ለእግዚአብሔር አድርጋቸው” አለው።'),
  ('98cae876-75b7-5485-a246-eca32079dd94', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 3, 42, 'ሙሴም እግዚአብሔር እንዳዘዘው የእስራኤልን ልጆች በኵር ሁሉ ቈጠረ።'),
  ('216995f1-e7a4-570f-aa13-7bdd4a5e7448', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 4, 43, 'ከእነርሱም የተቈጠሩ ወንዶች በኵሮች ሁሉ በየስማቸው ከአንድ ወር ጀምሮ ከዚያም በላይ ሃያ ሁለት ሺህ ሁለት መቶ ሰባ ሦስት ነበሩ።'),
  ('aac63a9f-5764-540c-ad4b-8d8f927230da', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 5, 44, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('b8fbc264-58c3-596e-abf3-a5b3417e45d6', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 6, 45, '“ሌዋውያንን በእስራኤል ልጆች በኵር ሁሉ ፋንታ፥ የሌዋውያንንም እንስሶች በእንስሶቻቸው ፋንታ ውሰድ፤ ሌዋውያንም ለእኔ ይሁኑ፤ እኔ እግዚአብሔር ነኝና።'),
  ('ec75fd93-4714-5475-a1d3-7231bafa09c0', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 7, 46, 'በሌዋውያን ላይ ከእስራኤል ልጆች በኵር ስለ ተረፉት ስለ ሁለት መቶ ሰባ ሦስት ቤዛ፥'),
  ('f1f6c961-0236-54c6-a515-cffeb083a223', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 8, 47, 'በየራሱ አምስት ዲድርክም ውሰድ፤ እንደ መቅደሱ ዲድርክም ብዛት ትወስዳለህ፤ ዲድርክም ሃያ አቦሊ ነው።'),
  ('caeb91c3-a22a-5c4d-a53d-1618eb9f4508', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 9, 48, 'ስለ ተረፉትም የመቤዣውን ገንዘብ ለአሮንና ለልጆቹ ትሰጣቸዋለህ።”'),
  ('873d79cd-fde5-55a7-ab84-310d54b63c59', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 10, 49, 'ሙሴም በሌዋውያን ከተቤዡት በላይ ከተረፉት ዘንድ የመቤዣውን ገንዘብ ወሰደ።'),
  ('b8de804d-5d25-57eb-a324-2edb5e4858e6', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 11, 50, 'ከእስራኤል ልጆች በኵሮች ገንዘቡን ሺህ ሦስት መቶ ስድሳ አምስት ዲድርክም እንደ መቅደሱ ዲድርክም ሚዛን ወሰደ።'),
  ('f694c866-e992-5bf8-a5fb-b3016e18e10f', '02edbe93-5866-5025-ab29-ecdbd811f6ea', '0078edde-da9c-5da3-a4af-e4bfe78bebf7', 12, 51, 'እንደ እግዚአብሔርም ቃል፥ እግዚአብሔር ሙሴን እንዳዘዘው ሙሴ የመቤዣውን ገንዘብ ለአሮንና ለልጆቹ ሰጠ።'),
  ('5bb37637-d30d-56c9-a72a-508b08a2a672', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 1, 1, 'እግዚአብሔርም ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('1f84bd29-87b4-54bc-a708-9577deb5b6a1', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 2, 2, '“ከሌዊ ልጆች መካከል በየወገናቸው፥ በየአባቶቻቸው ቤቶች የቀዓትን ልጆች ለዩአቸው፤'),
  ('d601a881-62e1-5a5c-a7a1-3ad8864d10fd', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 3, 3, 'ከሃያ አምስት ዓመት ጀምሮ እስከ አምሳ ዓመት ድረስ በምስክሩ ድንኳን ይሠሩ ዘንድ ለአገልግሎት የሚገቡበትን ሁሉ ትለያለህ።'),
  ('0c4fd3e5-74c0-5de3-a873-5b4917045543', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 4, 4, 'በምስክሩ ድንኳን በቅድስተ ቅዱሳኑ ዘንድ የቀዓት ልጆች ሥራ ይህ ነው፤'),
  ('932f740c-ad7f-56a2-a4e7-ef23b32872e0', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 5, 5, 'ሰፈሩ በተነሣ ጊዜ አሮንና ልጆቹ ገብተው የሚሸፍነውን መጋረጃ ያወርዳሉ፤ የምስክሩንም ታቦት ይጠቀልሉበታል፤'),
  ('c928eac5-5837-59fd-a7a4-f966e92645d6', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 6, 6, 'በላዩም የአቆስጣውን ቍርበት መሸፈኛ ያድርጉበት፤ ከእርሱም በላይ ሁለንተናው ሰማያዊ የሆነ መጐናጸፊያ ያግቡበት፤ መሎጊያዎቹንም ያግቡበት።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8312d225-2c1c-5e58-ad4e-f88565a4439b', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 7, 7, 'በኅብስተ ገጹ ገበታ ላይም ሰማያዊውን መጐናጸፊያ ይዘርጉበት፤ በእርሱም ላይ ወጭቶቹን፥ ጭልፋዎቹንም፥ ጽዋዎቹንም፥ ለማፍሰስም መቅጃዎቹን ያድርጉበት፤ ሁልጊዜም የሚኖር ኅብስት በእርሱ ላይ ይሁን።'),
  ('0185b68d-a4c1-5c2c-a841-ba9bff1c591c', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 8, 8, 'በእነርሱም ላይ ቀይ መጐናጸፊያ ይዘርጉ፤ በአቆስጣውም ቍርበት መሸፈኛ ይሸፍኑት። መሎጊያዎቹንም ያግቡ።'),
  ('46ff3a11-1c61-5f54-a921-68eeb5691694', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 9, 9, 'ሰማያዊውንም መጐናጸፊያ ይውሰዱ፤ የሚያበሩባትንም መቅረዝ፥ ቀንዲሎችዋንም፥ መኰስተሪያዎችዋንም፥ የኵስታሪ ማድረጊያዎችዋንም፥ እርስዋንም ለማገልገል የዘይቱን ማሰሮዎች ሁሉ ይሸፍኑ፤'),
  ('bbc4778f-d340-51f7-a306-8f94b89a5e46', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 10, 10, 'እርስዋንና ዕቃዎችዋን ሁሉ በአቆስጣ ቍርበት መሸፈኛ ውስጥ ያድርጉ፤ በመሸከሚያውም ላይ ያድርጉት።'),
  ('5992bc00-a447-5734-a6a2-a7d46dafbbfb', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 11, 11, 'በወርቁም መሠዊያ ላይ ሰማያዊውን መጐናጸፊያ ይዘርጉበት፤ በአቆስጣም ቍርበት መሸፈኛ ይሸፍኑት፤ መሎጊያዎቹንም ያግቡ።'),
  ('86cd68c6-a342-59d4-a601-e21e0eb3fb6d', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 12, 12, 'በመቅደስም ውስጥ የሚያገለግሉበትን የማገልገያውን ዕቃ ሁሉ ይውሰዱ፤ በሰማያዊዉም መጐናጸፊያ ውስጥ ያስቀምጡት፤ በአቆስጣም ቍርበት መሸፈኛ ይሸፍኑት፤ በመሸከሚያውም ላይ ያድርጉት።'),
  ('e032d2ff-f51d-5277-a645-9d1677710d01', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 13, 13, 'አመዱንም ያስወግዱ፤ መክደኛውንም በመሠዊያው ላይ ያድርጉ፤ ሐምራዊዉንም መጐናጸፊያ ይዘርጉበት፤'),
  ('a2ddf87b-339c-5b96-a60d-deeb3e25c8f4', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 14, 14, 'የሚያገለግሉበትን ዕቃውን ሁሉ፥ ማንደጃዎቹን፥ ሜንጦዎቹንም፥ ጽዋዎቹንም፥ ድስቶቹንም፥ መክደኛዎቹንም፥ ያመድ ማፍሰሻዎቹን፥ የመሠዊያውን ዕቃ ሁሉ ያስቀምጡበት፤ በእርሱም የአቆስጣን ቍርበት መሸፈኛ ይዘርጉ፤ መሎጊያዎቹንም ያግቡ። ሐምራዊዉንም መጐናጸፊያ ወስደው ማስታጠቢያውንና ማስቀመጫውን ይሸፍኑት፤ በአቆስጣው ቍርበት መሸፈኛ ውስጥም አድርገው በመሸከሚያዎቹ ላይ ያኑሩት፤'),
  ('3f28e3f4-5a5b-592c-a8f4-584098d665f4', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 15, 15, 'አሮንና ልጆቹ መቅደሱንና የመቅደሱን ዕቃ ሁሉ ሸፍነው ከጨረሱ በኋላ ሰፈሩ ሲነሣ የቀዓት ልጆች ሊሸከሙት ይገባሉ። እንዳይሞቱ ግን ንዋየ ቅድሳቱን አይንኩ። በምስክሩ ድንኳን ዘንድ የቀዓት ልጆች ሸክም ይህ ነው።'),
  ('51d10212-7eda-5d4a-ad13-c40359ceec85', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 16, 16, 'የካህኑም የአሮን ልጅ አልዓዛር በመብራቱ ዘይት በጣፋጩም ዕጣን ላይ ፥ ሁልጊዜም በሚቀርበው በእህሉ ቍርባንና በቅባቱ ዘይት ላይ ሹም ነው፤ ድንኳኑን ሁሉ፥ በእርሱም ውስጥ ያለውን ሁሉ፥ መቅደሱንና ዕቃውን ይጠብቃል።”'),
  ('f4c5aa6e-024f-5293-a61d-23ac4dc2414f', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 17, 17, 'እግዚአብሔር ሙሴንና አሮንን እንዲህ ብሎ ተናገራቸው፦'),
  ('d0b5a060-69c2-5235-a2aa-2b485d70b425', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 18, 18, '“የቀዓትን ወገኖች ነገድ ከሌዋውያን መካከል አታጥፉአቸው፤'),
  ('eeabb1bf-0ee6-5314-a673-0c0882aaa921', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 19, 19, 'ነገር ግን ወደ ቅድስተ ቅዱሳኑ በቀረቡ ጊዜ በሕይወት ይኖሩ ዘንድ እንጂ እንዳይሞቱ እንዲሁ አድርጉላቸው፤ አሮንና ልጆቹ ይግቡ፤'),
  ('a72da403-14f3-5b75-a36d-f6d46890dadd', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f7d471a1-9499-57e7-ad9d-b2d12ed35267', 20, 20, 'ከእነርሱ ለእያንዳንዱ ሰው ሥራውንና ሸክሙን ያዘጋጁ፤ ነገር ግን እንዳይሞቱ ንዋየ ቅዱሳቱን ለድንገት እንኳን ለማየት አይግቡ።”'),
  ('10e20849-5097-53f5-a0ea-44305a4faae7', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'c710813d-57a4-514c-ac54-3fedcf2b1244', 1, 21, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('858abf9e-7a73-50db-ac4b-d29c1fb10791', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'c710813d-57a4-514c-ac54-3fedcf2b1244', 2, 22, '“የጌድሶንን ልጆች ከመጀመሪያው ጀምረህ በየአባቶቻቸው ቤቶች በየወገኖቻቸውም ቍጠራቸው።'),
  ('b5e2c5c3-1e69-571d-af1a-19a9d0c543af', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'c710813d-57a4-514c-ac54-3fedcf2b1244', 3, 23, 'የምስክሩን ድንኳን ሥራ ይሠሩ ዘንድ ለአገልግሎት የሚገቡትን ሁሉ ከሃያ አምስት ዓመት ጀምሮ እስከ አምሳ ዓመት ድረስ ቍጠራቸው።'),
  ('f61e02e7-54db-5b41-a0b2-9c516394a8c1', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'c710813d-57a4-514c-ac54-3fedcf2b1244', 4, 24, 'የጌድሶን ወገኖች ሥራ በማገልገልና በመሸከም ይህ ነው፤'),
  ('1889cfa5-14c8-5594-a253-91c44623a1b8', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'c710813d-57a4-514c-ac54-3fedcf2b1244', 5, 25, 'የድንኳኑን መጋረጃዎች፥ የምስክሩንም ድንኳን፥ መደረቢያውን፥ በላዩም ያለውን የአቆስጣውን ቍርበት መደረቢያ፥ የምስክሩንም ድንኳን ደጃፍ መጋረጃ፥ የአደባባዩንም መጋረጃ፥'),
  ('77a78866-e8a9-5b37-ab80-ef99bdb8a1ff', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'c710813d-57a4-514c-ac54-3fedcf2b1244', 6, 26, 'በምስክሩ ድንኳን ዙሪያ ያለውን የአደባባዩን ደጃፍ መጋረጃ፥ ለማገልገልም የሚሠሩበትን ዕቃ ሁሉ ይሸከሙ፤ በዚህም ያገልግሉ።'),
  ('9f5f1fdd-3b43-5bfb-a614-0a134fff82fd', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'c710813d-57a4-514c-ac54-3fedcf2b1244', 7, 27, 'የጌድሶን ልጆች አገልግሎት ሁሉ፥ በተራቸውም ሁሉ፥ በሥራቸውም ሁሉ በአሮንና በልጆቹ ትእዛዝ ይሁን፤ በስማቸውና በተራቸውም ትቈጥራቸዋለህ።'),
  ('f319effa-92ba-50cb-a455-d040d1bdfa2e', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'c710813d-57a4-514c-ac54-3fedcf2b1244', 8, 28, 'የጌድሶን ልጆች አገልግሎት በምስክሩ ድንኳን ዘንድ ይህ ነው፤ ከካህኑ ከአሮን ልጅ ከኢታምር እጅ በታች ይሆናሉ።'),
  ('00e51d90-767c-55fe-a711-f2d7f1c1c035', '2dd1360d-25ed-5746-a525-5dd69c95fa24', '06659c80-d4d4-5436-a0cc-a02e88290c7e', 1, 29, '“የሜራሪንም ልጆች በየወገናቸው፥ በየአባቶቻቸውም ቤቶች ቍጠራቸው።'),
  ('fe8d93f5-0d2a-580d-abc9-e84d1afee0a9', '2dd1360d-25ed-5746-a525-5dd69c95fa24', '06659c80-d4d4-5436-a0cc-a02e88290c7e', 2, 30, 'የምስክሩን ድንኳን ሥራ ይሠሩ ዘንድ ለአገልግሎት የሚገቡትን ሁሉ ከሃያ አምስት ዓመት ጀምሮ እስከ አምሳ ዓመት ድረስ ቍጠራቸው።'),
  ('7dd78b22-d81d-51f4-a2e8-484b597b4bb4', '2dd1360d-25ed-5746-a525-5dd69c95fa24', '06659c80-d4d4-5436-a0cc-a02e88290c7e', 3, 31, 'በምስክሩ ድንኳን ዘንድ ባለው አገልግሎታቸው ሁሉ፥ የድንኳኑ ሳንቆች፥ መወርወሪያዎቹም፥ ተራዳዎቹም፥ እግሮቹም፥ መሸፈኛዎቹም፥ መቀመጫዎቹም፥ የምስክሩ ድንኳን ደጃፍ መጋረጃ፥'),
  ('5a5a5c4e-d713-50b6-a410-991709995ade', '2dd1360d-25ed-5746-a525-5dd69c95fa24', '06659c80-d4d4-5436-a0cc-a02e88290c7e', 4, 32, 'በዙሪያውም የሚቆሙት የአደባባዩ ምሰሶዎች፥ እግሮቹም፥ የአደባባዩ ደጃፍ መጋረጃ ምሰሶዎች፥ እግሮቻቸውም፥ ካስማዎቹም፥ አውታሮቹም፥ ዕቃዎቹና ማገልገያዎቹ ሸክማቸው ነው፤ የሚጠብቁትንም የሸክማቸውን ዕቃ ሁሉ በየስማቸው ቍጠሩ።'),
  ('a45426e7-3225-5526-aae9-3255baf4c7b2', '2dd1360d-25ed-5746-a525-5dd69c95fa24', '06659c80-d4d4-5436-a0cc-a02e88290c7e', 5, 33, 'በምስክሩ ድንኳን ዘንድ ባለው ሥራቸው ሁሉ የሜራሪ ልጆች ወገኖች አገልግሎት ይህ ነው፤ እነርሱም ከካህኑ ከአሮን ልጅ ከኢታምር እጅ በታች ይሆናሉ።”'),
  ('333d710b-feee-51a1-a6b1-ee5fa2c57dd4', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 1, 34, 'ሙሴና አሮንም፥ የእስራኤልም አለቆች የቀዓትን ልጆች በየወገናቸው፥ በየአባቶቻቸውም ቤቶች ቈጠሩአቸው።'),
  ('64be28b4-ff03-5edc-a112-55fef4aa29cf', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 2, 35, 'በምስክሩ ድንኳን ውስጥ ይሠሩ ዘንድ ወደ አገልግሎት የገቡትን ሁሉ ከሃያ አምስት ዓመት ጀምሮ እስከ አምሳ ዓመት ድረስ ያሉትን ቈጠሩአቸው፤'),
  ('e3895737-a359-5238-aa65-b76fb361c572', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 3, 36, 'በየወገናቸውም ከእነርሱ የተቈጠሩት ሁለት ሺህ ሰባት መቶ አምሳ ነበሩ።'),
