  ('b402f4a6-c0ac-5971-a3fb-7bcf9c8a85a2', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 10, 43, 'በምስክሩ ድንኳን ውስጥ ወደ አገልግሎት የገቡት ሁሉ ከሃያ አምስት ዓመት ጀምሮ እስከ አምሳ ዓመት ድረስ ያሉትን ቈጠሯቸው።'),
  ('4fb1146b-a52f-5050-aaf1-eeaf90cb3a19', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 11, 44, 'ቍጥራቸውም በየወገናቸው፥ በየአባቶቻቸውም ቤቶች ሦስት ሺህ ሁለት መቶ ነበረ።'),
