  ('74c691c4-23c2-5971-a3a1-03640820cd33', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 13, 46, 'በየወገናቸውና በየአባቶቻቸው ቤቶች ከሌዋውያን የተቈጠሩት ሁሉ፥ ሙሴና አሮን የእስራኤልም አለቆች የቈጠሩአቸው፥'),
  ('fce0742d-18c4-5d74-a0b0-f54dff83bfe6', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 14, 47, 'በምስክሩ ድንኳን ውስጥ ሥራውን ለመሥራትና ዕቃውን ለመሸከም የገቡት ሁሉ፥ ከሃያ አምስት ዓመት ጀምሮ እስከ አምሳ ዓመት ድረስ ያሉት፥'),
  ('4f5be1db-2f5c-5ade-a60d-03ab9c497e26', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 15, 48, 'ከእነርሱ የተቈጠሩት ስምንት ሺህ አምስት መቶ ሰማንያ ነበሩ።'),
  ('4c099f4a-1ab3-5529-a7c4-b4224ca00e49', '2dd1360d-25ed-5746-a525-5dd69c95fa24', 'f3d95a42-126b-54b0-a518-1c8b9fdcc069', 16, 49, 'እንደ እግዚአብሔር ትእዛዝ እያንዳንዳቸው በየአገልግሎታቸውና በየሸክማቸው በሙሴ እጅ ተቈጠሩ፤ እግዚአብሔር ሙሴን እንዳዘዘ እንዲሁ በእርሱ ተቈጠሩ።'),
  ('639205db-ebf0-57d2-a11b-7196978b40ac', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'ed4cfe01-77c0-563b-af49-fbe3f4717a6b', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('8717e025-e616-5f35-a3f2-ff69eb37165a', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'ed4cfe01-77c0-563b-af49-fbe3f4717a6b', 2, 2, '“የእስራኤል ልጆች ለምጻሙን ሁሉ ፈሳሽ ነገርም ያለበትን ሁሉ በሰውነቱ የረከሰውን ሁሉ ከሰፈሩ እንዲያወጡ እዘዛቸው፤'),
  ('0d9002af-a923-5450-ac1e-1007226f6d68', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'ed4cfe01-77c0-563b-af49-fbe3f4717a6b', 3, 3, 'እኔ በመካከሉ የማድርበትን ሰፈራቸውን እንዳያረክሱ ከወንድ እስከ ሴት ከሰፈሩ አውጡአቸው።”'),
  ('d1fd66bb-f11b-5667-a54d-8f9597300d22', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'ed4cfe01-77c0-563b-af49-fbe3f4717a6b', 4, 4, 'የእስራኤልም ልጆች እንዲሁ አደረጉ፤ ከሰፈሩ አወጡአቸው፤ እግዚአብሔር ሙሴን እንደ ተናገረው፥ የእስራኤል ልጆች እንዲሁ አደረጉ።'),
  ('295c39c5-4232-5516-a633-7e880a00c1a7', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', '35e05c01-2eda-58ec-a3b8-367dfe2bcb1e', 1, 5, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('94c0314d-0f7e-5f8a-a0e6-6467e636683b', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', '35e05c01-2eda-58ec-a3b8-367dfe2bcb1e', 2, 6, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ወንድ ወይም ሴት ቸል ብለው ወይም ባለማወቅ ሰው ከሚሠራው ኀጢአት ሁሉ የሠሩት ቢኖር፥'),
  ('13372ef5-1f87-5b5a-aea2-1aff3208bd19', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', '35e05c01-2eda-58ec-a3b8-367dfe2bcb1e', 3, 7, 'ያች ሰውነት ብትናዘዝ፥ ያደረገችውንም ኀጢአት ሁሉ ብትናገር የወሰደውን ዓይነቱን ሁሉ ይመልስ። አምስተኛ እጅም ለባለ ገንዘቡ ይጨምር።'),
  ('d8788015-dca5-5b53-a228-d132e250b6c5', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', '35e05c01-2eda-58ec-a3b8-367dfe2bcb1e', 4, 8, 'ነገር ግን ይመልስለት ዘንድ ሰውዬው ዘመድ ባይኖረው፥ ስለ በደል ለእግዚአብሔር የሚመልሰው ነገር ለካህኑ ይሁን፤ ይህም ስለ እርሱ ማስተስረያ ከሚደረግበት አውራ በግ ላይ ይጨመር።'),
  ('feffab94-fc65-5403-a21c-65f3703aefc5', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', '35e05c01-2eda-58ec-a3b8-367dfe2bcb1e', 5, 9, 'የእስራኤልም ልጆች ለእግዚአብሔር ከሚያቀርቡአቸው የተቀደሱ ነገሮች ሁሉ የመጀመሪያው ለካህኑ ነው።'),
  ('d27ceff8-3923-5a66-a867-96829c40e65a', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', '35e05c01-2eda-58ec-a3b8-367dfe2bcb1e', 6, 10, 'የተቀደሰ የሰው ነገር ሁሉ፥ ሰውም ለካህኑ የሚሰጠው ሁሉ ለእርሱ ይሁን።”'),
  ('f2d41865-ca4c-5f53-a2a7-813f34ecf652', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 1, 11, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('1dad2212-f147-5a5e-ac06-628375b355b4', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 2, 12, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ የማንኛውም ሰው ሚስት ከእርሱ ፈቀቅ ብትል፥ በእርሱም ላይ ብትበድል፥'),
  ('cd4a7160-e634-59a5-a24b-34a9de68fe2a', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 3, 13, 'ሌላም ሰው ከእርስዋ ጋር ቢተኛ፥ ብታመነዝር፥ ከባልዋም ዐይን ቢሸሸግ፥ እርስዋም ተሰውራ ብትረክስ፥'),
  ('cac04864-5f50-514a-aecc-9097fbaad9bc', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 4, 14, 'ምስክርም ባይኖርባት፥ በምንዝርም ባትያዝ፥ በባልዋም ላይ የቅንዐት መንፈስ ቢመጣበት፥ እርስዋም ስትረክስ ስለ ሚስቱ ቢቀና ወይም እርስዋ ሳትረክስ የቅንዐቱ መንፈስ ቢመጣበት፥ ስለ ሚስቱም ቢቀና፥'),
  ('ece70014-3dd7-569f-af3a-b18b75d1ed79', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 5, 15, 'ያ ሰው ሚስቱን ወደ ካህኑ ያምጣት፤ የኢፍ መስፈሪያም ዐሥረኛ እጅ ገብስ ዱቄት ቍርባን ስለ እርስዋ ያምጣ፤ የቅንዐት ቍርባን ነውና፥ ኀጢአትንም የሚያሳስብ የመታሰቢያ ቍርባን ነውና ዘይት አያፍስስበት፤ ዕጣንም አይጨምርበት።'),
  ('d91ac6b7-90b0-508a-a49a-ec57f7c859eb', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 6, 16, '“ካህኑም ያቀርባታል፤ በእግዚአብሔርም ፊት ያቆማታል፤'),
  ('dcd0bf87-33bf-5372-a264-ceabc2d438bf', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 7, 17, 'ካህኑም የተቀደሰ ውኃ በሸክላ ማሰሮ ይወስዳል፤ ካህኑም በምስክሩ ድንኳን ውስጥ ካለው ትቢያ ወስዶ በውኃ ላይ ይረጨዋል፤'),
  ('f17a3b34-0c0f-5f3b-aba7-f8cbf52d388c', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 8, 18, 'ካህኑም ሴቲቱን በእግዚአብሔር ፊት ያቆማታል፤ የሴቲቱንም ራስ ይገልጣል፤ በእጅዋም ለመታሰቢያ የሚሆነውን የእህል ቍርባን፥ የቅንዐት ቍርባን ያኖራል፤ በካህኑም እጅ ርግማንን የሚያመጣው መራራ ውኃ ይሆናል።'),
  ('0728723a-0ebd-5e6c-af36-a28d5a67b7bc', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 9, 19, 'ካህኑም ያምላታል፤ ሴቲቱንም እንዲህ ይላታል፦ ሌላ ወንድ አልተኛሽ፥ ባልሽንም አልተውሽ፥ ራስሽንም አላረከስሽ እንደ ሆነ፥ ርግማንን ከሚያመጣ ከዚህ መራራ ውኃ ንጹሕ ሁኚ፤'),
  ('d749f28e-cb96-5342-a103-5367f6355669', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 10, 20, 'ነገር ግን ባልሽን ትተሽ ረክሰሽ እንደ ሆነ፥ ከባልሽም ሌላ ወንድ ከአንቺ ጋር ተኝቶ እንደ ሆነ፤'),
  ('36d08a65-d893-5fe8-a172-fe326e4d5ea6', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 11, 21, 'ካህኑም ሴቲቱን በመርገም መሐላ ያምላታል፤ ካህኑም ሴቲቱን እንዲህ ይበላት፦ እግዚአብሔር የተረገምሽ ያድርግሽ ጎንሽን ያረግፈው ዘንድ እግዚአብሔር ከሕዝብሽ መካከል ለይቶ ያጥፋሽ፤ ሆድሽን ይሰንጥቀው፤'),
  ('a75b10b6-fdad-5517-a4d3-b70241cc7478', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 12, 22, 'ርግማንንም የሚያመጣ ይህ ውኃ ወደ ሆድሽ ይግባ፥ ማኅፀንሽንም ይሰንጥቀው፤ ጎንሽም ይርገፍ። ሴቲቱም፦ ይሁን ይሁን ትላለች።'),
  ('b7eacb5b-caa4-577c-a257-51477aaf6f60', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 13, 23, '“ካህኑም እነዚህን መርገሞች በሰሌዳ ላይ ይጽፋቸዋል፤ በመርገሙም መራራ ውኃ ይደመስሳቸዋል፤'),
  ('886587c7-40a3-5b14-a8cb-a3b52d8e3d57', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 14, 24, 'የመርገሙን መራራ ውኃ ለሴቲቱ ያጠጣታል፤ የርግማኑም ውኃ ወደ ሆድዋ ይገባል።'),
  ('63c42f42-2b7e-52c3-ae22-3888111dbe48', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 15, 25, 'ካህኑም የቅንዐቱን መሥዋዕት ከሴቲቱ እጅ ይወስዳል፤ ያንም መሥዋዕት በእግዚአብሔር ፊት ያቀርበዋል፥ ወደ መሠዊያውም ያመጣዋል፤'),
  ('78dba0a7-ce1d-5097-a926-d313be4193dc', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 16, 26, 'ካህኑም ከእህሉ ቍርባን አንድ እፍኝ ሙሉ ለመታሰቢያው ወስዶ በመሠዊያው ላይ ይጨምረዋል። ከዚያም በኋላ ለሴቲቱ ያን ውኃ ያጠጣታል።'),
  ('779932ca-4aa8-55d1-a767-37e1b3fd0833', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 17, 27, 'ውኃውን ካጠጣት በኋላ እንዲህ ይሆናል፤ ራስዋን አርክሳና ባልዋን ቸል ብላው ከሆነ፤ የመርገሙ መራራ ውኃ ወደ ሆድዋ ይገባል፤ ሆድዋንም ይሰነጥቀዋል፤ ጎኗም ይረግፋል፤ ሴቲቱም በሕዝብዋ መካከል ለመርገም ትሆናለች።'),
  ('40752294-8584-5f42-a9be-b31b86b91472', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 18, 28, 'ራስዋን ያላረከሰች እንደ ሆነች፥ ያለ ነውርም እንደ ሆነች፥ ያነጻታል፤ ልጆችንም ትወልዳለች።'),
  ('d38957cf-84d4-5015-ac0b-8d40461d228b', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 19, 29, '“በባልዋ ላይ ለበደለችና ራስዋን ላረከሰች ሴት የቅንዐት ሕግ ይህ ነው፤'),
  ('f946d154-5b69-5b8c-a582-beab7f774b27', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 20, 30, 'በሰው ላይ የቅንዐት መንፈስ ቢመጣ፥ ስለ ሚስቱም ቢቀና፤ ሴቲቱን በእግዚአብሔር ፊት ያቆማታል፤'),
  ('62fa408d-2ca6-557c-ac5f-d9fc3fd3577b', '3292ac15-0611-5d9b-a9a2-5c5c83ea6efe', 'adf67db6-1584-5aca-a4a3-8c6564a6762c', 21, 31, 'ካህኑም ይህን ሕግ ሁሉ ያደርግባታል። ሰውየውም ከኀጢአት ንጹሕ ይሆናል፤ ሴቲቱም ኀጢአቷን ትሸከማለች።”'),
  ('6e4fd5ab-11ff-5a17-a3e8-1dbee7835049', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('65e75c39-0815-5482-ac61-a28dc9f9c5a4', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 2, 2, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፤ ወንድ ወይም ሴት ለእግዚአብሔር ራሱን የተለየ ያደርግ ዘንድ ልዩ ስእለት ቢሳል፥'),
  ('f9c03cf6-dda8-5492-ac1e-4d6800e9e980', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 3, 3, 'ከወይን ጠጅና ከሚያሰክር መጠጥ ራሱን የተለየ ያድርግ፤ ከወይን ወይም ከሌላ ከሚያሰክር ነገር የሚገኘውን ሆምጣጤ አይጠጣ፤ የወይንም ጭማቂ አይጠጣ፤ የወይንም እሸት ወይም ዘቢብ አይብላ።'),
  ('ba496b8f-6254-5b8e-a918-e7012b7eeb3d', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 4, 4, 'ራሱን የተለየ ባደረገበት ወራት ሁሉ ከወይን የሆነውን ነገር ሁሉ ከውስጡ ፍሬ ጀምሮ እስከ ደረቀው ዘቢብ ድረስ አይብላ።'),
  ('f8ddb123-e29a-50d6-a204-47646e5f876f', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 5, 5, '“ራሱን ለመለየት ስእለት ባደረገበት ወራት ሁሉ ራሱን አይላጭ፤ ለእግዚአብሔር የተለየበት ወራት እስኪፈጸም ድረስ ቅዱስ ይሆናል፤ የራሱንም ጠጕር ያሳድጋል።'),
  ('b40c22d1-7302-52f4-a079-1971c7cc3128', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 6, 6, '“ለእግዚአብሔር ራሱን የተለየ ባደረገበት ወራት ሁሉ ወደ ሬሳ አይቅረብ።'),
  ('fcaac7ae-1df1-582d-a50e-d3feef512f55', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 7, 7, 'ለአምላኩ ያደረገው ብፅዐት በራሱ ላይ ነውና አባቱ፥ ወይም እናቱ፥ ወይም ወንድሙ፥ ወይም እኅቱ ሲሞቱ ሰውነቱን አያርክስባቸው።'),
  ('8f9914c8-6ba3-5327-a079-31041650729e', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 8, 8, 'በብፅዐቱ ወራት ሁሉ ለእግዚአብሔር የተቀደሰ ነውና።'),
  ('511518a6-966e-5c1d-a0f3-994bb5e99d67', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 9, 9, '“ሰውም በአጠገቡ ድንገት ቢሞት የራሱ ብፅዐት ይረክሳል፤ እርሱ በሚነጻበት ቀን ራሱን ይላጭ፤ በሰባተኛው ቀን ይላጨው።'),
  ('49ba7c73-6e40-5e6f-a8d2-50b6a3733ce8', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 10, 10, 'በስምንተኛውም ቀን ሁለት ዋኖሶች ወይም ሁለት የርግብ ግልገሎች ወደ ምስክሩ ድንኳን ደጃፍ ወደ ካህኑ ያምጣ፤'),
  ('1c986537-a8c4-50e3-aa00-9f826c7658cc', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 11, 11, 'ካህኑም አንዲቱን ለኀጢአት መሥዋዕት ሁለተኛዪቱንም ለሚቃጠል መሥዋዕት ያቀርባል፤ በሬሳም የተነሣ ኀጢአት ሠርቶአልና ያስተሰርይለታል፤ በዚያም ቀን ራሱን ይቀድሰዋል።'),
  ('15e05f39-9334-5d38-a9ba-370bcc7437b4', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 12, 12, 'በስእለቱ ወራትም ሁሉ ለእግዚአብሔር ይቀደሳል፤ የአንድ ዓመትም ተባት ጠቦት ለበደል መሥዋዕት ያምጣ፤ ስእለቱ ግን ረክሶአልና ያለፈው ወራት ሁሉ አይቈጠርለትም።'),
  ('402c8a67-9e98-521f-ae8f-f4104ac19bf1', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 13, 13, '“የተሳለው ሰው ሕግ ይህ ነው፤ የስእለቱ ወራት በተፈጸመ ጊዜ ራሱ ወደ ምስክሩ ድንኳን ደጃፍ ይቅረብ፤ ቍርባኑንም ለእግዚአብሔር ያቅርብ።'),
  ('ee9468ae-3f40-5d89-a937-4af7aada2255', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 14, 14, 'ነውር የሌለበት የአንድ ዓመት ተባት ጠቦት ለሚቃጠል መሥዋዕት፥ ነውርም የሌለባትን የአንድ ዓመት እንስት ጠቦት ለኀጢአት መሥዋዕት፥ ነውር የሌለበትን አውራ በግ ለደኅንነት መሥዋዕት፥'),
  ('957860b0-986c-5f03-aea3-8b632d05962c', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 15, 15, 'አንድ ሌማትም በዘይት የተለወሰ የስንዴ ቂጣ እንጀራ፥ በዘይትም የተቀባ ስስ ቂጣ፥ የእህሉንም ቍርባን፥ የመጠጡንም ቍርባን ያቅርብ።'),
  ('463771b6-bd13-5e11-a0e2-df9d392fb973', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 16, 16, 'ካህኑም በእግዚአብሔር ፊት ያቅርበው። የኀጢአቱንም መሥዋዕት የሚቃጠለውንም መሥዋዕት ያሳርግለታል።'),
  ('cf76f1be-ec01-5396-a79e-165b3cbd8956', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 17, 17, 'አውራውንም በግ ለደኅንነት መሥዋዕት ከሌማቱ ቂጣ እንጀራ ጋር ወደ እግዚአብሔር ያቀርባል፤ ካህኑም ደግሞ የእህሉን ቍርባንና የመጠጡን ቍርባን ያቀርባል።'),
  ('2530dde5-e60b-51d2-a508-fd187fa881b6', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 18, 18, 'የተሳለውም የተሳለውን የራስ ጠጕር በምስክሩ ድንኳን አጠገብ ይላጫል፤ የስእለቱንም ራስ ጠጕር ወስዶ ከደኅንነት መሥዋዕት በታች ወዳለው እሳት ይጥለዋል።'),
  ('1cfc1e25-51e2-5582-a937-66fcb7e9b359', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 19, 19, 'ካህኑም የተቀቀለውን የአውራውን በግ ወርች፥ ከሌማቱም አንድ ቂጣ እንጎቻ፥ አንድም ስስ ቂጣ ይወስዳል፤ የተሳለውንም የራስ ጠጕር ከተላጨ በኋላ በባለስእለቱ እጆች ላይ ያኖራቸዋል።'),
  ('b97f5663-0308-55cf-a8be-56d8fb5bae24', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 20, 20, 'ካህኑም እነዚህን ሁሉ ቍርባን አድርጎ በእግዚአብሔር ፊት ያቀርባል፤ ይህም የቍርባን ፍርምባና የመባው ወርች ለካህኑ የተቀደሰ ነው፤ ከዚያም በኋላ ባለስእለቱ ወይን ይጠጣል።'),
  ('2ec130aa-763f-545f-aedc-cd2ea2fb0562', 'ead99649-fe25-5d70-af10-24622106db06', 'e7e6d335-bb32-544f-aaa1-e84422b12874', 21, 21, '“ስእለቱን የተሳለው የባለስእለቱ፥ እጁም ከሚያገኘው ሌላ ስለ ስእለቱ ለእግዚአብሔር የሚያቀርበው የቍርባኑ ሕግ ይህ ነው፤ ስእለቱን እንደ ተሳለ እንደ ስእለቱ ሕግ እንዲሁ ያደርጋል።”'),
  ('b9c6fb10-8b0d-50c1-ae37-d84f903dbe31', 'ead99649-fe25-5d70-af10-24622106db06', 'ea8bde4a-bc2e-54df-a070-12a694e57cfd', 1, 22, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('58ddf902-9d18-5bba-a1cf-d80e2ce3e035', 'ead99649-fe25-5d70-af10-24622106db06', 'ea8bde4a-bc2e-54df-a070-12a694e57cfd', 2, 23, '“ለአሮንና ለልጆቹ ንገራቸው፤ የእስራኤልን ልጆች ስትባርኩአቸው እንዲህ በሉአቸው፦'),
  ('a1778cba-e5bb-5f5b-a395-3d1919e707bc', 'ead99649-fe25-5d70-af10-24622106db06', 'ea8bde4a-bc2e-54df-a070-12a694e57cfd', 3, 24, '“እግዚአብሔር ይባርክህ፥ ይጠብቅህም፤'),
  ('5e574f4b-5e81-5b3b-a870-5ea05db5d878', 'ead99649-fe25-5d70-af10-24622106db06', 'ea8bde4a-bc2e-54df-a070-12a694e57cfd', 4, 25, 'እግዚአብሔር ፊቱን ያብራልህ፥ ይራራልህም።'),
  ('3f6eba0f-f938-533a-a56e-6dd69deb362b', 'ead99649-fe25-5d70-af10-24622106db06', 'ea8bde4a-bc2e-54df-a070-12a694e57cfd', 5, 26, '“እግዚአብሔር ፊቱን ወደ አንተ ያንሣ፥ ሰላምንም ይስጥህ።'),
  ('362f7344-e8ac-5152-a4a9-3b70f9cbf62d', 'ead99649-fe25-5d70-af10-24622106db06', 'ea8bde4a-bc2e-54df-a070-12a694e57cfd', 6, 27, 'እንዲሁ ስሜን በእስራኤል ልጆች ላይ ይጠራሉ፤ እኔም እባርካቸዋለሁ።”'),
  ('0dbb485b-7935-5f3c-a156-6a9c0f7af729', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 1, 1, 'እንዲህም ሆነ፤ ሙሴ ድንኳኑን ፈጽሞ በተከለባት፥ እርስዋንና ዕቃዋን ሁሉ በቀባና በቀደሰባት፥ መሠዊያውንና ዕቃውንም ሁሉ በቀባና በቀደሰባት ቀን፥'),
  ('d05c9e95-80e2-5516-ab88-18631c86ca77', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 2, 2, 'ዐሥራ ሁለቱ የእስራኤል አለቆች፥ የአባቶቻቸው ቤቶች አለቆች፥ ቍርባናቸውን አቀረቡ፤ እነዚህም ከተቈጠሩት በላይ የተሾሙ የነገዶች አለቆች ነበሩ።'),
  ('1422bd98-a8a6-538a-afb6-ae9e3acae4e9', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 3, 3, 'መባቸውንም በእግዚአብሔር ፊት አቀረቡ፤ የተከደኑ ስድስት ሰረገሎች ዐሥራ ሁለትም በሬዎች፤ በየሁለቱም አለቆች አንድ ሰረገላ አቀረቡ፤ ሁሉም እያንዳንዱ አንድ በሬ በድንኳኑ ፊት አቀረቡ።'),
  ('9efcc06b-b491-5d7d-acf8-a0328ec6c9f4', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 4, 4, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('31126230-7d1b-54f5-a756-ea1063a5a123', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 5, 5, '“ለምስክሩ ድንኳን ሥራ የሚያገለግል ይሆን ዘንድ፥ ከእነርሱ ተቀብለህ ለሌዋውያን ለእያንዳንዱ እንደ አገልግሎታቸው ስጣቸው።”'),
  ('2b560284-97ce-5630-ad74-77a56fc944fe', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 6, 6, 'ሙሴም ሰረገሎችንና በሬዎችን ተቀብሎ ለሌዋውያን ሰጣቸው።'),
  ('5304ebcb-f2bf-594c-a9ce-dfde9ba1c94a', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 7, 7, 'ለጌድሶን ልጆች እንደ አገልግሎታቸው ሁለት ሰረገሎችንና አራት በሬዎችን ሰጣቸው።'),
  ('ff272d54-1456-539a-a1c8-95f60f6e3e22', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 8, 8, 'ከካህኑም ከአሮን ልጅ ከኢታምር እጅ በታች ላሉት ለሜራሪ ልጆች እንደ አገልግሎታቸው መጠን አራት ሰረገሎችንና ስምንት በሬዎችን ሰጣቸው።'),
  ('293ff6f5-2859-54fd-a95a-267f6989953c', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 9, 9, 'ለቀዓት ልጆች ግን መቅደሱን ማገልገል የእነርሱ ነውና፥ በትከሻቸውም ይሸከሙት ነበርና ምንም አልሰጣቸውም።'),
  ('aedf5724-c371-5228-a92a-ffb63a86c111', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 10, 10, 'መሠዊያውም በተቀባ ቀን አለቆቹ መሠዊያውን ለመቀደስ ቍርባንን አቀረቡ፤ አለቆችም መባቸውን በመሠዊያው ፊት አቀረቡ።'),
