  ('f3f88139-dcfb-589f-af86-08b40464e65c', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 70, 70, 'ለኀጢአትም መሥዋዕት አንድ አውራ ፍየል፤'),
  ('86d762b8-0350-5269-aa4a-ca3f8bc0293b', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 71, 71, 'ለደኅንነትም መሥዋዕት ሁለት ጊደሮች፥ አምስት አውራ በጎች፥ አምስት አውራ ፍየሎች፥ አምስት የአንድ ዓመት እንስት የበግ ጠቦቶች ነበረ፤ የአሚሳዲ ልጅ የአኪያዜር መባ ይህ ነበረ።'),
  ('eade8dd2-8846-5044-afe5-e8ebbefb338f', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 72, 72, 'በዐሥራ አንደኛውም ቀን የአሴር ልጆች አለቃ የኤክራን ልጅ ፋግኤል መባውን አቀረበ፤'),
  ('0c9551cd-4159-5cf6-ad6d-839625c81097', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 73, 73, 'መባውም ለእህል ቍርባን በዘይት የተለወሰ መልካም ዱቄት የተሞሉ፥ ሚዛኑ እንደ መቅደሱ ሰቅል ሚዛን መቶ ሠላሳ ሰቅል የሆነ አንድ የብር ወጭት፥ ሚዛኑም ሰባ ሰቅል የሆነ አንድ የብር ድስት፤'),
