  ('63e20117-fac0-530b-a56b-6d502f822789', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 76, 76, 'ለኀጢአትም መሥዋዕት አንድ አውራ ፍየል፤'),
  ('cfafd9b3-fcbe-5e9d-ada3-dad7afad8e16', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 77, 77, 'ለደኅንነትም መሥዋዕት ሁለት ጊደሮች፥ አምስት አውራ በጎች፥ አምስት አውራ ፍየሎች፥ አምስት የአንድ ዓመት እንስት የበግ ጠቦቶች ነበረ፤ የኤክራን ልጅ የፋግኤል መባ ይህ ነበረ።'),
  ('23cf3349-ebbc-557c-acb1-69155cd0c6b0', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 78, 78, 'በዐሥራ ሁለተኛውም ቀን የንፍታሌም ልጆች አለቃ የዔናን ልጅ አኪሬ መባውን አቀረበ፤'),
  ('725734c6-f853-570f-a5a9-d13a8d11d526', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 79, 79, 'መባውም ለእህል ቍርባን በዘይት የተለወሰ መልካም ዱቄት የተሞሉ፥ ሚዛኑ እንደ መቅደሱ ሰቅል ሚዛን መቶ ሠላሳ ሰቅል የሆነ አንድ የብር ወጭት፥ ሚዛኑም ሰባ ሰቅል የሆነ አንድ የብር ድስት፤'),
  ('5b164b03-44d7-559d-a9da-3386dfd9d3af', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 80, 80, 'ዕጣንም የተሞላ ሚዛኑ ዐሥር ሰቅል የሆነ አንድ የወርቅ ጭልፋ፤'),
  ('b887252a-bf5a-5814-ab94-8b41eadcf664', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 81, 81, 'ለሚቃጠልም መሥዋዕት አንድ ወይፈን፥ አንድ አውራ በግ፥ አንድ የአንድ ዓመት ተባት የበግ ጠቦት፤'),
  ('9ee97a8a-ab14-5bea-a6b3-d6e455f3cf34', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 82, 82, 'ለኀጢአትም መሥዋዕት አንድ አውራ ፍየል፤'),
  ('769d0916-6af8-5ea0-a2a2-393666690cc0', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 83, 83, 'ለደኅንነትም መሥዋዕት ሁለት ጊደሮች፥ አምስት አውራ በጎች፥ አምስት አውራ ፍየሎች፥ አምስት የአንድ ዓመት እንስት የበግ ጠቦቶች ነበረ፤ የዔናን ልጅ የአኪሬ መባ ይህ ነበረ።'),
  ('e214c330-4b22-504f-afb0-e68813ea5fbd', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 84, 84, 'መሠዊያው በተቀባ ቀን የእስራኤል ልጆች አለቆች ለመሠዊያው መቀደሻ ያቀረቡት መባ ይህ ነበረ፤ ዐሥራ ሁለት የብር ወጭቶች፥ ዐሥራ ሁለት የብር ድስቶች፥ ዐሥራ ሁለት የወርቅ ጭልፋዎች፤'),
  ('475f31bb-24d7-53e0-ad5e-a25feda6c045', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 85, 85, 'እያንዳንዱም የብር ወጭት መቶ ሠላሳ ሰቅል፥ እያንዳንዱም ድስት ሰባ ሰቅል ነበረ፤ የዚህም ዕቃ ሁሉ ብር በመቅደሱ ሰቅል ሚዛን ሁለት ሺህ አራት መቶ ሰቅል ነበረ።'),
  ('1f032868-8836-5ff5-ad99-8c3aa4562ff3', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 86, 86, 'ዕጣንም የተሞሉ ዐሥራ ሁለት የወርቅ ጭልፋዎች፥ እያንዳንዱ በመቅደሱ ሰቅል ሚዛን ዐሥር ዐሥር ሰቅል ነበረ፤ የጭልፋዎቹ ወርቅ ሁሉ መቶ ሃያ ሰቅል ነበረ።'),
  ('88aa51a5-e744-5b95-a8ad-f4b5abc5fdc3', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 87, 87, 'የሚቃጠለው መሥዋዕት ከብት ሁሉ ከእህሉ ቍርባን ጋር ዐሥራ ሁለት ወይፈኖች፥ ዐሥራ ሁለትም አውራ በጎች፥ ዐሥራ ሁለትም የአንድ ዓመት ተባት የበግ ጠቦቶች ነበሩ፤ የኀጢአትም መሥዋዕት አውራ ፍየሎች ዐሥራ ሁለት ነበሩ።'),
  ('f250cbfc-1505-59d7-ac37-3b5872ff18d4', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 88, 88, 'የደኅንነትም መሥዋዕት ከብት ሁሉ፥ ሃያ አራት ጊደሮች፥ ስድሳም አውራ በጎች፥ ስድሳም አውራ ፍየሎች፥ ስድሳም ነውር የሌለባቸው የአንድ ዓመት እንስት የበግ ጠቦቶች ነበሩ። መሠዊያው ከተቀባ በኋላ ለመቀደሻው የቀረበ ቍርባን ይህ ነበረ።'),
  ('35430af8-3ce9-56e7-aa79-be6fa0c16dd2', '468a4f50-9872-590d-aaae-d595c20ba2bc', 'a652a0df-b6e1-5bb0-a241-920f8156d9ea', 89, 89, 'ሙሴም ወደ ምስክሩ ድንኳን እርሱን ለመነጋገር በገባ ጊዜ በቃል ኪዳኑ ታቦት ላይ ካለው ከስርየት መክደኛው በላይ ከኪሩቤልም መካከል የእግዚአብሔርን ድምፅ ይሰማ ነበር፤ ከእርሱም ጋር ይናገር ነበር።'),
  ('2e5ac2ad-5ec5-5ab8-a816-b2e1659315ac', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '8bcf2e8f-1bff-5496-a7f0-5b67318a0cb7', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('77aa5469-aacc-5f05-aa73-dc9555f21280', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '8bcf2e8f-1bff-5496-a7f0-5b67318a0cb7', 2, 2, '“መብራቶቹን ስታበራ ሰባቱ መብራቶች በመቅረዙ ፊት ያበራሉ ብለህ ለአሮን ንገረው።”'),
  ('08cbd3f4-fcdb-54d7-a16a-45a30f4174fe', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '8bcf2e8f-1bff-5496-a7f0-5b67318a0cb7', 3, 3, 'አሮንም እንዲሁ አደረገ፤ እግዚአብሔር ሙሴን እንዳዘዘ በመቅረዙ ፊት መብራቶቹን አበራ።'),
  ('0672d8da-1d93-5ed2-aace-c4f69f94da3a', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '8bcf2e8f-1bff-5496-a7f0-5b67318a0cb7', 4, 4, 'የመቅረዝዋም ሥራዋ እንዲህ ነበረ። ሁለንተናቸው ወርቅ የሆነ አፅቆችዋ ሥረ-ወጥ ነበሩ፤ አበቦችዋም ሁለንተናቸው ሥረ-ወጥ ነበሩ። እግዚአብሔር ሙሴን እንዳሳየው ምሳሌ መቅረዝዋን እንዲሁ አደረገ።'),
  ('499bc101-4938-52cb-ad72-1b6923079458', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 1, 5, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('a93e7ad5-3f7d-5b6c-a364-e2a9216f9ff7', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 2, 6, '“ከእስራኤል ልጆች መካከል ሌዋውያንን ወስደህ አንጻቸው።'),
  ('94cf23e0-61f1-531c-a4c8-2597a196852c', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 3, 7, 'ታነጻቸው ዘንድ እንዲህ ታደርግላቸዋለህ፤ በማንጻት ውኃ ትረጫቸዋለህ፤ ሰውነታቸውን ሁሉ ይላጩ፤ ልብሳቸውንም ይጠቡ፤ ንጹሓንም ይሆናሉ።'),
  ('b2736584-0076-54bc-aefc-8a26d81f454b', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 4, 8, 'ከላሞች አንድ ወይፈን፥ ለእህሉም ቍርባን በዘይት የተለወሰ መልካም ዱቄትን ይውሰዱ፤ ሌላውንም የአንድ ዓመት ወይፈን ለኀጢአት መሥዋዕት ይውሰዱ።'),
  ('3bf98204-baee-5de9-a23b-271cf1c707eb', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 5, 9, 'ሌዋውያንንም በምስክሩ ድንኳን ፊት አቅርብ፤ የእስራኤልንም ልጆች ማኅበር ሁሉ ሰብስብ።'),
  ('da7e5a6e-60ba-52ab-aae6-566ac322bb5c', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 6, 10, 'ሌዋውያንንም በእግዚአብሔር ፊት አቅርባቸው፤ የእስራኤልም ልጆች በሌዋውያን ላይ እጃቸውን ይጫኑባቸው።'),
  ('d537f8ba-63be-54ef-af18-d29acb543d42', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 7, 11, 'አሮንም ሌዋውያን እግዚአብሔርን ያገለግሉ ዘንድ ከእስራኤል ልጆች መካከል ስጦታ አድርጎ፥ ሌዋውያንን በእግዚአብሔር ፊት ይለያቸዋል።'),
  ('d195f652-2d5f-5ffb-affc-1ce932de92a5', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 8, 12, 'ሌዋውያኑም በወይፈኖቹ ራሶች ላይ እጆቻቸውን ይጫኑ፤ ለሌዋውያንም ስለ ማስተስረያ አንዱን ለኀጢአት መሥዋዕት፥ ሁለተኛውንም ለሚቃጠል መሥዋዕት ለእግዚአብሔር አቅርብ።'),
  ('ca71d782-60d0-5101-a458-ec55b3f9868e', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 9, 13, 'ሌዋውያንንም በአሮንና በልጆቹ ፊት አቁማቸው፤ በእግዚአብሔርም ፊት ስጦታ አድርገህ አቅርባቸው።'),
  ('57dbf7bb-5083-5854-a3bf-3b7cfb6dfe29', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 10, 14, 'እንዲሁ ሌዋውያንን ከእስራኤል ልጆች መካከል ለይ፤ እነርሱም ለእኔ ይሁኑ።'),
  ('763af1da-4f08-5fd8-aca2-e40bd1f2dd4a', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 11, 15, '“ከዚያም በኋላ ሌዋውያን የምስክሩን ድንኳን አገልግሎት ያገለግሉ ዘንድ ይገባሉ፤ ታነጻቸውማለህ፤ ስጦታም አድርገህ በፊቴ ታቀርባቸዋለህ።'),
  ('600de1ae-d6dd-5656-ae36-7dc33a495c56', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 12, 16, 'እነርሱም ከእስራኤል ልጆች መካከል ፈጽሞ ለእኔ ተሰጥተዋልና በእስራኤል ልጆች በኵራት ሁሉ፥ መጀመሪያ በሚወለድ ሁሉ ፋንታ ለእኔ ወስጄአቸዋለሁ።'),
  ('2af69308-e299-59dd-a7ac-26119b641809', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 13, 17, 'በግብፅ ምድር ያለውን በኵር ሁሉ በገደልሁበት ቀን የእስራኤልን ልጆች በኵራት ሁሉ፥ ሰው ወይም እንስሳ፥ ለእኔ ቀድሼአቸዋለሁና የእኔ ናቸው።'),
  ('d0091608-ad89-5f7f-ac4a-6c30a29f5627', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 14, 18, 'በእስራኤልም ልጆች በኵር ሁሉ ፋንታ ሌዋውያንን ወስጄአለሁ።'),
  ('b5aaa1d2-41df-5528-ae5e-6854b50578ef', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 15, 19, 'ሌዋውያንንም ስጦታ አድርጌ አገባኋቸው፤ ልዩ በሆነች ድንኳን ውስጥ የእስራኤልን ልጆች ሥራ ይሠሩ ዘንድ፥ የእስራኤልንም ልጆች ኀጢአት ያቃልሉ ዘንድ ከእስራኤል ልጆች መካከል ለአሮንና ለልጆቹ ተሰጡ፤ ከእስራኤልም ልጆች ወደ መቅደስ የሚቀርብ አይኑር።”'),
  ('f2b9e5a5-2e27-517f-ac94-79f1fc9ef866', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 16, 20, 'ሙሴና አሮን የእስራኤልም ልጆች ማኅበር ሁሉ እንዲሁ በሌዋውያን ላይ አደረጉ፤ እግዚአብሔር ሙሴን ስለ ሌዋውያን እንዳዘዘው እንዲሁ የእስራኤል ልጆች አደረጉላቸው።'),
  ('cd8c7488-3064-5f97-ac3a-1210eea9a8e8', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 17, 21, 'ሌዋውያንም ከኀጢአት ራሳቸውን አነጹ፤ ልብሳቸውንም አጠቡ፤ አሮንም ስጦታ አድርጎ በእግዚአብሔር ፊት አቀረባቸው፤ አሮንም ያነጻቸው ዘንድ አስተሰረየላቸው።'),
  ('3e0b3285-93a2-53c8-a170-86bb2bee178f', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 18, 22, 'ከዚያም በኋላ ሌዋውያን በምስክሩ ድንኳን ውስጥ በአሮንና በልጆቹ ፊት አገልግሎታቸውን ይፈጽሙ ዘንድ ገቡ፤ እግዚአብሔር ሙሴን ስለ ሌዋውያን እንዳዘዘው እንዲሁ አደረጉላቸው።'),
  ('6847d3ed-3d98-5c96-afa8-abb3cf17e0fb', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 19, 23, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('fce26e55-215c-5733-a5fa-fe0c484dca0f', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 20, 24, '“የሌዋውያን ሕግ ይህ ነው፤ ከሃያ አምስት ዓመት ጀምሮ ከዚያም በላይ ያሉት እስከ አምሳ ዓመት ድረስ በምስክሩ ድንኳን ሥራ ያገለግሉ ዘንድ ይገባሉ።'),
  ('54a2398c-1e50-57ec-a4af-8bf6f1491685', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 21, 25, 'ከአምሳ ዓመት በኋላ ከሥራው ይሰናበት። ከዚያም ወዲያ እርሱ አያገልግል።'),
  ('a8a3de4f-2f16-5127-a305-c4c9549eee50', 'f76f3aa3-ee2d-59e1-a203-bb52ec7f6f5e', '3b78b9a0-006a-5751-aff2-16f18df3d72f', 22, 26, 'ወንድሙንም በምስክሩ ድንኳን ውስጥ ያገልግል፤ ሰሞናቸውንም ይጠብቅ። ነገር ግን አገልግሎቱን ይተው። እንዲሁ በየሰሞናቸው ለሌዋውያን ታደርጋለህ።”'),
  ('f5d653a5-0341-568f-ad22-d0947656f20f', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 1, 1, 'የእስራኤል ልጆች ከግብፅ ምድር በወጡ በሁለተኛው ዓመት በመጀመሪያው ወር በሲና ምድረ በዳ እግዚአብሔር ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('535d41bc-dbfa-59f9-ac26-75bcd174dfe4', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 2, 2, '“የእስራኤል ልጆች በጊዜው ፋሲካውን ያድርጉ።'),
  ('7f3b16f1-35da-5dfb-a522-6e7f1728c8f6', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 3, 3, 'በመጀመሪያው ወር በዐሥራ አራተኛው ቀን በመሸ ጊዜ በጊዜው አድርጉት፤ እንደ ሥርዐቱ ሁሉ እንደ ፍርዱም ሁሉ አድርጉት።”'),
  ('60e7875e-855c-54eb-a1e0-867477947559', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 4, 4, 'ሙሴም ፋሲካን ያደርጉ ዘንድ ለእስራኤል ልጆች ነገራቸው።'),
  ('98395228-1b82-5006-a8ba-679535c2ec25', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 5, 5, 'በመጀመሪያውም ወር በዐሥራ አራተኛው ቀን በሲና ምድረ በዳ ፋሲካን አደረጉ፤ እግዚአብሔር ሙሴን እንዳዘዘው እንዲሁ የእስራኤል ልጆች አደረጉ።'),
  ('81bf67a4-c3f3-5092-a47d-0ad51d0dcd45', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 6, 6, 'በሰውነታቸው ርኵሰት የነበረባቸው ሰዎች መጡ፤ ስለዚህም በዚያ ቀን ፋሲካን ያደርጉ ዘንድ አልቻሉም።'),
  ('90bce9ad-7f68-53f6-a27c-5e5e85b23a67', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 7, 7, 'በዚያም ቀን ወደ ሙሴና ወደ አሮን ቀረቡ። እነዚያም ሰዎች “እኛ በሰውነታችን ርኵሰት ያለብን ሰዎች ነን፤ በእስራኤል ልጆች መካከል በጊዜው ቍርባን ለእግዚአብሔር እንዳናቀርብ ስለ ምን እንከለከላለን?” አሉት።'),
  ('c86bceeb-4fd6-5a6c-a1aa-116cc4f41fce', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 8, 8, 'ሙሴም፥ “እግዚአብሔር ስለ እናንተ የሚያዝዘውን እስክሰማ ቈዩ” አላቸው።'),
  ('e5ae065b-3251-5a96-a5ad-704fb70ffdf6', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 9, 9, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('d35c0267-db88-5af7-a0e9-2b254a4778f5', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 10, 10, '“ለእስራኤል ልጆች እንዲህ ብለህ ንገራቸው፦ ከእናንተ ወይም ከትውልዶቻችሁ ዘንድ ማንኛውም ሰው በሰውነቱ ቢረክስ፥ ወይም ሩቅ መንገድ ቢሄድ፥ ወይም በተወለዳችሁበት ሀገር ያለም ቢሆን እርሱ ደግሞ ለእግዚአብሔር ፋሲካን ያድርግ።'),
  ('41fc960f-9801-5fd5-a2af-9cfbd032c7a6', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 11, 11, 'በሁለተኛው ወር በዐሥራ አራተኛው ቀን በመሸ ጊዜ ያድርጉት፤ ከቂጣ እንጀራና ከመራራ ቅጠል ጋር ይብሉት።'),
  ('65993e95-4fda-5f23-a395-04fde36a5eae', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 12, 12, 'ከእርሱም እስከ ነገ ምንም አያስቀሩ፤ ከእርሱም አጥንትን አይስበሩ፤ እንደ ፋሲካ ሥርዐት ሁሉ ያድርጉት።'),
  ('a4e2e096-4778-5893-ab5b-2958e83d8ad9', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 13, 13, 'ነገር ግን ንጹሕ የሆነ ሰው በመንገድም ላይ ያልሆነ ፋሲካን ባያደርግ፥ ያ ሰው ከሕዝቡ ዘንድ ተለይቶ ይጠፋል፤ የእግዚአብሔርን ቍርባን በጊዜው አላቀረበምና ያ ሰው ኀጢአቱን ይሸከማል።'),
  ('87612af9-7eca-57ef-a02e-380bbc968c35', '481a5b9d-013b-5f3a-aad2-8898881730f6', 'cacb21e1-4410-5d2b-a893-2a7302a3cda0', 14, 14, 'ወደ አገራችሁ መጻተኛ ቢመጣ፥ የእግዚአብሔርን ፋሲካ እንደ ፋሲካው ሕግ እንደ ትእዛዙም ያድርግ፤ ለመጻተኛና ለሀገር ልጅ አንድ ሥርዐት ይሁንላችሁ።”'),
  ('ec327852-9f07-5c98-a77c-24a25446010e', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 1, 15, 'ድንኳንዋን በተከሉበት ቀን ደመናው የምስክሩን ድንኳን ሸፈናት፤ ከማታም ጀምሮ እስከ ጥዋት ድረስ በድንኳኑ ላይ እንደ እሳት ይመስል ነበር።'),
  ('4ec7de0d-ec0f-57eb-a7fc-ba43f5e5b41d', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 2, 16, 'እንዲሁ ሁልጊዜ ነበረ፤ በቀን ደመና፥ በሌሊትም የእሳት አምሳል ይሸፍናት ነበር።'),
  ('39b1a464-ce2c-5d65-a0d7-2c8d35a64e29', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 3, 17, 'ደመናውም ከድንኳኑ ላይ በተነሣ ጊዜ በዚያን ጊዜ የእስራኤል ልጆች ይጓዙ ነበር፤ ደመናውም በቆመበት ስፍራ በዚያ የእስራኤል ልጆች ይሰፍሩ ነበር።'),
  ('1f321080-360b-5bd4-accf-4bb622b2e009', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 4, 18, 'በእግዚአብሔር ትእዛዝ የእስራኤል ልጆች ይጓዙ ነበር፤ በእግዚአብሔርም ትእዛዝ ይሰፍሩ ነበር፤ ደመናው በድንኳኑ ላይ በተቀመጠበት ዘመን ሁሉ በሰፈራቸው ይቀመጡ ነበር።'),
  ('33aba84e-c372-5a00-a6f1-4625790d7a42', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 5, 19, 'ደመናውም በድንኳኑ ላይ ብዙ ቀን በተቀመጠ ጊዜ የእስራኤል ልጆች የእግዚአብሔርን ትእዛዝ ይጠብቁ ነበር፤ አይጓዙምም ነበር።'),
  ('f10c7b39-9bec-5bc3-a0f7-cf6c9e2a2a2c', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 6, 20, 'ደመናው ድንኳኑን በጋረደበት ቀን ቍጥር ሁሉ የእስራኤል ልጆች በእግዚአብሔር ቃል ይሰፍሩ፥ በእግዚአብሔርም ትእዛዝ ይጓዙ ነበር።'),
  ('be083f88-b2cc-5eaa-a6ad-1b00edfa194e', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 7, 21, 'አንዳንድ ጊዜም ደመናው ከማታ ጀምሮ እስከ ጥዋት ድረስ ይቀመጥ ነበር፤ በጥዋትም ደመናው በተነሣ ጊዜ ይጓዙ ነበር። በቀንም በሌሊትም ቢሆን ደመናው በተነሣ ጊዜ ይጓዙ ነበር'),
  ('6f206c41-d435-5f18-a3b1-b2668097b86f', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 8, 22, 'ደመናውም እስከ ወር ቈይቶ በድንኳኑ ላይ ቢቀመጥ የእስራኤል ልጆች በሰፈራቸው ይቀመጡ ነበር፤ አይጓዙምም ነበር፤ ነገር ግን በተነሣ ጊዜ ይጓዙ ነበር።'),
  ('a05ad02f-479d-513e-a25b-b70d8393abce', '481a5b9d-013b-5f3a-aad2-8898881730f6', '21a48f5c-5f7a-55d1-aaf7-cb806204899a', 9, 23, 'በእግዚአብሔር ትእዛዝ ይሰፍሩ ነበር፤ በእግዚአብሔርም ትእዛዝ ይጓዙ ነበር፤ እግዚአብሔር በሙሴ ቃል እንደ አዘዘ የእግዚአብሔርን ትእዛዝ ይጠብቁ ነበር።'),
  ('484e246e-b1d6-5435-a87b-75d87925a010', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 1, 1, 'እግዚአብሔርም ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('8349fa3b-be66-5d00-a964-44471deebd95', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 2, 2, '“ሁለት የብር መለከቶች አስጠፍጥፈህ ለአንተ አድርግ፤ ማኅበሩን ለመጥራት ከሰፈራቸውም ለማስጓዝ ይሁኑልህ።'),
  ('8a140a63-57c3-536e-a326-2cb020da1da0', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 3, 3, 'ሁለቱም መለከቶች በተነፉ ጊዜ ማኅበሩ ሁሉ ወደ አንተ ወደ ምስክሩ ድንኳን ይሰብሰቡ።'),
  ('2aa6dbb3-eeeb-5f84-a9d3-1c716515ed65', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 4, 4, 'አንድ መለከት ሲነፋ ታላላቆቹ የእስራኤል አእላፍ አለቆች ወደ አንተ ይሰብሰቡ።'),
  ('3500bf2a-1bf2-5e66-a2fe-2a55bec47808', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 5, 5, 'መለከቱንም በምልክት ስትነፉ በምሥራቅ በኩል የሰፈሩት ይጓዙ።'),
  ('d6c99f34-29ef-5346-a400-7865674503dd', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 6, 6, 'ሁለተኛውንም በምልክቱ ስትነፉ በአዜብ በኩል የሰፈሩት ይጓዙ፤ ሦስተኛውንም በምልክቱ በነፋችሁ ጊዜ በባሕር በኩል የሰፈሩት ይጓዙ፤ አራተኛውንም በምልክቱ በነፋችሁ ጊዜ በመስዕ በኩል የሰፈሩት ሠራዊት ይጓዙ፤ ለማስጓዝ በምልክት ትነፉታላችሁ።'),
  ('a038156f-28b1-5f28-a914-dbe9218f460a', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 7, 7, 'ጉባኤውም በሚሰበሰብበት ጊዜ ያለ ምልክት ትነፉታላችሁ።'),
  ('d5798b3f-a65b-5cac-adff-e52f5f046b17', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 8, 8, 'የአሮንም ልጆች ካህናቱ መለከቱን ይንፉ፤ ይህም ለልጅ ልጃችሁ ለዘለዓለም ሥርዐት ይሁንላችሁ።'),
  ('783a2cc3-e271-5a19-ade6-33e288c6058f', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 9, 9, 'በሚገፋችሁም ጠላት ላይ በምድራችሁ ወደ ሰልፍ ስትወጡ በምልክት መለከቶችን ንፉ፤ በእግዚአብሔርም በአምላካችሁ ፊት ትታሰባላችሁ፤ ከጠላቶቻችሁም ትድናላችሁ።'),
  ('b30fe3eb-c590-5557-a71e-3db342e73d7e', '936de3bf-6257-57fd-a317-f333a7dce57e', 'b03e5657-4165-52f9-adac-b58d69f9f3bd', 10, 10, 'ደግሞ በደስታችሁ ቀን፥ በበዓላታችሁም ዘመን፥ በወርም መባቻ፥ በሚቃጠልም መሥዋዕታችሁና በደኅንነት መሥዋዕታችሁ ላይ መለከቶችን ንፉ፤ እነርሱም በአምላካችሁ ፊት ለመታሰቢያ ይሆኑላችኋል፤ እኔ እግዚአብሔር አምላካችሁ ነኝና።”'),
  ('70848326-bf32-592b-a774-bbc8119f6e0e', '936de3bf-6257-57fd-a317-f333a7dce57e', '6fe09823-ddcf-5bd4-a7db-584db5d76492', 1, 11, 'በሁለተኛውም ዓመት በሁለተኛው ወር ከወሩም በሃያኛው ቀን እንዲህ ሆነ፤ ደመናው ከምስክሩ ድንኳን ላይ ተነሣ።')
